-- Locação — modelos de contrato por garantia, editáveis por imobiliária, + apólice anexável que trava a entrega das
-- chaves (t_d08cfeee, Pacote 4 do plano t_55cd3848; pedidos de Denis 16/11, tópico 6238).
--
-- Rollback: supabase/rollback/20261201120000_locacao_modelos_contrato.sql
-- Teste:    supabase/tests/run-locacao-modelos.sh (homologação, transação desfeita; nunca produção).
--
-- O que muda:
--  * Tabela nova locacao_modelos: os 8 modelos (fiador, caução em dinheiro, caução de imóvel/caucionamento, seguro-fiança
--    Porto, Pottencial, Tokio Marine, Almada e Loft) nascem como PADRÃO DO SISTEMA (organization_id NULL) com os textos
--    enviados por Denis, já sem nenhum dado de cliente. Cada imobiliária edita a SUA cópia: cada salvamento é uma
--    versão nova (v1, v2…) com data e autor; voltar a uma versão antiga grava uma versão nova com aquele texto.
--    Edita: setor de contratos e administrador da imobiliária. Corretor não edita nem lê pela tela de modelos.
--  * Cláusulas da seguradora/Loft ficam marcadas (trava): mudar esse texto exige confirmação explícita.
--  * O editor só aceita campos [ ] conhecidos e exige os blocos automáticos ([[LOCADOR]], [[OBJETO]], …).
--  * "Montar contrato" passa a valer para fiador, caução, caucionamento, seguro-fiança e Loft (residencial ou
--    comercial: o modelo troca o bloco de destinação). Título de capitalização segue com a minuta anexada.
--  * Cada minuta "gerada" guarda o modelo e a versão de texto usados; se o modelo mudar no meio, o banco recusa.
--  * Dados do contrato ganham campos por garantia (seguradora/apólice, caução, caucionante e imóvel caucionado, Loft).
--    Não travam o envio à Conferência (trava continua só no residencial com fiador); travam só a geração do PDF.
--  * Tabela nova locacao_anexos: apólice do seguro-fiança (e termos da Loft), anexável antes ou depois da assinatura
--    pelo corretor, setor de contratos ou vistoria. Seguro-fiança sem apólice: a ENTREGA DAS CHAVES é recusada.
--  * Nada é apagado; nenhuma locação existente é alterada. Nada é publicado por esta migration.
BEGIN;
SELECT set_config('lock_timeout', '5s', true);

-- 1) Tabelas --------------------------------------------------------------------------------------------------------
-- Modelos de contrato. organization_id NULL = padrão do sistema (textos enviados por Denis); cada imobiliária grava as
-- suas versões (v1, v2…) por cima do padrão. Uma versão nunca é alterada: editar ou restaurar cria uma versão nova.
CREATE TABLE IF NOT EXISTS public.locacao_modelos (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE,
  chave text NOT NULL CONSTRAINT locacao_modelos_chave_check CHECK (chave IN ('fiador', 'caucao_dinheiro', 'caucao_imovel',
    'seguro_porto', 'seguro_pottencial', 'seguro_tokio', 'seguro_almada', 'loft')),
  versao integer NOT NULL CONSTRAINT locacao_modelos_versao_check CHECK (versao >= 1),
  titulo text NOT NULL CONSTRAINT locacao_modelos_titulo_check CHECK (length(titulo) BETWEEN 1 AND 120),
  tipo text NOT NULL CONSTRAINT locacao_modelos_tipo_check CHECK (tipo IN ('residencial', 'comercial')),
  garantia text NOT NULL,
  seguradora text,
  subtitulo text NOT NULL CONSTRAINT locacao_modelos_subtitulo_check CHECK (length(subtitulo) BETWEEN 1 AND 120),
  paragrafos jsonb NOT NULL CONSTRAINT locacao_modelos_paragrafos_check CHECK (jsonb_typeof(paragrafos) = 'array'),
  nota text CONSTRAINT locacao_modelos_nota_check CHECK (nota IS NULL OR length(nota) <= 300),
  restaurada_de integer,
  criado_por uuid,
  criado_em timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS locacao_modelos_org_versao ON public.locacao_modelos (organization_id, chave, versao)
  WHERE organization_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS locacao_modelos_padrao_versao ON public.locacao_modelos (chave, versao)
  WHERE organization_id IS NULL;

-- Anexos da locação que não são documento do corretor: apólice do seguro-fiança e termos da Loft. Podem entrar antes ou
-- depois da assinatura. Sem apólice, a entrega das chaves fica travada (decisão de Denis, 16/11).
CREATE TABLE IF NOT EXISTS public.locacao_anexos (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  locacao_id uuid NOT NULL REFERENCES public.locacoes(id) ON DELETE CASCADE,
  tipo text NOT NULL CONSTRAINT locacao_anexos_tipo_check CHECK (tipo IN ('apolice', 'loft_termos')),
  storage_path text NOT NULL CONSTRAINT locacao_anexos_path_unico UNIQUE,
  nome_arquivo text NOT NULL CONSTRAINT locacao_anexos_nome_check CHECK (length(nome_arquivo) BETWEEN 1 AND 200),
  numero text CONSTRAINT locacao_anexos_numero_check CHECK (numero IS NULL OR length(numero) BETWEEN 1 AND 60),
  enviado_por uuid,
  enviado_em timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS locacao_anexos_loc_idx ON public.locacao_anexos (locacao_id, tipo);

ALTER TABLE public.locacao_modelos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.locacao_anexos ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.locacao_modelos, public.locacao_anexos FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.locacao_modelos, public.locacao_anexos TO service_role;

-- Cada minuta gerada guarda o modelo e a versão de texto que usou (0 = padrão do sistema).
ALTER TABLE public.locacao_minutas ADD COLUMN IF NOT EXISTS modelo_chave text;
ALTER TABLE public.locacao_minutas ADD COLUMN IF NOT EXISTS modelo_versao integer;

-- 2) Funções internas -----------------------------------------------------------------------------------------------
-- Campos [ ] que o editor aceita (espelho de CAMPOS_MODELO no front; o teste confere as duas listas).
CREATE OR REPLACE FUNCTION public.locacao_modelo_campos() RETURNS text[]
LANGUAGE sql IMMUTABLE SET search_path TO '' AS $$
  SELECT ARRAY['NUMERO_CONTRATO', 'NOME_LOCADOR', 'NOME_LOCATARIO', 'NOME_FIADOR', 'IMOVEL_ENDERECO', 'VALOR_ALUGUEL',
    'VALOR_ALUGUEL_EXTENSO', 'DIA_VENCIMENTO', 'PRAZO_MESES', 'DATA_INICIO', 'DATA_TERMINO', 'CIDADE',
    'ADMINISTRADORA_QUALIFICACAO', 'FIADOR_IMOVEL_ENDERECO', 'FIADOR_MATRICULA', 'FIADOR_CARTORIO', 'CAUCAO_VALOR',
    'CAUCAO_VALOR_EXTENSO', 'CAUCAO_MESES', 'CAUCAO_FORMA', 'CAUCAO_FAVORECIDO', 'CAUCIONANTE_QUALIFICACAO',
    'CAUCAO_IMOVEL_DESCRICAO', 'CAUCAO_IMOVEL_CARTORIO', 'CAUCAO_IMOVEL_MATRICULA', 'SEGURADORA', 'APOLICE_NUMERO',
    'APOLICE_REFERENCIA', 'LOFT_REFERENCIA']::text[]
$$;

-- Blocos automáticos ([[...]]) que precisam existir em todo modelo.
CREATE OR REPLACE FUNCTION public.locacao_modelo_blocos() RETURNS text[]
LANGUAGE sql IMMUTABLE SET search_path TO '' AS $$
  SELECT ARRAY['LOCADOR', 'LOCATARIO', 'FIADOR', 'OBJETO', 'PRAZO', 'ADICIONAIS', 'ASSINATURAS']::text[]
$$;

-- Qual modelo serve para qual garantia da locação (espelho de MODELOS_DA_GARANTIA no front).
CREATE OR REPLACE FUNCTION public.locacao_modelo_garantia_ok(_garantia text, _chave text) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path TO '' AS $$
  SELECT coalesce(CASE _garantia
    WHEN 'fiador' THEN _chave = 'fiador'
    WHEN 'caucao' THEN _chave IN ('caucao_dinheiro', 'caucao_imovel')
    WHEN 'outras' THEN _chave = 'caucao_imovel'
    WHEN 'seguro_fianca' THEN _chave IN ('seguro_porto', 'seguro_pottencial', 'seguro_tokio', 'seguro_almada')
    WHEN 'loft' THEN _chave = 'loft'
    ELSE false END, false)
$$;

-- Versão vigente de um modelo na imobiliária: a última dela; sem edição, o padrão do sistema.
CREATE OR REPLACE FUNCTION public.locacao_modelo_atual(_org uuid, _chave text) RETURNS public.locacao_modelos
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$
  SELECT m FROM public.locacao_modelos m
   WHERE m.chave = _chave AND (m.organization_id = _org OR m.organization_id IS NULL)
   ORDER BY (m.organization_id IS NULL), m.versao DESC LIMIT 1
$$;

CREATE OR REPLACE FUNCTION public.locacao_modelo_json(_m public.locacao_modelos) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$
  SELECT jsonb_build_object('chave', _m.chave, 'titulo', _m.titulo, 'tipo', _m.tipo, 'garantia', _m.garantia,
    'seguradora', _m.seguradora, 'subtitulo', _m.subtitulo, 'paragrafos', _m.paragrafos,
    'versao', CASE WHEN _m.organization_id IS NULL THEN 0 ELSE _m.versao END,
    'padrao', _m.organization_id IS NULL, 'nota', _m.nota, 'criado_em', _m.criado_em,
    'autor', (SELECT p.nome FROM public.profiles p WHERE p.id = _m.criado_por))
$$;

-- Quem edita e usa os modelos: setor de contratos (inclui administrador da imobiliária).
CREATE OR REPLACE FUNCTION public.locacao_modelo_exige() RETURNS uuid
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _org uuid := public.locacao_ctx();
BEGIN
  IF NOT public.locacao_tem_papel(auth.uid(), 'contratos') THEN
    RAISE EXCEPTION 'Só o setor de contratos ou o administrador mexe nos modelos de contrato.' USING ERRCODE = '42501';
  END IF;
  RETURN _org;
END $$;

-- Valida a lista de parágrafos que vai virar versão nova. Devolve a lista limpa (só as chaves conhecidas).
CREATE OR REPLACE FUNCTION public.locacao_modelo_validar(_chave text, _p jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path TO '' AS $$
DECLARE _e jsonb; _t text; _out jsonb := '[]'::jsonb; _ids text[] := ARRAY[]::text[]; _x text; _bl text[] := ARRAY[]::text[];
BEGIN
  IF _p IS NULL OR jsonb_typeof(_p) <> 'array' OR jsonb_array_length(_p) < 5 OR jsonb_array_length(_p) > 400 THEN
    RAISE EXCEPTION 'Modelo inválido: lista de cláusulas vazia ou grande demais.' USING ERRCODE = '22023';
  END IF;
  FOR _e IN SELECT value FROM jsonb_array_elements(_p) LOOP
    IF jsonb_typeof(_e) <> 'object' OR jsonb_typeof(_e->'t') IS DISTINCT FROM 'string' OR jsonb_typeof(_e->'id') IS DISTINCT FROM 'string'
       OR (_e ? 'trava' AND jsonb_typeof(_e->'trava') <> 'boolean')
       OR (_e ? 'dest' AND (_e->>'dest') NOT IN ('residencial', 'comercial'))
       OR (_e ? 'cond' AND (_e->>'cond') NOT IN ('isencao_multa'))
       OR (_e->>'id') !~ '^[a-z0-9_-]{1,24}$' THEN
      RAISE EXCEPTION 'Modelo inválido: cláusula mal formada.' USING ERRCODE = '22023';
    END IF;
    _t := btrim(_e->>'t');
    IF length(_t) < 1 OR length(_t) > 8000 THEN
      RAISE EXCEPTION 'Cláusula vazia ou longa demais (máx. 8.000 caracteres).' USING ERRCODE = '22023';
    END IF;
    IF (_e->>'id') = ANY (_ids) THEN RAISE EXCEPTION 'Modelo inválido: cláusula repetida.' USING ERRCODE = '22023'; END IF;
    _ids := _ids || (_e->>'id');
    -- Bloco automático: parágrafo que é só [[NOME]].
    IF _t ~ '^\[\[[A-Z_]+\]\]$' THEN
      _x := substring(_t FROM 3 FOR length(_t) - 4);
      IF NOT (_x = ANY (public.locacao_modelo_blocos())) THEN
        RAISE EXCEPTION 'Bloco automático desconhecido: [[%]]', _x USING ERRCODE = '22023';
      END IF;
      IF _x = ANY (_bl) THEN RAISE EXCEPTION 'Bloco automático repetido: [[%]]', _x USING ERRCODE = '22023'; END IF;
      _bl := _bl || _x;
    ELSIF _t ~ '\[\[' THEN
      RAISE EXCEPTION 'Bloco automático [[...]] tem de ficar sozinho no parágrafo.' USING ERRCODE = '22023';
    ELSE
      FOR _x IN SELECT (regexp_matches(_t, '\[([A-Z_]+)\]', 'g'))[1] LOOP
        IF NOT (_x = ANY (public.locacao_modelo_campos())) THEN
          RAISE EXCEPTION 'Campo que não existe: [%]. Use um dos campos da lista.', _x USING ERRCODE = '22023';
        END IF;
      END LOOP;
    END IF;
    _out := _out || jsonb_strip_nulls(jsonb_build_object('id', _e->>'id', 't', _t,
      'trava', CASE WHEN coalesce((_e->>'trava')::boolean, false) THEN true END, 'dest', _e->>'dest', 'cond', _e->>'cond'));
  END LOOP;
  FOREACH _x IN ARRAY ARRAY['LOCADOR', 'LOCATARIO', 'OBJETO', 'PRAZO', 'ASSINATURAS']
                 || CASE WHEN _chave = 'fiador' THEN ARRAY['FIADOR'] ELSE ARRAY[]::text[] END LOOP
    IF NOT (_x = ANY (_bl)) THEN
      RAISE EXCEPTION 'Falta o bloco automático [[%]] (dados que o sistema preenche).', _x USING ERRCODE = '22023';
    END IF;
  END LOOP;
  RETURN _out;
END $$;

-- Parte "exigida pela seguradora" (parágrafos travados) — se mudar, exige confirmação explícita.
CREATE OR REPLACE FUNCTION public.locacao_modelo_travados(_p jsonb) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path TO '' AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', e->>'id', 't', e->>'t') ORDER BY n), '[]'::jsonb)
    FROM jsonb_array_elements(_p) WITH ORDINALITY AS x(e, n) WHERE coalesce((e->>'trava')::boolean, false)
$$;

CREATE OR REPLACE FUNCTION public.locacao_modelo_gravar(_org uuid, _chave text, _p jsonb, _nota text, _confirma boolean,
  _restaurada_de integer) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _base public.locacao_modelos; _novo public.locacao_modelos; _v integer; _limpo jsonb;
BEGIN
  -- Uma gravação por vez por imobiliária+modelo (duas pessoas salvando juntas não pegam o mesmo número).
  PERFORM pg_advisory_xact_lock(hashtextextended(_org::text || ':' || _chave, 0));
  _base := public.locacao_modelo_atual(_org, _chave);
  IF _base.id IS NULL THEN RAISE EXCEPTION 'Modelo desconhecido.' USING ERRCODE = '22023'; END IF;
  _limpo := public.locacao_modelo_validar(_chave, _p);
  IF _limpo = _base.paragrafos THEN
    RAISE EXCEPTION 'Nada mudou em relação à versão atual.' USING ERRCODE = '22023';
  END IF;
  IF public.locacao_modelo_travados(_limpo) IS DISTINCT FROM public.locacao_modelo_travados(_base.paragrafos)
     AND NOT coalesce(_confirma, false) THEN
    RAISE EXCEPTION 'Texto exigido pela seguradora/Loft mudou: confirme que o novo texto veio da própria seguradora.'
      USING ERRCODE = '22023';
  END IF;
  SELECT coalesce(max(versao), 0) + 1 INTO _v FROM public.locacao_modelos WHERE organization_id = _org AND chave = _chave;
  INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo,
    paragrafos, nota, restaurada_de, criado_por)
  VALUES (_org, _chave, _v, _base.titulo, _base.tipo, _base.garantia, _base.seguradora, _base.subtitulo, _limpo,
    left(nullif(btrim(coalesce(_nota, '')), ''), 300), _restaurada_de, auth.uid())
  RETURNING * INTO _novo;
  RETURN public.locacao_modelo_json(_novo);
END $$;

CREATE OR REPLACE FUNCTION public.locacao_tem_apolice(_loc uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$
  SELECT EXISTS (SELECT 1 FROM public.locacao_anexos a WHERE a.locacao_id = _loc AND a.tipo = 'apolice')
$$;

-- Anexa apólice/termos: corretor dono, setor de contratos ou vistoria (administrador também), da minuta em diante.
CREATE OR REPLACE FUNCTION public.locacao_anexo_exige(_l public.locacoes, _tipo text) RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $$
BEGIN
  IF _l.etapa NOT IN ('minuta', 'assinatura', 'pos_assinatura', 'chaves', 'comissao') THEN
    RAISE EXCEPTION 'A apólice entra a partir da etapa Minuta.' USING ERRCODE = '22023';
  END IF;
  IF _tipo IS NULL OR NOT ((_tipo = 'apolice' AND _l.garantia = 'seguro_fianca') OR (_tipo = 'loft_termos' AND _l.garantia = 'loft')) THEN
    RAISE EXCEPTION 'Anexo não se aplica a esta garantia.' USING ERRCODE = '22023';
  END IF;
  IF _l.corretor_id = auth.uid() THEN RETURN 'corretor'; END IF;
  IF public.locacao_tem_papel(auth.uid(), 'contratos') THEN RETURN 'contratos'; END IF;
  IF public.locacao_tem_papel(auth.uid(), 'vistoria') THEN RETURN 'vistoria'; END IF;
  RAISE EXCEPTION 'Só o corretor da locação, o setor de contratos ou a vistoria anexam a apólice.' USING ERRCODE = '42501';
END $$;

REVOKE ALL ON FUNCTION public.locacao_modelo_campos(), public.locacao_modelo_blocos(),
  public.locacao_modelo_garantia_ok(text, text), public.locacao_modelo_atual(uuid, text),
  public.locacao_modelo_json(public.locacao_modelos), public.locacao_modelo_exige(), public.locacao_modelo_validar(text, jsonb),
  public.locacao_modelo_travados(jsonb), public.locacao_modelo_gravar(uuid, text, jsonb, text, boolean, integer),
  public.locacao_tem_apolice(uuid), public.locacao_anexo_exige(public.locacoes, text) FROM PUBLIC, anon, authenticated;

-- 3) RPCs dos modelos (tela "Modelos de contrato" e "Montar contrato") ----------------------------------------------
CREATE OR REPLACE FUNCTION public.locacao_modelos_listar() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _org uuid := public.locacao_modelo_exige();
BEGIN
  RETURN (SELECT coalesce(jsonb_agg(public.locacao_modelo_json(public.locacao_modelo_atual(_org, p.chave)) - 'paragrafos'
      || jsonb_build_object('versoes', (SELECT count(*) FROM public.locacao_modelos o WHERE o.organization_id = _org
                                          AND o.chave = p.chave))
      ORDER BY array_position(ARRAY['fiador', 'caucao_dinheiro', 'caucao_imovel', 'seguro_porto', 'seguro_pottencial',
        'seguro_tokio', 'seguro_almada', 'loft'], p.chave)), '[]'::jsonb)
    FROM (SELECT DISTINCT chave FROM public.locacao_modelos WHERE organization_id IS NULL) p);
END $$;

-- _versao NULL = vigente; 0 = padrão do sistema; N = versão N da imobiliária.
CREATE OR REPLACE FUNCTION public.locacao_modelo_ler(_chave text, _versao integer DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _org uuid := public.locacao_modelo_exige(); _m public.locacao_modelos;
BEGIN
  IF _versao IS NULL THEN _m := public.locacao_modelo_atual(_org, _chave);
  ELSIF _versao = 0 THEN
    SELECT * INTO _m FROM public.locacao_modelos WHERE organization_id IS NULL AND chave = _chave ORDER BY versao DESC LIMIT 1;
  ELSE
    SELECT * INTO _m FROM public.locacao_modelos WHERE organization_id = _org AND chave = _chave AND versao = _versao;
  END IF;
  IF _m.id IS NULL THEN RAISE EXCEPTION 'Modelo ou versão não encontrado.' USING ERRCODE = '22023'; END IF;
  RETURN public.locacao_modelo_json(_m);
END $$;

CREATE OR REPLACE FUNCTION public.locacao_modelo_historico(_chave text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _org uuid := public.locacao_modelo_exige();
BEGIN
  RETURN (SELECT coalesce(jsonb_agg(public.locacao_modelo_json(m) - 'paragrafos' || jsonb_build_object('restaurada_de', m.restaurada_de)
      ORDER BY (m.organization_id IS NULL), m.versao DESC), '[]'::jsonb)
    FROM public.locacao_modelos m WHERE m.chave = _chave AND (m.organization_id = _org OR m.organization_id IS NULL));
END $$;

CREATE OR REPLACE FUNCTION public.locacao_modelo_salvar(_chave text, _paragrafos jsonb, _nota text DEFAULT NULL,
  _confirma boolean DEFAULT false) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _org uuid := public.locacao_modelo_exige();
BEGIN
  RETURN public.locacao_modelo_gravar(_org, _chave, _paragrafos, _nota, _confirma, NULL);
END $$;

-- Voltar a uma versão anterior = gravar uma versão NOVA com o texto dela (o histórico não perde nada).
CREATE OR REPLACE FUNCTION public.locacao_modelo_restaurar(_chave text, _versao integer, _confirma boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _org uuid := public.locacao_modelo_exige(); _m public.locacao_modelos;
BEGIN
  IF _versao = 0 THEN
    SELECT * INTO _m FROM public.locacao_modelos WHERE organization_id IS NULL AND chave = _chave ORDER BY versao DESC LIMIT 1;
  ELSE
    SELECT * INTO _m FROM public.locacao_modelos WHERE organization_id = _org AND chave = _chave AND versao = _versao;
  END IF;
  IF _m.id IS NULL THEN RAISE EXCEPTION 'Versão não encontrada.' USING ERRCODE = '22023'; END IF;
  RETURN public.locacao_modelo_gravar(_org, _chave, _m.paragrafos,
    CASE WHEN _versao = 0 THEN 'Restaurado o padrão do sistema' ELSE 'Restaurada a v' || _versao END, _confirma, _versao);
END $$;

REVOKE ALL ON FUNCTION public.locacao_modelos_listar(), public.locacao_modelo_ler(text, integer),
  public.locacao_modelo_historico(text), public.locacao_modelo_salvar(text, jsonb, text, boolean),
  public.locacao_modelo_restaurar(text, integer, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.locacao_modelos_listar(), public.locacao_modelo_ler(text, integer),
  public.locacao_modelo_historico(text), public.locacao_modelo_salvar(text, jsonb, text, boolean),
  public.locacao_modelo_restaurar(text, integer, boolean) TO authenticated;

-- 4) Apólice / termos Loft: anexar (preparar → upload por URL assinada no servidor → registrar) e baixar ------------
CREATE OR REPLACE FUNCTION public.locacao_anexo_preparar(_id uuid, _tipo text, _ext text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _l public.locacoes := public.locacao_pega(_id);
BEGIN
  PERFORM public.locacao_anexo_exige(_l, _tipo);
  IF _ext IS NULL OR _ext NOT IN ('pdf', 'jpg', 'jpeg', 'png', 'webp') THEN
    RAISE EXCEPTION 'Envie a apólice em PDF ou imagem.' USING ERRCODE = '22023';
  END IF;
  RETURN jsonb_build_object('path', _l.organization_id::text || '/' || _l.id::text || '/anexos/'
    || gen_random_uuid()::text || '.' || _ext);
END $$;

CREATE OR REPLACE FUNCTION public.locacao_anexo_registrar(_id uuid, _tipo text, _path text, _nome text, _numero text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _l public.locacoes := public.locacao_pega(_id); _papel text; _novo uuid; _nm text;
  _num text := left(nullif(btrim(coalesce(_numero, '')), ''), 60);
BEGIN
  _papel := public.locacao_anexo_exige(_l, _tipo);
  IF _path IS NULL OR _path !~ ('^' || _l.organization_id::text || '/' || _l.id::text || '/anexos/[0-9a-f-]{36}[.](pdf|jpg|jpeg|png|webp)$')
     OR NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'locacao-documentos' AND o.name = _path) THEN
    RAISE EXCEPTION 'Arquivo não encontrado.' USING ERRCODE = '22023';
  END IF;
  IF (SELECT o.metadata->>'mimetype' FROM storage.objects o WHERE o.bucket_id = 'locacao-documentos' AND o.name = _path)
     IS DISTINCT FROM (CASE WHEN _path LIKE '%.pdf' THEN 'application/pdf' WHEN _path LIKE '%.png' THEN 'image/png'
       WHEN _path LIKE '%.webp' THEN 'image/webp' ELSE 'image/jpeg' END) THEN
    RAISE EXCEPTION 'O tipo do arquivo não confere com a extensão.' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.locacao_anexos WHERE storage_path = _path) THEN
    RAISE EXCEPTION 'Arquivo já registrado.' USING ERRCODE = '22023';
  END IF;
  _nm := left(coalesce(nullif(btrim(_nome), ''), 'anexo'), 200);
  INSERT INTO public.locacao_anexos (organization_id, locacao_id, tipo, storage_path, nome_arquivo, numero, enviado_por)
  VALUES (_l.organization_id, _l.id, _tipo, _path, _nm, _num, auth.uid()) RETURNING id INTO _novo;
  PERFORM public.locacao_evento(_l, _papel, CASE _tipo WHEN 'apolice' THEN 'Apólice anexada' ELSE 'Termos da Loft anexados' END
    || coalesce(' — nº ' || _num, '') || ' (' || _nm || ')'
    || CASE WHEN _tipo = 'apolice' THEN ' — entrega das chaves liberada quanto à apólice' ELSE '' END);
  UPDATE public.locacoes SET atualizado_em = now() WHERE id = _l.id;
  RETURN jsonb_build_object('id', _novo);
END $$;

CREATE OR REPLACE FUNCTION public.locacao_anexo_ver(_anexo uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _org uuid := public.locacao_ctx(); _a public.locacao_anexos; _l public.locacoes;
BEGIN
  SELECT * INTO _a FROM public.locacao_anexos WHERE id = _anexo AND organization_id = _org;
  SELECT * INTO _l FROM public.locacoes WHERE id = _a.locacao_id;
  IF _a.id IS NULL OR _l.id IS NULL OR NOT public.locacao_pode_ver(_l) THEN
    RAISE EXCEPTION 'Sem acesso a este anexo.' USING ERRCODE = '42501';
  END IF;
  RETURN jsonb_build_object('path', _a.storage_path, 'nome', _a.nome_arquivo);
END $$;

REVOKE ALL ON FUNCTION public.locacao_anexo_preparar(uuid, text, text), public.locacao_anexo_registrar(uuid, text, text, text, text),
  public.locacao_anexo_ver(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.locacao_anexo_preparar(uuid, text, text), public.locacao_anexo_registrar(uuid, text, text, text, text),
  public.locacao_anexo_ver(uuid) TO authenticated;

-- 5) Padrão do sistema (organization_id NULL): os 8 textos-base enviados por Denis, sem dado de cliente.
--    Fonte: src/lib/locacao-modelos-padrao.json (o teste confere que é o mesmo texto).
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, 'fiador', 1, $mod$Fiador$mod$, 'residencial', 'fiador', NULL, $mod$FIADOR$mod$, $mod$[{"id": "p001", "t": "QUADRO RESUMO: Locador(es); Locatário(a); Administradora; Imóvel; Destinação da Locação; Prazo da Locação; Valor e Vencimento do Aluguel; Primeiro Aluguel; Reajuste e Indexador; Encargos Locatícios; Contas de Consumo; Transferência de Titularidade; Garantia Locatícia; Inadimplência; Vistoria Inicial; Contestação da Vistoria; Conservação e Manutenção do Imóvel; Benfeitorias e Modificações; Vistoria Final e Revistoria; Rescisão e Multa Contratual; Desocupação e Aviso Prévio; Seguro Incêndio; Sublocação/Cessão; Preferência na Compra do Imóvel; Administração do Imóvel; LGPD; Disposições Gerais; Foro."}, {"id": "p002", "t": "PRÊAMBULO"}, {"id": "p003", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p004", "t": "[[LOCADOR]]"}, {"id": "p005", "t": "[[LOCATARIO]]"}, {"id": "p006", "t": "ADMINISTRADORA: [ADMINISTRADORA_QUALIFICACAO]; A administração do imóvel será realizada pela ADMINISTRADORA durante a vigência da locação, permanecendo sua atuação até a efetiva entrega das chaves, observados os poderes que lhe foram conferidos pelo LOCADOR. As partes comprometem-se a encaminhar à ADMINISTRADORA as comunicações e solicitações relacionadas à administração da locação, sem prejuízo dos direitos e obrigações legais e contratuais de cada parte."}, {"id": "p007", "t": "[[FIADOR]]"}, {"id": "p008", "t": "PARÁGRAFO 1º: O FIADOR assume a responsabilidade solidária pelo cumprimento das obrigações pecuniárias decorrentes deste contrato, incluindo aluguéis, encargos locatícios, multas e eventuais indenizações por danos ao imóvel, respondendo até a efetiva devolução das chaves ao LOCADOR ou à ADMINISTRADORA, observados os limites legais aplicáveis à fiança."}, {"id": "p009", "t": "PARÁGRAFO 2º: O FIADOR declara ter pleno conhecimento das obrigações assumidas neste instrumento, responsabilizando-se solidariamente pelo cumprimento das obrigações locatícias, inclusive reajustes previstos contratualmente e encargos decorrentes da locação, até a efetiva devolução das chaves, observadas as disposições do artigo 39 da Lei nº 8.245/91."}, {"id": "p010", "t": "PARÁGRAFO 3º: O FIADOR declara possuir o imóvel matriculado sob [FIADOR_IMOVEL_ENDERECO], imóvel com matrícula nº [FIADOR_MATRICULA], registrado no [FIADOR_CARTORIO], apresentado como elemento de comprovação de sua capacidade econômico-financeira, não constituindo tal declaração caução ou garantia real sobre o referido bem. O FIADOR compromete-se a comunicar por escrito à ADMINISTRADORA eventual alienação ou perda da titularidade do imóvel, para avaliação da necessidade de substituição da garantia, nos termos da legislação vigente."}, {"id": "p011", "t": "PARÁGRAFO 4º: Na hipótese de exoneração da fiança, o FIADOR deverá observar os procedimentos e prazos previstos na legislação vigente, permanecendo responsável pelas obrigações locatícias durante o período legal aplicável. O LOCATÁRIO deverá providenciar a substituição da garantia, quando exigível, no prazo e nas condições estabelecidos pela Lei nº 8.245/91."}, {"id": "p012", "t": "PARÁGRAFO 5º: O FIADOR responderá pelas obrigações decorrentes da locação, incluindo aluguéis, reajustes previstos neste contrato, encargos locatícios, multas e despesas legalmente exigíveis decorrentes do inadimplemento, observados os limites da garantia prestada e a legislação vigente."}, {"id": "p013", "t": "PARÁGRAFO 6º: Em caso de prorrogação da locação por prazo indeterminado, a responsabilidade do FIADOR permanecerá vigente, nos termos do artigo 39 da Lei nº 8.245/91, ressalvadas as hipóteses legais de exoneração da fiança."}, {"id": "p014", "t": "PARÁGRAFO 7º: Em caso de falecimento do FIADOR, a responsabilidade de seus herdeiros ficará limitada às obrigações vencidas até a data do falecimento, observados os limites da herança e o disposto no artigo 836 do Código Civil, devendo o LOCATÁRIO providenciar a substituição da garantia, nos termos da Lei nº 8.245/91."}, {"id": "p015", "t": "PARÁGRAFO 8º: Nas hipóteses legais de perda, exoneração ou insuficiência da garantia fidejussória, o LOCATÁRIO será notificado para apresentar nova garantia locatícia, no prazo de 30 (trinta) dias, observadas as disposições do artigo 40 da Lei nº 8.245/91, sob pena de adoção das medidas legais cabíveis."}, {"id": "p016", "t": "[[OBJETO]]"}, {"id": "p017", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p018", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p019", "t": "O imóvel identificado neste instrumento destina-se exclusivamente à MORADIA do LOCATÁRIO e dos moradores expressamente identificados neste contrato, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "residencial"}, {"id": "p020", "t": "O imóvel identificado neste instrumento destina-se exclusivamente ao uso COMERCIAL do LOCATÁRIO, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "comercial", "adaptado": true}, {"id": "p021", "t": "[[PRAZO]]"}, {"id": "p022", "t": "Cláusula 1º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), devendo ser pago pelo LOCATÁRIO até o dia [DIA_VENCIMENTO] de cada mês, conforme as condições estabelecidas neste instrumento."}, {"id": "p023", "t": "Cláusula 2º - O primeiro aluguel vencerá 30 (trinta) dias após a efetiva entrega das chaves ao LOCATÁRIO. Os aluguéis subsequentes vencerão todo dia [DIA_VENCIMENTO] de cada mês, observando-se, quando necessário, o cálculo proporcional dos períodos de ocupação, a fim de evitar cobrança em duplicidade."}, {"id": "p024", "t": "[[ADICIONAIS]]"}, {"id": "p025", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p026", "t": "Além do aluguel mensal, serão de responsabilidade do LOCATÁRIO os encargos locatícios expressamente atribuídos a ele neste contrato, os quais serão devidos a partir da efetiva entrega das chaves, observadas as disposições legais e contratuais aplicáveis."}, {"id": "p027", "t": "Cláusula 3º - O atraso no pagamento do aluguel ou de quaisquer encargos locatícios acarretará a incidência de multa moratória de 10% (dez por cento) sobre o valor devido, acrescida de juros de mora de 1% (um por cento) ao mês, calculados proporcionalmente aos dias de atraso, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p028", "t": "Cláusula 4º - O pagamento dos alugueis e encargos locatícios devem ser realizados por meio de boleto bancário, que será emitido pela ADMINISTRADORA."}, {"id": "p029", "t": "Cláusula 5º - Caso o LOCATÁRIO não receba o boleto bancário até 02 (dois) dias úteis antes do vencimento, deverá entrar em contato com a ADMINISTRADORA para solicitar a segunda via, permanecendo responsável pelo pagamento na data estabelecida, salvo eventual falha imputável à ADMINISTRADORA que tenha efetivamente impedido o pagamento."}, {"id": "p030", "t": "Cláusula 6º - O inadimplemento do aluguel ou de quaisquer encargos locatícios na data do vencimento constituirá o LOCATÁRIO em mora, independentemente de notificação, facultando ao LOCADOR adotar as medidas judiciais e extrajudiciais cabíveis, inclusive ação de despejo e cobrança, nos termos da Lei nº 8.245/91, sem prejuízo dos encargos moratórios previstos neste contrato."}, {"id": "p031", "t": "Cláusula 7º - O LOCATÁRIO não poderá suspender ou deixar de efetuar o pagamento dos aluguéis e encargos locatícios por iniciativa própria, devendo eventuais divergências ou solicitações relacionadas ao imóvel ser formalizadas perante a ADMINISTRADORA, sem prejuízo dos direitos assegurados pela legislação vigente."}, {"id": "p032", "t": "Cláusula 8º – O LOCATÁRIO declara estar ciente de que o inadimplemento das obrigações financeiras decorrentes deste contrato poderá ensejar o protesto dos respectivos débitos, observadas as exigências legais aplicáveis."}, {"id": "p033", "t": "Cláusula 9º - O inadimplemento das obrigações locatícias poderá ensejar a adoção das medidas judiciais cabíveis, bem como a comunicação dos débitos aos órgãos de proteção ao crédito, desde que observados os requisitos legais, inclusive quanto à legitimidade, exatidão e atualização das informações fornecidas."}, {"id": "p034", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p035", "t": "O valor do aluguel será reajustado anualmente, respeitado o intervalo mínimo permitido pela legislação vigente, mediante aplicação do índice IPCA (Índice Nacional de Preços ao Consumidor Amplo), ou de outro índice oficial que venha a substituí-lo em caso de sua extinção, observadas as disposições legais aplicáveis."}, {"id": "p036", "t": "Cláusula 10º - O LOCATÁRIO será responsável pelo pagamento do IPTU e das despesas ordinárias de condomínio incidentes sobre o imóvel durante o período de sua posse, podendo tais valores ser incluídos no boleto mensal de aluguel para fins de cobrança e repasse. Permanecem sob responsabilidade exclusiva do LOCADOR as despesas extraordinárias de condomínio, conforme disposto no artigo 22, inciso X e parágrafo único, da Lei nº 8.245/91."}, {"id": "p037", "t": "Cláusula 11º - Caso o LOCATÁRIO receba diretamente carnês, avisos ou documentos referentes aos tributos e encargos de sua responsabilidade, deverá encaminhá-los à ADMINISTRADORA com antecedência suficiente para viabilizar o pagamento dentro do respectivo vencimento, respondendo por eventuais encargos decorrentes de sua omissão ou atraso injustificado."}, {"id": "p038", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p039", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p040", "t": "Cláusula 12º – O locatário obriga-se a providenciar, junto às concessionárias competentes, a transferência da titularidade das de ÁGUA, ELERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p041", "t": "DO DESCUMPRIMENTO E DAS PROVIDÊNCIAS ADMINISTRATIVAS:"}, {"id": "p042", "t": "Cláusula 13º - Caso o LOCATÁRIO não consiga realizar a transferência de titularidade das contas de ÁGUA, ENERGIA ELÉTRICA e GÁS antes da retirada das chaves, deverá apresentar à ADMINISTRADORA a devida comprovação das tentativas realizadas e da impossibilidade de efetivação, ficando a retirada das chaves condicionada à autorização expressa do LOCADOR. Uma vez autorizada a retirada das chaves pelo LOCADOR, o LOCATÁRIO deverá apresentar à ADMINISTRADORA, no prazo máximo de 15 (quinze) dias corridos, contados da data da retirada das chaves, os respectivos comprovantes de efetivação da transferência de titularidade das referidas contas."}, {"id": "p043", "t": "O não atendimento da obrigação no prazo estabelecido, sem a devida comprovação de impedimento não imputável ao LOCATÁRIO, caracterizará descumprimento contratual e ensejará a aplicação de multa administrativa no valor de R$ 250,00 (duzentos e cinquenta reais), a ser lançada no boleto de aluguel imediatamente subsequente à constatação do descumprimento."}, {"id": "p044", "t": "Na ausência de comprovação da regularização após o prazo previsto, a ADMINISTRADORA poderá, quando tecnicamente possível e mediante os documetnos e autorizações necessárias, adotrar as providências cabíveis perante as respectivas concessionárias para a regularização da titularidade, ficando o LOCATÁRIO responsável pelos eventuais custos, taxas ou encargos decorrentes de tais providências, quando comprovadamente de sua responsabilidade, sem prejuízo da multa prevista nesta cláusula."}, {"id": "p045", "t": "Cláusula 14º - O LOCATÁRIO declara receber, na data da efetiva entrega das chaves, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso para HABITAÇÃO.", "dest": "residencial"}, {"id": "p046", "t": "Cláusula 14º - O LOCATÁRIO declara receber, na data da efetiva entrega das chaves, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso COMERCIAL.", "dest": "comercial", "adaptado": true}, {"id": "p047", "t": "Cláusula 15º - Caso o LOCATÁRIO identifique divergências em relação ao laudo de vistoria inicial, deverá apresentar sua contestação por escrito à ADMINISTRADORA, no prazo de 10 (dez) dias corridos contados da entrega das chaves, preferencialmente acompanhada de fotografias ou outros registros que comprovem as condições apontadas. A ausência de manifestação dentro do prazo será considerada concordância quanto às condições aparentes descritas no laudo, ressalvados os vícios ocultos e defeitos não identificáveis em vistoria ordinária."}, {"id": "p048", "t": "Cláusula 16º - Fica permitido ao LOCATÁRIO realizar pequenos furos nas paredes do imóvel para a fixação de quadros, espelhos, suportes e objetos similares, desde que não comprometam a estrutura, as instalações hidráulicas ou elétricas. Fica expressamente vedada a realização de furos em azulejos, revestimentos cerâmicos e áreas impermeabilizadas, salvo mediante autorização prévia e por escrito do LOCADOR. Ao término da locação, o LOCATÁRIO deverá providenciar a adequada reparação dos furos realizados nas paredes, recompondo a pintura e o acabamento quando necessário, restituindo o imóvel nas condições em que o recebeu, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p049", "t": "Cláusula 17º - O LOCATÁRIO deverá devolver o imóvel com a pintura nas mesmas condições em que o recebeu, conforme descrito no laudo de vistoria inicial, responsabilizando-se pela reparação de manchas, riscos, alterações de cores, descascamentos ou danos decorrentes de uso inadequado ou de sua responsabilidade, ressalvado o desgaste natural decorrente do uso regular do imóvel."}, {"id": "p050", "t": "Cláusula 18º - O LOCATÁRIO deverá zelar pela conservação dos pisos, azulejos, armários, acessórios e demais itens que integram o imóvel, responsabilizando-se pelos danos que causar por ação, omissão ou uso inadequado, devendo providenciar o reparo ou a substituição dos itens danificados por outros de padrão, qualidade e características equivalentes aos originalmente existentes, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p051", "t": "Cláusula 19º - Caso algum piso seja danificado e o LOCATÁRIO não encontre o mesmo modelo disponível para compra, ou tenha saído de fabricação, deverá consultar o LOCADOR, através da ADMINISTRADORA, um outro modelo compatível aceito para substituição de todos os pisos do cômodo, arcando o LOCATÁRIO com todo o custo de material e instalação."}, {"id": "p052", "t": "Cláusula 20º - O LOCATÁRIO deverá verificar a tensão elétrica disponível nos pontos de energia do imóvel antes de conectar seus equipamentos e aparelhos eletrônicos, responsabilizando-se pelos danos decorrentes da utilização inadequada ou incompatível com a tensão disponível, desde que as instalações tenham sido entregues em condições regulares de funcionamento e que as informações disponíveis tenham sido corretamente fornecidas."}, {"id": "p053", "t": "Cláusula 21º - O LOCATÁRIO não poderá realizar modificações, alterações ou benfeitorias no imóvel sem prévia autorização, por escrito, do LOCADOR. Salvo ajuste expresso em contrário, as benfeitorias realizadas, ainda que autorizadas, incorporar-se-ão ao imóvel, sem direito de indenização ou retenção pelo LOCATÁRIO, nos termos do artigo 35 da Lei nº 8.245/91 e da Súmula 335 do STJ, ressalvadas as obrigações legais do LOCADOR relativas à conservação, segurança e habitabilidade do imóvel."}, {"id": "p054", "t": "Cláusula 22º - Compete ao LOCATÁRIO realizar os reparos e serviços de manutenção decorrentes do uso regular do imóvel, bem como reparar os danos causados por si, seus moradores, visitantes ou terceiros sob sua responsabilidade. Compete ao LOCADOR realizar os reparos relativos a vícios anteriores à locação, problemas estruturais e defeitos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, desde que não decorrentes de ação ou omissão do LOCATÁRIO."}, {"id": "p055", "t": "PARÁGRAFO ÚNICO: Identificada a necessidade de reparo de responsabilidade do LOCADOR, o LOCATÁRIO deverá comunicar formalmente a ADMINISTRADORA, para que sejam adotadas as providências necessárias. Em situações urgentes, que envolvam risco à segurança ou agravamento de danos ao imóvel, deverá comunicar imediatamente a ADMINISTRADORA, permitindo a adoção das medidas emergenciais cabíveis, observadas as disposições legais quanto à responsabilidade pelos custos."}, {"id": "p056", "t": "Cláusula 23º - O LOCADOR poderá exigir que o LOCATÁRIO remova modificações ou benfeitorias realizadas sem autorização prévia e por escrito, quando necessário à recomposição do imóvel às condições originais, correndo as despesas correspondentes por conta do LOCATÁRIO, desde que decorrentes de sua responsabilidade."}, {"id": "p057", "t": "Cláusula 24º - Ao término da locação, será realizada vistoria final para verificar as condições de conservação do imóvel, mediante comparação com o laudo de vistoria inicial, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p058", "t": "Parágrafo 1º: Caso sejam constatados danos ou irregularidades de responsabilidade do LOCATÁRIO, este será comunicado para que possa providenciar os respectivos reparos no prazo de 05 (cinco) dias corridos, ou outro prazo acordado entre as partes, sem prejuízo da cobrança de eventuais valores necessários à recomposição do imóvel."}, {"id": "p059", "t": "Parágrafo 2º: Caso o LOCATÁRIO não realize os reparos de sua responsabilidade, o LOCADOR poderá providenciá-los e exigir o ressarcimento dos respectivos custos, mediante apresentação dos comprovantes pertinentes, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p060", "t": "Parágrafo 3º: A vistoria final será realizada sem custo para o LOCATÁRIO. Caso seja necessária nova vistoria para verificação dos reparos executados, poderá ser cobrada taxa de revistoria no valor de R$ 150,00 (cento e cinquenta reais), desde que previamente informada e relacionada à necessidade de nova verificação de pendências de responsabilidade do LOCATÁRIO."}, {"id": "p061", "t": "Parágrafo 4º: A existência de danos ou pendências apontadas na vistoria não impedirá o recebimento das chaves nem a formalização da devolução do imóvel, permanecendo assegurado ao LOCADOR o direito de exigir o ressarcimento dos prejuízos comprovadamente atribuíveis ao LOCATÁRIO."}, {"id": "p062", "t": "Cláusula 25º - O LOCATÁRIO permitirá que o LOCADOR ou seu representante devidamente autorizado examine ou vistori? o imóvel, mediante prévio agendamento e comunicação com antecedência mínima de 48 (quarenta e oito) horas, em dia e horário previamente acordados entre as partes, respeitado o direito à privacidade e ao uso pacífico do imóvel."}, {"id": "p063", "t": "Cláusula 26º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade residencial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "residencial"}, {"id": "p064", "t": "Cláusula 26º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade comercial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "comercial", "adaptado": true}, {"id": "p065", "t": "Cláusula 27º - Em caso de desapropriação do imóvel, a locação será extinta, ficando o LOCADOR desobrigado das obrigações futuras decorrentes deste contrato, ressalvados os direitos do LOCATÁRIO de pleitear eventual indenização diretamente perante o poder público desapropriante, quando legalmente cabível."}, {"id": "p066", "t": "Cláusula 28º - O LOCATÁRIO obriga-se a respeitar as normas de convivência, os direitos de vizinhança, as regras condominiais e a legislação vigente, abstendo-se de praticar atos que comprometam a segurança, a tranquilidade, a higiene ou o sossego dos demais moradores."}, {"id": "p067", "t": "Parágrafo primeiro: O descumprimento das obrigações legais ou contratuais poderá ensejar a aplicação das medidas cabíveis, inclusive rescisão da locação, conforme a natureza e a gravidade da infração, observadas as disposições da Lei nº 8.245/91."}, {"id": "p068", "t": "Parágrafo segundo: Fica estipulada multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente à época da infração, aplicável em caso de descumprimento contratual que justifique sua incidência, observados os critérios de proporcionalidade, a natureza da obrigação descumprida e a legislação vigente."}, {"id": "p069", "t": "Parágrafo terceiro: Na hipótese de devolução antecipada do imóvel por iniciativa do LOCATÁRIO durante o prazo determinado deste contrato, será devida multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente, calculada proporcionalmente ao período restante do contrato, conforme o artigo 4º da Lei nº 8.245/91."}, {"id": "p070", "t": "Cláusula 29º - Fica o LOCATÁRIO isento do pagamento de multa contratual por desocupação voluntária do imóvel após o 12º (décimo segundo) mês de locação, tendo, porém, a obrigação de avisar por escrito com, no mínimo, 30 (trinta) dias de antecedência, ficando responsável pelo pagamento do aluguel e dos acessórios locatícios durante o período de aviso.", "cond": "isencao_multa"}, {"id": "p071", "t": "Parágrafo primeiro: A isenção da multa rescisória apenas caberá em benefício do LOCATÁRIO, caso esteja quite com todas as demais obrigações previstas neste instrumento. Caso contrário fica estipulada a multa contratual compensatória proporcionalmente ao período de cumprimento do contrato, em conformidade com a nova redação do artigo 4º, atribuída pela Lei no 12.112/2009, na qual incorrerá o LOCATÁRIO na hipótese de devolução do imóvel antes do prazo pactuado.", "cond": "isencao_multa"}, {"id": "p072", "t": "Cláusula 30º - O LOCATÁRIO assume o formal compromisso de 30 (trinta) dias antes de desocupar o imóvel, notificar por escrito a ADMINISTRADORA que, efetuará uma vistoria no mesmo a fim de ficar constatado o estado de conservação do imóvel."}, {"id": "p073", "t": "Cláusula 31º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p074", "t": "Cláusula 32º - Após o término do prazo contratual, caso a locação prossiga por prazo indeterminado, o LOCATÁRIO poderá rescindir o contrato mediante comunicação por escrito ao LOCADOR ou à ADMINISTRADORA, com antecedência mínima de 30 (trinta) dias."}, {"id": "p075", "t": "Parágrafo único: Na ausência do aviso prévio previsto nesta cláusula, o LOCADOR poderá exigir quantia correspondente a 01 (um) mês de aluguel e encargos vigentes na data da rescisão, conforme disposto no artigo 6º, parágrafo único, da Lei nº 8.245/91."}, {"id": "p076", "t": "Cláusula 33º - Fica eleito o foro da comarca onde se localiza o imóvel objeto desta locação para dirimir quaisquer controvérsias decorrentes deste contrato, ressalvadas as hipóteses legais de competência absoluta."}, {"id": "p077", "t": "Parágrafo único: Em caso de demanda judicial decorrente do descumprimento das obrigações contratuais, as partes responderão pelas custas e despesas processuais, conforme a legislação vigente e eventual determinação judicial."}, {"id": "p078", "t": "Cláusula 34º - É vedado ao LOCATÁRIO ceder, transferir ou sublocar, total ou parcialmente, o imóvel objeto deste contrato, bem como emprestá-lo a terceiros, sem prévia autorização expressa e por escrito do LOCADOR, nos termos do artigo 13 da Lei nº 8.245/91."}, {"id": "p079", "t": "Parágrafo único: Em caso de separação de fato, separação judicial, divórcio ou dissolução da união estável do LOCATÁRIO, a locação prosseguirá automaticamente com aquele que permanecer no imóvel, observadas as disposições do artigo 12 da Lei nº 8.245/91, inclusive quanto à comunicação ao LOCADOR e ao FIADOR."}, {"id": "p080", "t": "Cláusula 35º - Caso o LOCADOR pretenda vender o imóvel durante a vigência da locação, deverá assegurar ao LOCATÁRIO o direito de preferência para aquisição, em igualdade de condições com terceiros, mediante comunicação formal contendo todas as condições do negócio, inclusive preço, forma de pagamento e demais informações pertinentes, nos termos dos artigos 27 e seguintes da Lei nº 8.245/91."}, {"id": "p081", "t": "Parágrafo único: O LOCATÁRIO terá o prazo legal de 30 (trinta) dias, contado do recebimento da comunicação, para manifestar sua aceitação integral e inequívoca da proposta. Caso não exerça o direito de preferência, deverá permitir visitas de interessados, mediante prévio agendamento e em horários previamente acordados."}, {"id": "p082", "t": "Cláusula 36º - Ocorrendo interesse do LOCATÁRIO na compra do imóvel, sua manifestação deverá ser encaminhada por escrito, à ADMINISTRADORA, com a devida intervenção do corretor de imóveis da mesma empresa, a quem caberá a intermediação para a concretização do negócio."}, {"id": "p083", "t": "Cláusula 37º - A ADMINISTRADORA permanecerá responsável pela administração da locação durante a vigência deste contrato, observados os poderes que lhe foram conferidos pelo LOCADOR, inclusive quanto aos procedimentos de encerramento, entrega das chaves, apuração de encargos e prestação de contas, conforme o respectivo contrato de administração."}, {"id": "p084", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p085", "t": "Cláusula 38º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da estrutura e partes integrantes do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p086", "t": "Parágrafo primeiro: O LOCATÁRIO (S), poderá ele mesmo contratar e apresentar a apólice para a ADMINISTRADORA, porém, somente serão aceitas apólices que apresentarem seu pagamento integral."}, {"id": "p087", "t": "Parágrafo segundo: Quanto a atualização e renovação do seguro, o valor segurado a ser corrigido durante a vigência do presente contrato, deverá comprovar que a apólice em vigor cubra sempre o custo para reconstrução do imóvel, onde caberá ao LOCATARIO providenciar a renovação do seguro na época própria, dando ciência ao LOCADOR ou a ADMINISTRADORA."}, {"id": "p088", "t": "Cláusula 39º - O descumprimento da obrigação de contratação ou renovação do seguro contra incêndio, após notificação para regularização, poderá caracterizar infração contratual, sujeitando o LOCATÁRIO às medidas legais e contratuais cabíveis."}, {"id": "p089", "t": "Cláusula 40º - Em se tratando de edifício, fica desde já convencionado que não serão aceitas apólices coletivas de condomínio em substituição ao seguro incêndio individual."}, {"id": "p090", "t": "Cláusula 41º - Caso o LOCATÁRIO não apresente a apólice de seguro contratada por sua iniciativa dentro do prazo estabelecido, o LOCADOR poderá providenciar a contratação do seguro, mediante prévia comunicação ao LOCATÁRIO, sendo os respectivos custos de responsabilidade deste, desde que comprovados documentalmente. Os valores poderão ser incluídos no boleto de aluguel, observadas as condições e os prazos de pagamento informados pela ADMINISTRADORA."}, {"id": "p091", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p092", "t": "Cláusula 42º - As partes declaram estar cientes de que a ADMINISTRADORA poderá coletar, armazenar, utilizar e compartilhar os dados pessoais estritamente necessários à execução deste contrato, ao cumprimento de obrigações legais e regulatórias, bem como à proteção do crédito, observadas as bases legais previstas no artigo 7º, incisos II, V e X, da Lei nº 13.709/2018 (Lei Geral de Proteção de Dados Pessoais – LGPD)."}, {"id": "p093", "t": "Cláusula 43º - O tratamento de dados pessoais para finalidades adicionais, não abrangidas pelas hipóteses legais previstas na cláusula anterior, dependerá da existência de base legal adequada, inclusive consentimento específico do titular, quando necessário, assegurados os direitos previstos na Lei nº 13.709/2018."}, {"id": "p094", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p095", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p096", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IPCA (Índice Nacional de Preços ao Consumidor Amplo); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p097", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O LOCADOR declara ser o legítimo proprietário e/ou possuidor do Imóvel, o qual se encontra livre e desonerado de quaisquer direitos, obrigações e ônus, judiciais e/ou extrajudiciais, que possam comprometer este CONTRATO, assumindo o dever de indenizar e manter o LOCATÁRIO e a ADMINISTRADORA indenes de quaisquer responsabilidades decorrentes de medidas que comprometam a sua posse e propriedade sobre o Imóvel. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Qualquer alteração nos endereços eletrônicos de e-mail constantes no cadastro prévio realizado deverá ser prontamente comunicada à ADMINISTRADORA por instrumento que comprove a total ciência da imobiliária quanto a aludida mudança. Em se tratando de LOCATÁRIO pessoa jurídica, que seja obrigado ao pagamento de imposto de renda retido na fonte (IRRF) quando do pagamento do aluguel, compromete-se o LOCATÁRIO a apresentar mensalmente à ADMINISTRADORA os comprovantes de recolhimento do IRRF, na forma calculada no boleto emitido para pagamento do aluguel, sob pena de ser responsável por quaisquer valores despendidos pelo LOCADOR perante a Receita Federal do Brasil, mesmo que apurados após a extinção do presente instrumento. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p098", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p099", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p100", "t": "[[ASSINATURAS]]"}]$mod$::jsonb, 'Texto-base enviado por Denis (16/11/2026)')
ON CONFLICT DO NOTHING;
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, 'caucao_dinheiro', 1, $mod$Caução em dinheiro$mod$, 'residencial', 'caucao', NULL, $mod$CAUÇÃO$mod$, $mod$[{"id": "p001", "t": "QUADRO RESUMO: Locador(es); Locatário(a); Administradora; Imóvel; Destinação da Locação; Prazo da Locação; Valor e Vencimento do Aluguel; Primeiro Aluguel; Reajuste e Indexador; Encargos Locatícios; Contas de Consumo; Transferência de Titularidade; Garantia Locatícia; Inadimplência; Vistoria Inicial; Contestação da Vistoria; Conservação e Manutenção do Imóvel; Benfeitorias e Modificações; Vistoria Final e Revistoria; Rescisão e Multa Contratual; Desocupação e Aviso Prévio; Seguro Incêndio; Sublocação/Cessão; Preferência na Compra do Imóvel; Administração do Imóvel; LGPD; Disposições Gerais; Foro."}, {"id": "p002", "t": "PRÊAMBULO"}, {"id": "p003", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p004", "t": "[[LOCADOR]]"}, {"id": "p005", "t": "[[LOCATARIO]]"}, {"id": "p006", "t": "ADMINISTRADORA: [ADMINISTRADORA_QUALIFICACAO]; cuja a administração do referido imóvel perdurará durante o prazo de vigência do presente Contrato de Locação, estendendo-se até a data da efetiva entrega das chaves, estando cientes as partes celebrantes deste instrumento de que toda e qualquer questão decorrente deste deverá ser tratada prévia e diretamente junto à ADMINISTRADORA, sendo que o não cumprimento desta cláusula, poderá dar ensejo às medidas cabíveis de rescisão contratual por culpa da parte infratora, ou outras medidas cabíveis, além de isenção de responsabilidade da ADMINISTRADORA."}, {"id": "p007", "t": "GARANTIA LOCATÍCIA: As partes convencionam que a garantia locatícia é representada pela importância de R$ [CAUCAO_VALOR] ([CAUCAO_VALOR_EXTENSO]), equivalente a [CAUCAO_MESES] aluguéis do início da locação, que deverá ser pago através de [CAUCAO_FORMA], favorecido, [CAUCAO_FAVORECIDO]. Valor este a ser devolvido no final da locação, corrigido pelo índice da POUPANÇA do período."}, {"id": "p008", "t": "Cláusula 1º - Ao término do prazo de locação, desde que cumpridas pelo LOCATÁRIO, todas as obrigações decorrentes deste contrato, inclusive, a desocupação do imóvel e a entrega das chaves, sem a existência de quaisquer débitos ou de reparos a serem realizados pelo LOCATÁRIO para com o LOCADOR, convencionam, ainda as partes, que o valor da caução em dinheiro será devolvida, bem como suas correções através do índice da Caderneta de Poupança, em benefício do LOCATÁRIO por ocasião do levantamento da soma respectiva, ao final do vínculo locatário. Para tanto, deverá ser apresentado, documento rescisório da locação, firmado pelo LOCADOR e LOCATÁRIO, com o reconhecimento de firmas das assinaturas ou realizada através de assinatura eletrônica."}, {"id": "p009", "t": "Cláusula 2º - Se o LOCATÁRIO, não observar quaisquer das cláusulas do presente contrato de locação, fica, desde já o LOCADOR ou ADMINISTRADORA que o represente, autorizado a resgatar o caução em dinheiro a qualquer momento, mesmo antes do prazo final do contrato, independente de interpelação judicial ou extrajudicial, a fim de que o valor do resgate quite eventual importância que lhe seja devida em razão de débitos oriundos deste contrato, respeitando a lei do inquilinato."}, {"id": "p010", "t": "Cláusula 3º - A hipótese do LOCATÁRIO contestar o valor apresentado e ajuizar a competente ação cautelar de prestação de contas, correrão por sua conta todas as despesas consequentes, inclusive custas e honorários advocatícios."}, {"id": "p011", "t": "[[OBJETO]]"}, {"id": "p012", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p013", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p014", "t": "O imóvel identificado neste instrumento destina-se exclusivamente à MORADIA do LOCATÁRIO e dos moradores expressamente identificados neste contrato, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "residencial"}, {"id": "p015", "t": "O imóvel identificado neste instrumento destina-se exclusivamente ao uso COMERCIAL do LOCATÁRIO, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "comercial", "adaptado": true}, {"id": "p016", "t": "[[PRAZO]]"}, {"id": "p017", "t": "Cláusula 4º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), devendo ser pago pelo LOCATÁRIO até o dia [DIA_VENCIMENTO] de cada mês, conforme as condições estabelecidas neste instrumento."}, {"id": "p018", "t": "Cláusula 5º - O primeiro aluguel vencerá 30 (trinta) dias após a efetiva entrega das chaves ao LOCATÁRIO. Os aluguéis subsequentes vencerão todo dia [DIA_VENCIMENTO] de cada mês, observando-se, quando necessário, o cálculo proporcional dos períodos de ocupação, a fim de evitar cobrança em duplicidade."}, {"id": "p019", "t": "[[ADICIONAIS]]"}, {"id": "p020", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p021", "t": "Além do aluguel mensal, serão de responsabilidade do LOCATÁRIO os encargos locatícios expressamente atribuídos a ele neste contrato, os quais serão devidos a partir da efetiva entrega das chaves, observadas as disposições legais e contratuais aplicáveis."}, {"id": "p022", "t": "Cláusula 6º - O atraso no pagamento do aluguel ou de quaisquer encargos locatícios acarretará a incidência de multa moratória de 10% (dez por cento) sobre o valor devido, acrescida de juros de mora de 1% (um por cento) ao mês, calculados proporcionalmente aos dias de atraso, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p023", "t": "Cláusula 7º - O pagamento dos alugueis e encargos locatícios devem ser realizados por meio de boleto bancário, que será emitido pela ADMINISTRADORA."}, {"id": "p024", "t": "Cláusula 8º - Caso o LOCATÁRIO não receba o boleto bancário até 02 (dois) dias úteis antes do vencimento, deverá entrar em contato com a ADMINISTRADORA para solicitar a segunda via, permanecendo responsável pelo pagamento na data estabelecida, salvo eventual falha imputável à ADMINISTRADORA que tenha efetivamente impedido o pagamento."}, {"id": "p025", "t": "Cláusula 9º - O inadimplemento do aluguel ou de quaisquer encargos locatícios na data do vencimento constituirá o LOCATÁRIO em mora, independentemente de notificação, facultando ao LOCADOR adotar as medidas judiciais e extrajudiciais cabíveis, inclusive ação de despejo e cobrança, nos termos da Lei nº 8.245/91, sem prejuízo dos encargos moratórios previstos neste contrato."}, {"id": "p026", "t": "Cláusula 10º - O LOCATÁRIO não poderá suspender ou deixar de efetuar o pagamento dos aluguéis e encargos locatícios por iniciativa própria, devendo eventuais divergências ou solicitações relacionadas ao imóvel ser formalizadas perante a ADMINISTRADORA, sem prejuízo dos direitos assegurados pela legislação vigente."}, {"id": "p027", "t": "Cláusula 11º – O LOCATÁRIO declara estar ciente de que o inadimplemento das obrigações financeiras decorrentes deste contrato poderá ensejar o protesto dos respectivos débitos, observadas as exigências legais aplicáveis."}, {"id": "p028", "t": "Cláusula 12º - O inadimplemento das obrigações locatícias poderá ensejar a adoção das medidas judiciais cabíveis, bem como a comunicação dos débitos aos órgãos de proteção ao crédito, desde que observados os requisitos legais, inclusive quanto à legitimidade, exatidão e atualização das informações fornecidas."}, {"id": "p029", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p030", "t": "O valor do aluguel será reajustado anualmente, respeitado o intervalo mínimo permitido pela legislação vigente, mediante aplicação do índice IPCA (Índice Nacional de Preços ao Consumidor Amplo), ou de outro índice oficial que venha a substituí-lo em caso de sua extinção, observadas as disposições legais aplicáveis."}, {"id": "p031", "t": "Cláusula 13º - O LOCATÁRIO será responsável pelo pagamento do IPTU e das despesas ordinárias de condomínio incidentes sobre o imóvel durante o período de sua posse, podendo tais valores ser incluídos no boleto mensal de aluguel para fins de cobrança e repasse. Permanecem sob responsabilidade exclusiva do LOCADOR as despesas extraordinárias de condomínio, conforme disposto no artigo 22, inciso X e parágrafo único, da Lei nº 8.245/91."}, {"id": "p032", "t": "Cláusula 14º - Caso o LOCATÁRIO receba diretamente carnês, avisos ou documentos referentes aos tributos e encargos de sua responsabilidade, deverá encaminhá-los à ADMINISTRADORA com antecedência suficiente para viabilizar o pagamento dentro do respectivo vencimento, respondendo por eventuais encargos decorrentes de sua omissão ou atraso injustificado."}, {"id": "p033", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p034", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p035", "t": "Cláusula 15º – O locatário obriga-se a providenciar, junto às concessionárias competentes, a transferência da titularidade das de ELERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p036", "t": "DO DESCUMPRIMENTO E DAS PROVIDÊNCIAS ADMINISTRATIVAS:"}, {"id": "p037", "t": "Cláusula 16º – Caso o LOCATÁRIO não consiga realizar a transferência de titularidade das contas de ENERGIA ELÉTRICA e GÁS antes da retirada das chaves, deverá apresentar à ADMINISTRADORA a devida comprovação das tentativas realizadas e da impossibilidade de efetivação, ficando a retirada das chaves condicionada à autorização expressa do LOCADOR. Uma vez autorizada a retirada das chaves pelo LOCADOR, o LOCATÁRIO deverá apresentar à ADMINISTRADORA, no prazo máximo de 15 (quinze) dias corridos, contados da data da retirada das chaves, os respectivos comprovantes de efetivação da transferência de titularidade das referidas contas."}, {"id": "p038", "t": "O não atendimento da obrigação no prazo estabelecido, sem a devida comprovação de impedimento não imputável ao LOCATÁRIO, caracterizará descumprimento contratual e ensejará a aplicação de multa administrativa no valor de R$ 250,00 (duzentos e cinquenta reais), a ser lançada no boleto de aluguel imediatamente subsequente à constatação do descumprimento."}, {"id": "p039", "t": "Na ausência de comprovação da regularização após o prazo previsto, a ADMINISTRADORA poderá, quando tecnicamente possível e mediante os documetnos e autorizações necessárias, adotrar as providências cabíveis perante as respectivas concessionárias para a regularização da titularidade, ficando o LOCATÁRIO responsável pelos eventuais custos, taxas ou encargos decorrentes de tais providências, quando comprovadamente de sua responsabilidade, sem prejuízo da multa prevista nesta cláusula."}, {"id": "p040", "t": "Cláusula 17º - O LOCATÁRIO declara receber, na data da efetiva entrega das chaves, o imóvel descrito no LAUDO DE"}, {"id": "p041", "t": "VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso para HABITAÇÃO.", "dest": "residencial"}, {"id": "p042", "t": "VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso COMERCIAL.", "dest": "comercial", "adaptado": true}, {"id": "p043", "t": "Cláusula 18º - Caso o LOCATÁRIO identifique divergências em relação ao laudo de vistoria inicial, deverá apresentar sua contestação por escrito à ADMINISTRADORA, no prazo de 10 (dez) dias corridos contados da entrega das chaves, preferencialmente acompanhada de fotografias ou outros registros que comprovem as condições apontadas. A ausência de manifestação dentro do prazo será considerada concordância quanto às condições aparentes descritas no laudo, ressalvados os vícios ocultos e defeitos não identificáveis em vistoria ordinária."}, {"id": "p044", "t": "Cláusula 19º - Fica permitido ao LOCATÁRIO realizar pequenos furos nas paredes do imóvel para a fixação de quadros, espelhos, suportes e objetos similares, desde que não comprometam a estrutura, as instalações hidráulicas ou elétricas. Fica expressamente vedada a realização de furos em azulejos, revestimentos cerâmicos e áreas impermeabilizadas, salvo mediante autorização prévia e por escrito do LOCADOR. Ao término da locação, o LOCATÁRIO deverá providenciar a adequada reparação dos furos realizados nas paredes, recompondo a pintura e o acabamento quando necessário, restituindo o imóvel nas condições em que o recebeu, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p045", "t": "Cláusula 20º - O LOCATÁRIO deverá devolver o imóvel com a pintura nas mesmas condições em que o recebeu, conforme descrito no laudo de vistoria inicial, responsabilizando-se pela reparação de manchas, riscos, alterações de cores, descascamentos ou danos decorrentes de uso inadequado ou de sua responsabilidade, ressalvado o desgaste natural decorrente do uso regular do imóvel."}, {"id": "p046", "t": "Cláusula 21º - O LOCATÁRIO deverá zelar pela conservação dos pisos, azulejos, armários, acessórios e demais itens que integram o imóvel, responsabilizando-se pelos danos que causar por ação, omissão ou uso inadequado, devendo providenciar o reparo ou a substituição dos itens danificados por outros de padrão, qualidade e características equivalentes aos originalmente existentes, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p047", "t": "Cláusula 22º - Caso algum piso seja danificado e o LOCATÁRIO não encontre o mesmo modelo disponível para compra, ou tenha saído de fabricação, deverá consultar o LOCADOR, através da ADMINISTRADORA, um outro modelo compatível aceito para substituição de todos os pisos do cômodo, arcando o LOCATÁRIO com todo o custo de material e instalação."}, {"id": "p048", "t": "Cláusula 23º - O LOCATÁRIO deverá verificar a tensão elétrica disponível nos pontos de energia do imóvel antes de conectar seus equipamentos e aparelhos eletrônicos, responsabilizando-se pelos danos decorrentes da utilização inadequada ou incompatível com a tensão disponível, desde que as instalações tenham sido entregues em condições regulares de funcionamento e que as informações disponíveis tenham sido corretamente fornecidas."}, {"id": "p049", "t": "Cláusula 24º - O LOCATÁRIO não poderá realizar modificações, alterações ou benfeitorias no imóvel sem prévia autorização, por escrito, do LOCADOR. Salvo ajuste expresso em contrário, as benfeitorias realizadas, ainda que autorizadas, incorporar-se-ão ao imóvel, sem direito de indenização ou retenção pelo LOCATÁRIO, nos termos do artigo 35 da Lei nº 8.245/91 e da Súmula 335 do STJ, ressalvadas as obrigações legais do LOCADOR relativas à conservação, segurança e habitabilidade do imóvel."}, {"id": "p050", "t": "Cláusula 25º - Compete ao LOCATÁRIO realizar os reparos e serviços de manutenção decorrentes do uso regular do imóvel, bem como reparar os danos causados por si, seus moradores, visitantes ou terceiros sob sua responsabilidade. Compete ao LOCADOR realizar os reparos relativos a vícios anteriores à locação, problemas estruturais e defeitos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, desde que não decorrentes de ação ou omissão do LOCATÁRIO."}, {"id": "p051", "t": "PARÁGRAFO ÚNICO: Identificada a necessidade de reparo de responsabilidade do LOCADOR, o LOCATÁRIO deverá comunicar formalmente a ADMINISTRADORA, para que sejam adotadas as providências necessárias. Em situações urgentes, que envolvam risco à segurança ou agravamento de danos ao imóvel, deverá comunicar imediatamente a ADMINISTRADORA, permitindo a adoção das medidas emergenciais cabíveis, observadas as disposições legais quanto à responsabilidade pelos custos."}, {"id": "p052", "t": "Cláusula 26º - O LOCADOR poderá exigir que o LOCATÁRIO remova modificações ou benfeitorias realizadas sem autorização prévia e por escrito, quando necessário à recomposição do imóvel às condições originais, correndo as despesas correspondentes por conta do LOCATÁRIO, desde que decorrentes de sua responsabilidade."}, {"id": "p053", "t": "Cláusula 27º - Ao término da locação, será realizada vistoria final para verificar as condições de conservação do imóvel, mediante comparação com o laudo de vistoria inicial, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p054", "t": "Parágrafo 1º: Caso sejam constatados danos ou irregularidades de responsabilidade do LOCATÁRIO, este será comunicado para que possa providenciar os respectivos reparos no prazo de 05 (cinco) dias corridos, ou outro prazo acordado entre as partes, sem prejuízo da cobrança de eventuais valores necessários à recomposição do imóvel."}, {"id": "p055", "t": "Parágrafo 2º: Caso o LOCATÁRIO não realize os reparos de sua responsabilidade, o LOCADOR poderá providenciá-los e exigir o ressarcimento dos respectivos custos, mediante apresentação dos comprovantes pertinentes, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p056", "t": "Parágrafo 3º: A vistoria final será realizada sem custo para o LOCATÁRIO. Caso seja necessária nova vistoria para verificação dos reparos executados, poderá ser cobrada taxa de revistoria no valor de R$ 150,00 (cento e cinquenta reais), desde que previamente informada e relacionada à necessidade de nova verificação de pendências de responsabilidade do LOCATÁRIO."}, {"id": "p057", "t": "Parágrafo 4º: A existência de danos ou pendências apontadas na vistoria não impedirá o recebimento das chaves nem a formalização da devolução do imóvel, permanecendo assegurado ao LOCADOR o direito de exigir o ressarcimento dos prejuízos comprovadamente atribuíveis ao LOCATÁRIO."}, {"id": "p058", "t": "Cláusula 28º - O LOCATÁRIO permitirá que o LOCADOR ou seu representante devidamente autorizado examine ou vistori? o imóvel, mediante prévio agendamento e comunicação com antecedência mínima de 48 (quarenta e oito) horas, em dia e horário previamente acordados entre as partes, respeitado o direito à privacidade e ao uso pacífico do imóvel."}, {"id": "p059", "t": "Cláusula 29º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade residencial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "residencial"}, {"id": "p060", "t": "Cláusula 29º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade comercial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "comercial", "adaptado": true}, {"id": "p061", "t": "Cláusula 30º - Em caso de desapropriação do imóvel, a locação será extinta, ficando o LOCADOR desobrigado das obrigações futuras decorrentes deste contrato, ressalvados os direitos do LOCATÁRIO de pleitear eventual indenização diretamente perante o poder público desapropriante, quando legalmente cabível."}, {"id": "p062", "t": "Cláusula 31º - O LOCATÁRIO obriga-se a respeitar as normas de convivência, os direitos de vizinhança, as regras condominiais e a legislação vigente, abstendo-se de praticar atos que comprometam a segurança, a tranquilidade, a higiene ou o sossego dos demais moradores."}, {"id": "p063", "t": "Parágrafo primeiro: O descumprimento das obrigações legais ou contratuais poderá ensejar a aplicação das medidas cabíveis, inclusive rescisão da locação, conforme a natureza e a gravidade da infração, observadas as disposições da Lei nº 8.245/91."}, {"id": "p064", "t": "Parágrafo segundo: Fica estipulada multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente à época da infração, aplicável em caso de descumprimento contratual que justifique sua incidência, observados os critérios de proporcionalidade, a natureza da obrigação descumprida e a legislação vigente."}, {"id": "p065", "t": "Parágrafo terceiro: Na hipótese de devolução antecipada do imóvel por iniciativa do LOCATÁRIO durante o prazo determinado deste contrato, será devida multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente, calculada proporcionalmente ao período restante do contrato, conforme o artigo 4º da Lei nº 8.245/91."}, {"id": "p066", "t": "Cláusula 32º - Fica o LOCATÁRIO isento do pagamento de multa contratual por desocupação voluntária do imóvel após o 12º (décimo segundo) mês de locação, tendo, porém, a obrigação de avisar por escrito com, no mínimo, 30 (trinta) dias de antecedência, ficando responsável pelo pagamento do aluguel e dos acessórios locatícios durante o período de aviso.", "cond": "isencao_multa"}, {"id": "p067", "t": "Parágrafo primeiro: A isenção da multa rescisória apenas caberá em benefício do LOCATÁRIO, caso esteja quite com todas as demais obrigações previstas neste instrumento. Caso contrário fica estipulada a multa contratual compensatória proporcionalmente ao período de cumprimento do contrato, em conformidade com a nova redação do artigo 4º, atribuída pela Lei no 12.112/2009, na qual incorrerá o LOCATÁRIO na hipótese de devolução do imóvel antes do prazo pactuado.", "cond": "isencao_multa"}, {"id": "p068", "t": "Cláusula 33º - O LOCATÁRIO assume o formal compromisso de 30 (trinta) dias antes de desocupar o imóvel, notificar por escrito a ADMINISTRADORA que, efetuará uma vistoria no mesmo a fim de ficar constatado o estado de conservação do imóvel."}, {"id": "p069", "t": "Cláusula 34º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p070", "t": "Cláusula 35º - Após o término do prazo contratual, caso a locação prossiga por prazo indeterminado, o LOCATÁRIO poderá rescindir o contrato mediante comunicação por escrito ao LOCADOR ou à ADMINISTRADORA, com antecedência mínima de 30 (trinta) dias."}, {"id": "p071", "t": "Parágrafo único: Na ausência do aviso prévio previsto nesta cláusula, o LOCADOR poderá exigir quantia correspondente a 01 (um) mês de aluguel e encargos vigentes na data da rescisão, conforme disposto no artigo 6º, parágrafo único, da Lei nº 8.245/91."}, {"id": "p072", "t": "Cláusula 36º - Fica eleito o foro da comarca onde se localiza o imóvel objeto desta locação para dirimir quaisquer controvérsias decorrentes deste contrato, ressalvadas as hipóteses legais de competência absoluta."}, {"id": "p073", "t": "Parágrafo único: Em caso de demanda judicial decorrente do descumprimento das obrigações contratuais, as partes responderão pelas custas e despesas processuais, conforme a legislação vigente e eventual determinação judicial."}, {"id": "p074", "t": "Cláusula 37º - É vedado ao LOCATÁRIO ceder, transferir ou sublocar, total ou parcialmente, o imóvel objeto deste contrato, bem como emprestá-lo a terceiros, sem prévia autorização expressa e por escrito do LOCADOR, nos termos do artigo 13 da Lei nº 8.245/91."}, {"id": "p075", "t": "Cláusula 38º - Caso o LOCADOR pretenda vender o imóvel durante a vigência da locação, deverá assegurar ao LOCATÁRIO o direito de preferência para aquisição, em igualdade de condições com terceiros, mediante comunicação formal contendo todas as condições do negócio, inclusive preço, forma de pagamento e demais informações pertinentes, nos termos dos artigos 27 e seguintes da Lei nº 8.245/91."}, {"id": "p076", "t": "Parágrafo único: O LOCATÁRIO terá o prazo legal de 30 (trinta) dias, contado do recebimento da comunicação, para manifestar sua aceitação integral e inequívoca da proposta. Caso não exerça o direito de preferência, deverá permitir visitas de interessados, mediante prévio agendamento e em horários previamente acordados."}, {"id": "p077", "t": "Cláusula 39º - Ocorrendo interesse do LOCATÁRIO na compra do imóvel, sua manifestação deverá ser encaminhada por escrito, à ADMINISTRADORA, com a devida intervenção do corretor de imóveis da mesma empresa, a quem caberá a intermediação para a concretização do negócio."}, {"id": "p078", "t": "Cláusula 40º - A ADMINISTRADORA permanecerá responsável pela administração da locação durante a vigência deste contrato, observados os poderes que lhe foram conferidos pelo LOCADOR, inclusive quanto aos procedimentos de encerramento, entrega das chaves, apuração de encargos e prestação de contas, conforme o respectivo contrato de administração."}, {"id": "p079", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p080", "t": "Cláusula 41º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da estrutura e partes integrantes do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p081", "t": "Parágrafo primeiro: O LOCATÁRIO (S), poderá ele mesmo contratar e apresentar a apólice para a ADMINISTRADORA, porém, somente serão aceitas apólices que apresentarem seu pagamento integral."}, {"id": "p082", "t": "Parágrafo segundo: Quanto a atualização e renovação do seguro, o valor segurado a ser corrigido durante a vigência do presente contrato, deverá comprovar que a apólice em vigor cubra sempre o custo para reconstrução do imóvel, onde caberá ao LOCATARIO providenciar a renovação do seguro na época própria, dando ciência ao LOCADOR ou a ADMINISTRADORA."}, {"id": "p083", "t": "Cláusula 42º - O descumprimento da obrigação de contratação ou renovação do seguro contra incêndio, após notificação para regularização, poderá caracterizar infração contratual, sujeitando o LOCATÁRIO às medidas legais e contratuais cabíveis."}, {"id": "p084", "t": "Cláusula 43º - Em se tratando de edifício, fica desde já convencionado que não serão aceitas apólices coletivas de condomínio em substituição ao seguro incêndio individual."}, {"id": "p085", "t": "Cláusula 44º - Caso o LOCATÁRIO não apresente a apólice de seguro contratada por sua iniciativa dentro do prazo estabelecido, o LOCADOR poderá providenciar a contratação do seguro, mediante prévia comunicação ao LOCATÁRIO, sendo os respectivos custos de responsabilidade deste, desde que comprovados documentalmente. Os valores poderão ser incluídos no boleto de aluguel, observadas as condições e os prazos de pagamento informados pela ADMINISTRADORA."}, {"id": "p086", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p087", "t": "Cláusula 45º - As partes declaram estar cientes de que a ADMINISTRADORA poderá coletar, armazenar, utilizar e compartilhar os dados pessoais estritamente necessários à execução deste contrato, ao cumprimento de obrigações legais e regulatórias, bem como à proteção do crédito, observadas as bases legais previstas no artigo 7º, incisos II, V e X, da Lei nº 13.709/2018 (Lei Geral de Proteção de Dados Pessoais – LGPD)."}, {"id": "p088", "t": "Cláusula 46º - O tratamento de dados pessoais para finalidades adicionais, não abrangidas pelas hipóteses legais previstas na cláusula anterior, dependerá da existência de base legal adequada, inclusive consentimento específico do titular, quando necessário, assegurados os direitos previstos na Lei nº 13.709/2018."}, {"id": "p089", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p090", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p091", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IPCA (Índice Nacional de Preços ao Consumidor Amplo); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p092", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O LOCADOR declara ser o legítimo proprietário e/ou possuidor do Imóvel, o qual se encontra livre e desonerado de quaisquer direitos, obrigações e ônus, judiciais e/ou extrajudiciais, que possam comprometer este CONTRATO, assumindo o dever de indenizar e manter o LOCATÁRIO e a ADMINISTRADORA indenes de quaisquer responsabilidades decorrentes de medidas que comprometam a sua posse e propriedade sobre o Imóvel. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Qualquer alteração nos endereços eletrônicos de e-mail constantes no cadastro prévio realizado deverá ser prontamente comunicada à ADMINISTRADORA por instrumento que comprove a total ciência da imobiliária quanto a aludida mudança. Em se tratando de LOCATÁRIO pessoa jurídica, que seja obrigado ao pagamento de imposto de renda retido na fonte (IRRF) quando do pagamento do aluguel, compromete-se o LOCATÁRIO a apresentar mensalmente à ADMINISTRADORA os comprovantes de recolhimento do IRRF, na forma calculada no boleto emitido para pagamento do aluguel, sob pena de ser responsável por quaisquer valores despendidos pelo LOCADOR perante a Receita Federal do Brasil, mesmo que apurados após a extinção do presente instrumento. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p093", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p094", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p095", "t": "[[ASSINATURAS]]"}]$mod$::jsonb, 'Texto-base enviado por Denis (16/11/2026)')
ON CONFLICT DO NOTHING;
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, 'caucao_imovel', 1, $mod$Caução de imóvel (caucionamento)$mod$, 'comercial', 'caucao', NULL, $mod$CAUCIONAMENTO DE IMÓVEL$mod$, $mod$[{"id": "p001", "t": "PRÊAMBULO"}, {"id": "p002", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p003", "t": "[[LOCADOR]]"}, {"id": "p004", "t": "[[LOCATARIO]]"}, {"id": "p005", "t": "ADMINISTRADORA: [ADMINISTRADORA_QUALIFICACAO]; cuja a administração do referido imóvel perdurará durante o prazo de vigência do presente Contrato de Locação, estendendo-se até a data da efetiva entrega das chaves, estando cientes as partes celebrantes deste instrumento de que toda e qualquer questão decorrente deste deverá ser tratada prévia e diretamente junto à ADMINISTRADORA, sendo que o não cumprimento desta cláusula, poderá dar ensejo às medidas cabíveis de rescisão contratual por culpa da parte infratora, ou outras medidas cabíveis, além de isenção de responsabilidade da ADMINISTRADORA."}, {"id": "p006", "t": "GARANTIA LOCATÍCIA: CAUCIONAMENTO – Comparece também neste ato na qualidade de CAUCIONANTE: [CAUCIONANTE_QUALIFICACAO]"}, {"id": "p007", "t": "Parágrafo primeiro: A CAUCIONANTE qualificada neste contrato, dá como CAUÇÃO, na forma do artigo 37, inciso I e 38, § 1º da Lei 8.245/91, o imóvel assim descrito: [CAUCAO_IMOVEL_DESCRICAO] Registro de Imóveis de [CAUCAO_IMOVEL_CARTORIO] – Matrícula [CAUCAO_IMOVEL_MATRICULA]"}, {"id": "p008", "t": "Parágrafo segundo: A CAUCIONANTE autoriza expressamente o registro e averbação deste contrato junto ao Cartório de Imóveis competente, bem como o caucionamento do imóvel descrito na cláusula acima, através do presente contrato, em favor da locação do imóvel situado na [IMOVEL_ENDERECO] inclusive requerendo a LOCADORA, perante o cartório competente a averbação de tal garantia na matrícula do imóvel."}, {"id": "p009", "t": "Parágrafo terceiro: Conforme livremente pactuado entre as partes todas as despesas com a Referida averbação são de exclusiva responsabilidade da CAUCIONANTE, podendo a proprietária ou a imobiliária intermediadora efetuar o pagamento e emitir juntamente com o valor do locatício a cobrança da referida averbação"}, {"id": "p010", "t": "[[OBJETO]]"}, {"id": "p011", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p012", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p013", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso COMERCIAL dos LOCATÁRIO (S).", "dest": "comercial"}, {"id": "p014", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso de MORADIA dos LOCATÁRIO (S).", "dest": "residencial", "adaptado": true}, {"id": "p015", "t": "[[PRAZO]]"}, {"id": "p016", "t": "Cláusula 1º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), conforme acordado entre as partes e o(a) LOCATÁRIO(A) se compromete a pagar pontualmente até o dia [DIA_VENCIMENTO] de cada mês subsequente."}, {"id": "p017", "t": "Cláusula 2º - O primeiro aluguel será pago 30 dias após a data de entrega das chaves e os aluguéis subsequentes, serão pagos na data de vencimento fixada neste documento."}, {"id": "p018", "t": "[[ADICIONAIS]]"}, {"id": "p019", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p020", "t": "O valor do aluguel pode ser acrescido de acessórios locatícios e encargos, se aplicável, conforme estipulado neste contrato. O cômputo desses encargos será a partir da posse da chave e serão cobrados juntamente com o aluguel na data estabelecida."}, {"id": "p021", "t": "Cláusula 3º - O aluguel mensal deve ser pago juntamente com os demais encargos, em moeda corrente nacional, em seu vencimento, ficando em caso contrário acrescidos de multa de 10% (dez por cento) do seu valor, mais juros de 1% (um por cento) ao mês, mais a correção monetária prevista em lei, a título de penalidade contratual, sem prejuízo da exigibilidade das demais correções estipuladas."}, {"id": "p022", "t": "Cláusula 4º - O pagamento dos alugueis e encargos locatícios devem ser realizados por meio de boleto bancário, que será emitido pela ADMINISTRADORA."}, {"id": "p023", "t": "Cláusula 5º - Caso o LOCATÁRIO não receba o boleto com a cobrança em ate 02 (dois) dias úteis antes do vencimento, será de responsabilidade do mesmo, entrar em contato com a ADMINISTRADORA para solicitar a emissão da 2º via de boleto."}, {"id": "p024", "t": "Cláusula 6º - O inadimplemento do aluguel ou de quaisquer encargos locatícios na data do vencimento constituirá o LOCATÁRIO em mora, facultando ao LOCADOR promover as medidas judiciais e extrajudiciais cabíveis, inclusive ação de despejo e cobrança, nos termos da Lei nº 8.245/91, sem prejuízo da incidência da multa, juros, correção monetária, honorários advocatícios e demais penalidades previstas neste contrato."}, {"id": "p025", "t": "Cláusula 7º - O LOCATÁRIO(S) não terá direito a reter o pagamento do aluguel ou de qualquer outra quantia devida nos termos do presente contrato, sob a alegação de não terem sido atendidas exigências porventura solicitadas."}, {"id": "p026", "t": "Cláusula 8º – O LOCATÁRIO(S) fica ciente nesta data que, antes da propositura da ação de despejo por falta de pagamento do aluguel e encargos na data estipulada neste contrato, poderá haver o protesto, junto ao cartório competente."}, {"id": "p027", "t": "Cláusula 9º - Eventual inadimplência do aluguel e encargos por parte dos LOCATÁRIO (S), ensejará Ação Judicial, independente do prazo da mora, não se responsabilizando o LOCADOR(A) pela inclusão dos nomes dos devedores ou de seus Fiadores junto às entidades mantenedoras de bancos de proteção ao crédito, SERASA, SCPC etc."}, {"id": "p028", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p029", "t": "O valor do aluguel ora contratado sofrerá reajuste anualmente, em conformidade com a legislação específica. Entretanto, havendo alteração legal para nova periodicidade, esta será aplicada automaticamente, independentemente de confirmação das partes."}, {"id": "p030", "t": "INDEXADORES:"}, {"id": "p031", "t": "As partes de comum acordo estabelecem o índice IPCA (Índice Nacional de Preços ao Consumidor Amplo), para a correção do aluguel, que será aplicado de acordo com a periodicidade acima. Havendo a extinção do mesmo, por determinação legal, as partes elegerão seu substituto imediatamente após a eventual extinção."}, {"id": "p032", "t": "Cláusula 10º - O LOCATÁRIO autoriza a ADMINISTRADORA a incluir, juntamente com o boleto do aluguel, os valores referentes ao IPTU e às despesas condominiais, ainda que correspondentes ao período vincendo, para fins de repasse ao LOCADOR e pagamento dentro dos respectivos vencimentos, comprometendo-se ao pagamento integral desses encargos na forma estabelecida neste contrato."}, {"id": "p033", "t": "Cláusula 11º - No caso dos carnês e/ou avisos dos tributos citados na cláusula acima serem entregues diretamente ao LOCATÁRIO (S), este deverá encaminhá-los ao endereço da ADMINISTRADORA, antes do vencimento dos títulos no prazo de até 5 (cinco) dias úteis, sob pena de responderem pelas multas do atraso."}, {"id": "p034", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p035", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p036", "t": "Cláusula 12º – O LOCATÁRIO obriga-se a providenciar, junto às concessionárias competentes, a transferência da titularidade das contas de ÁGUA, ENERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade das referidas contas, por parte do LOCATÁRIO, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p037", "t": "Cláusula 13º – O descumprimento da obrigação prevista na CLÁUSULA 12º, autoriza o LOCADOR a reter as chaves até a devida apresentação dos respectivos comprovantes, sem que isso gere qualquer direito de indenização ou alegação de atraso na imissão da posse por parte do LOCATÁRIO."}, {"id": "p038", "t": "Cláusula 14º - O LOCATÁRIO declara receber, nesta data, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso COMERCIAL.", "dest": "comercial"}, {"id": "p039", "t": "Cláusula 14º - O LOCATÁRIO declara receber, nesta data, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso para HABITAÇÃO.", "dest": "residencial", "adaptado": true}, {"id": "p040", "t": "Cláusula 15º - Em caso de discordância do laudo de vistoria inicial, o LOCATÁRIO terá o prazo de 10 (dez) dias corridos para realizar sua contestação, mediante formalização por email ou notificação por correios. O silêncio será considerado concordância ao laudo inicial apresentado."}, {"id": "p041", "t": "Cláusula 16º - Fica terminantemente proibida a colocação de pregos e parafusos nas paredes ou executar furos nos azulejos. Caso o LOCATÁRIO necessite fixar armários de cozinha ou outros, deverá solicitar autorização por escrito ao LOCADOR, ocasião em que, uma vez autorizado, receberá uma cópia da planta hidráulica e elétrica do imóvel."}, {"id": "p042", "t": "Cláusula 17º - A repintura no imóvel ora locado por parte do LOCATÁRIO, deverá ser compatível com a tinta anterior, ou seja, nas mesmas cores e qualidade que foi entregue."}, {"id": "p043", "t": "Cláusula 18º - Os pisos, azulejos, armários modulados, ou qualquer item de acabamento do imóvel ora locado por parte do LOCATÁRIO, deverá ser entregue nas mesmas condições recebidas, ou seja, caso danifique algum desses itens, o mesmo deverá ser substituído pelo mesmo modelo, tamanho, marca e nas mesmas cores e qualidade que foi entregue."}, {"id": "p044", "t": "Cláusula 19º - Caso algum piso seja danificado e o LOCATÁRIO não encontre o mesmo modelo disponível para compra, ou tenha saído de fabricação, deverá consultar o LOCADOR, através da ADMINISTRADORA, um outro modelo compatível aceito para substituição de todos os pisos e em todos os ambientes que o integram, arcando o LOCATÁRIO com todo o custo de material e instalação."}, {"id": "p045", "t": "Cláusula 20º - Fica o LOCATÁRIO, responsável pela verificação da voltagem da corrente elétrica existente no imóvel, em todos os seus pontos, assumindo para si, eventuais danos em aparelhos e/ou equipamentos que sejam ligados sem a devida checagem."}, {"id": "p046", "t": "Cláusula 21º - O LOCATÁRIO não poderá realizar modificações, alterações ou introduzir benfeitorias no imóvel sem a prévia e expressa autorização por escrito do LOCADOR. As benfeitorias realizadas, ainda que autorizadas, incorporar-se-ão ao imóvel, não assistindo ao LOCATÁRIO direito de retenção ou indenização, inclusive quanto às benfeitorias úteis e voluptuárias, nos termos da Lei nº 8.245/91, salvo disposição expressa em contrário firmada entre as partes. As benfeitorias expressamente autorizadas pelo LOCADOR para realização pelo LOCATÁRIO encontram-se descritas em cláusula adicional deste contrato, devendo ser observadas as condições nela estabelecidas."}, {"id": "p047", "t": "Cláusula 22º - São de responsabilidade do LOCATÁRIO as obras de manutenção do imóvel, cabendo exclusivamente ao LOCADOR aquelas que importem na estrutura e segurança dele, nos termos da legislação vigente. I): Sendo necessária a realização de qualquer obra ou manutenção por parte do LOCADOR, o LOCATÁRIO deverá notifica-lo para que no prazo de até 05 (cinco) dias úteis do recebimento da notificação, dar início aos reparos necessários. Não sendo realizados, fica desde já autorizado o LOCATÁRIO a realizar três orçamentos e providenciar a realização dos reparos que importem a estrutura ou segurança do imóvel e cobrá-los do LOCADOR pelo menor preço orçado."}, {"id": "p048", "t": "Cláusula 23º - Fica ainda facultado ao LOCADOR quando lhe convier, exigir a remoção de benfeitorias introduzidas no imóvel sem sua autorização, correndo todas as despesas por conta do LOCATÁRIO."}, {"id": "p049", "t": "Cláusula 24º - Se na VISTORIA FINAL for constatado qualquer anormalidade no imóvel, o LOCATÁRIO será notificado no prazo de 05 (cinco) dias corridos, para reparar o defeito ou substituir as peças ou aparelhos defeituosos por sua conta e risco. Não atendida esta notificação, ficará facultado ao LOCADOR providenciar os serviços, cobrando do LOCATÁRIO, os valores gastos com material e mão de obra, além dos dias de aluguel necessários para tais reparos."}, {"id": "p050", "t": "Parágrafo único: As partes concordam que a vistoria final do imóvel será realizada sem qualquer custo para o LOCATÁRIO. Contudo, caso seja necessária a realização de uma revistoria, será cobrada uma taxa de R$ 120,00 (cento e vinte) reais para cobrir custos envolvidos."}, {"id": "p051", "t": "Cláusula 25º - O LOCATÁRIO desde já, faculta o LOCADOR, ou seu representante devidamente constituído, examinar ou vistoriar o imóvel locado, quando entender conveniente, com aviso de 48 (quarenta e oito) horas de antecedência."}, {"id": "p052", "t": "Cláusula 26º - O presente contrato poderá ser rescindido de pleno direito na hipótese de desapropriação, incêndio ou qualquer evento que torne o imóvel impróprio para uso e exija sua reconstrução, total ou parcial, impossibilitando sua utilização por período superior a 45 (quarenta e cinco) dias. Poderá, ainda, ser rescindido em caso de insolvência, recuperação judicial ou falência do LOCATÁRIO, quando aplicável, sem prejuízo das demais hipóteses previstas neste contrato e da incidência da multa contratual estabelecida na CLÁUSULA 28º."}, {"id": "p053", "t": "Cláusula 27º - No caso de desapropriação do imóvel locado, ficará o LOCADOR desobrigado por todas as cláusulas deste contrato, ressalvando-se ao LOCATÁRIO tão somente o direito de haver do poder público desapropriante a indenização a que porventura tenha direito."}, {"id": "p054", "t": "Cláusula 28º - O LOCATÁRIO é obrigado a respeitar os direitos de vizinhança, a lei do silêncio, regras de condomínio, evitando a prática de quaisquer atos que venham a perturbar a tranquilidade e as condições de saúde pública."}, {"id": "p055", "t": "Parágrafo primeiro: Ocorrerá também a rescisão do presente contrato se o LOCATÁRIO infringir obrigação legal ou cometer infração a qualquer uma das cláusulas do presente instrumento."}, {"id": "p056", "t": "Parágrafo segundo: Fica estipulada a multa contratual compensatória proporcional de 03 (três) vezes o valor do aluguel vigente da época da eventual infração, em benefício ao LOCADOR, sem prejuízo da exigibilidade das obrigações assumidas por este instrumento, podendo o LOCADOR, se assim lhe convier, considerar ao mesmo tempo rescindido o presente contrato de locação, independentemente de qualquer formalidade."}, {"id": "p057", "t": "Cláusula 29º - O LOCATÁRIO assume o formal compromisso de 30 (trinta) dias antes de desocupar o imóvel, notificar por escrito a ADMINISTRADORA que, efetuará uma vistoria no mesmo a fim de ficar constatado o estado de conservação do imóvel."}, {"id": "p058", "t": "Cláusula 30º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p059", "t": "Cláusula 31º - Decorrido o PRAZO DA LOCAÇÃO e estando a locação vigorando por prazo indeterminado, o LOCATÁRIO poderá rescindir o contrato de locação mediante notificação por escrito á ADMINISTRADORA, com antecedência de 30 (trinta) dias da devolução das chaves."}, {"id": "p060", "t": "Parágrafo único: Na ausência do aviso acima citado, o LOCADOR poderá exigir a quantia correspondente a 01 (um) mês de aluguel e encargos vigentes da data da rescisão, conforme autoriza o artigo 6º, da Lei no 8.245/91."}, {"id": "p061", "t": "Cláusula 32º - Fica eleito o foro da comarca onde se localiza o imóvel objeto da locação para dirimir quaisquer controvérsias oriundas deste contrato, com renúncia expressa de qualquer outro, por mais privilegiado que seja. Em qualquer procedimento judicial decorrente do descumprimento das obrigações assumidas neste contrato pelo LOCATÁRIO, este responderá pelo pagamento das custas processuais, despesas judiciais e honorários advocatícios, na forma da legislação vigente e conforme fixação judicial, quando cabível."}, {"id": "p062", "t": "Parágrafo único: Em qualquer procedimento judicial que o LOCATÁRIO der causa, correrão por sua conta além do principal, todas as custas e despesas oriundas desta medida e ainda, honorários advocatícios, mesmo em caso de purgação de mora, quando houver a propositura da ação ou logo após a distribuição da petição."}, {"id": "p063", "t": "Cláusula 33º - Não é permitida a transferência deste contrato, no todo ou em parte, a sublocação ou empréstimo do imóvel locado, sem prévio consentimento, por escrito do LOCADOR."}, {"id": "p064", "t": "Parágrafo único: Em caso de falecimento, separação de fato ou judicial, divórcio ou dissolução da união estável do LOCATÁRIO, esta locação prosseguirá automaticamente com seu cônjuge ou companheiro, este que permanecer no imóvel, nos termos da Lei."}, {"id": "p065", "t": "Cláusula 34º - Caso o imóvel seja colocado à venda, o LOCATÁRIO terá preferência na compra. Não havendo interesse no prazo de 30 (trinta) dias, o LOCATÁRIO deverá permitir e facilitar as visitas dos pretendentes ao mesmo, em conformidade com o artigo 27, da Lei no 8.245/91."}, {"id": "p066", "t": "Cláusula 35º - Ocorrendo interesse do LOCATÁRIO na compra do imóvel, sua manifestação deverá ser encaminhada por escrito, à ADMINISTRADORA, com a devida intervenção do corretor de imóveis da mesma empresa, a quem caberá a intermediação para a concretização do negócio."}, {"id": "p067", "t": "Cláusula 36º - A administração exercida pela ADMINISTRADORA permanecerá vigente até a efetiva entrega das chaves pelo LOCATÁRIO e a quitação integral de todas as obrigações decorrentes da presente locação, inclusive aluguéis, encargos, multas, indenizações e demais valores eventualmente pendentes, o que ocorrer por último."}, {"id": "p068", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p069", "t": "Cláusula 37º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da parte perecível do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p070", "t": "Parágrafo primeiro: O LOCATÁRIO (S), poderá ele mesmo contratar e apresentar a apólice para a ADMINISTRADORA, porém, somente serão aceitas apólices que apresentarem seu pagamento integral."}, {"id": "p071", "t": "Parágrafo segundo: Quanto a atualização e renovação do seguro, o valor segurado a ser corrigido durante a vigência do presente contrato, deverá comprovar que a apólice em vigor cubra sempre o custo para reconstrução do imóvel, onde caberá ao LOCATARIO providenciar a renovação do seguro na época própria, dando ciência ao LOCADOR ou a ADMINISTRADORA."}, {"id": "p072", "t": "Cláusula 38º - A falta do pagamento do seguro por parte do LOCATÁRIO, constituirá infração passível de rescisão do presente instrumento, independente da incidência da multa infracional prevista em contrato."}, {"id": "p073", "t": "Cláusula 39º - Tratando-se de unidade integrante de condomínio edilício, não será aceita a apólice coletiva contratada pelo condomínio em substituição ao seguro contra incêndio previsto na CLÁUSULA 37º, permanecendo o LOCATÁRIO obrigado ao cumprimento integral da obrigação contratual."}, {"id": "p074", "t": "Cláusula 40º - Caso o LOCATÁRIO não apresente sua apólice contratada de forma particular à ADMINISTRADORA, ficará o LOCADOR automaticamente autorizado a contratar uma empresa Seguradora de sua preferência e lançar seus valores à vista na primeira parcela de cobrança de aluguel. As renovações serão cobradas automaticamente no boleto de pagamento do aluguel."}, {"id": "p075", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p076", "t": "Cláusula 41º - As partes declaram expresso consentimento que a ADMINISTRADORA irá coletar, tratar e compartilhar os dados necessários ao cumprimento do contrato, nos termos do art. 7°, inciso V da Lei Geral de Proteção de Dados, bem como os dados necessários para o cumprimento de obrigações legais, nos termos do art. 7°, inciso II da LGPD e os dados, se necessários para proteção de crédito, conforme autorizado, também pelo art. 7° inciso V da LGPD."}, {"id": "p077", "t": "Cláusula 42º - Outros dados poderão ser coletados, tratados e compartilhados para fins administrativos da imobiliária, conforme termo de consentimento específico."}, {"id": "p078", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p079", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p080", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IPCA (Índice Nacional de Preços ao Consumidor Amplo); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p081", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O LOCADOR declara ser o legítimo proprietário e/ou possuidor do Imóvel, o qual se encontra livre e desonerado de quaisquer direitos, obrigações e ônus, judiciais e/ou extrajudiciais, que possam comprometer este CONTRATO, assumindo o dever de indenizar e manter o LOCATÁRIO e a ADMINISTRADORA indenes de quaisquer responsabilidades decorrentes de medidas que comprometam a sua posse e propriedade sobre o Imóvel. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Qualquer alteração nos endereços eletrônicos de e-mail constantes no cadastro prévio realizado deverá ser prontamente comunicada à ADMINISTRADORA por instrumento que comprove a total ciência da imobiliária quanto a aludida mudança. Em se tratando de LOCATÁRIO pessoa jurídica, que seja obrigado ao pagamento de imposto de renda retido na fonte (IRRF) quando do pagamento do aluguel, compromete-se o LOCATÁRIO a apresentar mensalmente à ADMINISTRADORA os comprovantes de recolhimento do IRRF, na forma calculada no boleto emitido para pagamento do aluguel, sob pena de ser responsável por quaisquer valores despendidos pelo LOCADOR perante a Receita Federal do Brasil, mesmo que apurados após a extinção do presente instrumento. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p082", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p083", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p084", "t": "[[ASSINATURAS]]"}]$mod$::jsonb, 'Texto-base enviado por Denis (16/11/2026)')
ON CONFLICT DO NOTHING;
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, 'seguro_porto', 1, $mod$Seguro-fiança Porto Seguro$mod$, 'residencial', 'seguro_fianca', 'porto', $mod$SEGURO FIANÇA PORTO SEGURO$mod$, $mod$[{"id": "p001", "t": "QUADRO RESUMO: Locador(es); Locatário(a); Administradora; Imóvel; Destinação da Locação; Prazo da Locação; Valor e Vencimento do Aluguel; Primeiro Aluguel; Reajuste e Indexador; Encargos Locatícios; Contas de Consumo; Transferência de Titularidade; Garantia Locatícia; Inadimplência; Vistoria Inicial; Contestação da Vistoria; Conservação e Manutenção do Imóvel; Benfeitorias e Modificações; Vistoria Final e Revistoria; Rescisão e Multa Contratual; Desocupação e Aviso Prévio; Seguro Incêndio; Sublocação/Cessão; Preferência na Compra do Imóvel; Administração do Imóvel; LGPD; Disposições Gerais; Foro."}, {"id": "p002", "t": "PRÊAMBULO"}, {"id": "p003", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p004", "t": "[[LOCADOR]]"}, {"id": "p005", "t": "[[LOCATARIO]]"}, {"id": "p006", "t": "ADMINISTRADORA: [ADMINISTRADORA_QUALIFICACAO]; cuja a administração do referido imóvel perdurará durante o prazo de vigência do presente Contrato de Locação, estendendo-se até a data da efetiva entrega das chaves, estando cientes as partes celebrantes deste instrumento de que toda e qualquer questão decorrente deste deverá ser tratada prévia e diretamente junto à ADMINISTRADORA, sendo que o não cumprimento desta cláusula, poderá dar ensejo às medidas cabíveis de rescisão contratual por culpa da parte infratora, ou outras medidas cabíveis, além de isenção de responsabilidade da ADMINISTRADORA."}, {"id": "p007", "t": "GARANTIA LOCATÍCIA: O seguro de Fiança Locatícia contratado pelo LOCADOR junto a PORTO SEGURO CIA. DE SEGUROS GERAIS, em que a vigência inicial será a data de protocolo da proposta ou data distinta acordada entre as partes e a vigência final será a data do término do contrato de locação, garantirá está locação, nos termos do inciso III, do artigo 37 da Lei do Inquilinato, mediante pagamento de prêmio, ressalvadas as exceções previstas nas condições gerais.", "trava": true}, {"id": "p008", "t": "A PORTO SEGURO CIA. DE SEGUROS GERAIS, disponibiliza a possibilidade de contratação de produtos com condições diferentes em relação ao Limite Máximo de Garantia (LMG).", "trava": true}, {"id": "p009", "t": "No SEGURO FIANÇA LOCATÍCIA TRADICIONAL, o LMG é a soma dos limites máximos de indenização (LMI) das coberturas contratadas. No SEGURO FIANÇA LOCATÍCIA ESSENCIAL, o LMG da apólice é igual ao LMI da cobertura de ALUGUEL. Quando contratada apenas a Cobertura Básica - Não Pagamento de Aluguéis, o Limite Máximo de Garantia da apólice será igual ao Limite Máximo de Indenização desta mesma cobertura. Quando houver a contratação de coberturas adicionais, o Limite Máximo de Garantia da apólice será menor que a soma dos Limites Máximos de Indenização das coberturas contratadas. São de conhecimento do LOCADOR e LOCATÁRIO as Condições Gerais do seguro de Fiança Locatícia, sendo que para a contratação da apólice, LOCADOR e LOCATÁRIO definiram previamente, mediante acordo, a seguradora, o corretor de seguros e os limites da apólice.", "trava": true}, {"id": "p010", "t": "Para efeito desta garantia, LOCADOR e LOCATÁRIO acordam que os prêmios iniciais e renovações do seguro da fiança locatícia, calculados conforme NORMAS VIGENTES, serão pagos pelo LOCATÁRIOS,de acordo com o inciso XI, do artigo 23 da lei do inquilinato, sob pena de rescisão desta locação, com o consequente despejo e cancelamento da apólice.", "trava": true}, {"id": "p011", "t": "Na hipótese de inadimplência do LOCATÁRIO, o LOCADOR poderá efetuar o pagamento dos prêmios, para que a apólice permaneça vigente. Em caso de prorrogação do contrato de locação, com alterações que influenciam nas condições iniciais de aceitação, a seguradora se reservará ao direito de realizar nova análise do risco.", "trava": true}, {"id": "p012", "t": "LOCADOR e LOCATÁRIO declaram que até a data da contratação do seguro, todas as obrigações contratuais foram cumpridas pelas partes, tendo o LOCATÁRIO adimplido pontualmente todos os aluguéis e encargos da locação. Declaram ainda que não há sinistro a reclamar, quanto a aluguéis e encargos, bem como estão cientes que não haverá cobertura securitária para os aluguéis e encargos vencidos e vincendos, caso seja identificado que o primeiro inadimplemento tenha ocorrido antes da contratação do seguro, ficando a seguradora, desobrigada e isenta de toda e qualquer responsabilidade, ainda que haja reclamação futura de inadimplência anterior a data de contratação do seguro A apólice garantirá exclusivamente as coberturas especificadas na proposta de seguro.", "trava": true}, {"id": "p013", "t": "Eventuais débitos decorrentes do presente contrato, não pagos pelo LOCATÁRIO após regularmente instados a tanto serão comunicados às entidades mantenedoras de bancos de dados de proteção ao crédito (Serasa, SPC, etc.), quer pelos Locadores, quer pela Seguradora, quer pela Administradora. Tais débitos incluem todas as despesas com as medidas judiciais cabíveis. Notificações em geral, inclusive sobre eventuais débitos decorrentes do presente contrato poderão ser realizadas ao(s) LOCATÁRIO(S), via e-mail.", "trava": true}, {"id": "p014", "t": "Cláusula 1º - Pagamento do prêmio pelo locador/proprietário", "trava": true}, {"id": "p015", "t": "O seguro de Fiança Locatícia contratado pelo(s) LOCADOR(ES) junto a PORTO SEGURO CIA. DE SEGUROS GERAIS, em que a vigência inicial será a data de protocolo da proposta ou data distinta acordada entre as partes e a vigência final será a data do término do contrato de locação, garantirá está locação, nos termos do inciso III, do artigo 37 da Lei do Inquilinato, mediante pagamento de prêmio, ressalvadas as exceções previstas nas condições gerais.", "trava": true}, {"id": "p016", "t": "A PORTO SEGURO CIA. DE SEGUROS GERAIS, disponibiliza a possibilidade de contratação de produtos com condições diferentes em relação ao Limite Máximo de Garantia (LMG).", "trava": true}, {"id": "p017", "t": "No SEGURO FIANÇA LOCATÍCIA TRADICIONAL, o LMG é a soma dos limites máximos de indenização (LMI) das coberturas contratadas No SEGURO FIANÇA LOCATÍCIA ESSENCIAL, o LMG da apólice é igual ao LMI da cobertura de ALUGUEL. Quando contratada apenas a Cobertura Básica - Não Pagamento de Aluguéis, o Limite Máximo de Garantia da apólice será igual ao Limite Máximo de Indenização desta mesma cobertura. Quando houver a contratação de coberturas adicionais, o Limite Máximo de Garantia da apólice será menor que a soma dos Limites Máximos de Indenização das coberturas contratadas.", "trava": true}, {"id": "p018", "t": "São de conhecimento do(s) LOCADOR(ES) e LOCATÁRIO(S) as Condições Gerais do seguro de Fiança Locatícia, sendo que para a contratação da apólice, LOCADOR(ES) e LOCATÁRIO(S) definiram previamente, mediante acordo, a seguradora, o corretor de seguros e os limites da apólice. Para efeito desta garantia, os prêmios iniciais e renovações do seguro da fiança locatícia, calculados conforme NORMAS VIGENTES, serão pagos pelo LOCADOR(ES).", "trava": true}, {"id": "p019", "t": "Em caso de prorrogação do contrato de locação, com alterações que influenciam nas condições iniciais de aceitação, a seguradora se reservará ao direito de realizar nova análise do risco.", "trava": true}, {"id": "p020", "t": "LOCADOR(ES) e LOCATÁRIO (S) declaram que até a data da contratação do seguro, todas as obrigações contratuais foram cumpridas pelas partes, tendo o LOCATÁRIO(S) adimplido pontualmente todos os aluguéis e encargos da locação. Declaram ainda que não há sinistro a reclamar, quanto a aluguéis e encargos, bem como estão cientes que não haverá cobertura securitária para os aluguéis e encargos vencidos e vincendos, caso seja identificado que o primeiro inadimplemento tenha ocorrido antes da contratação do seguro, ficando a seguradora, desobrigada e isenta de toda e qualquer responsabilidade, ainda que haja reclamação futura de inadimplência anterior a data de contratação do seguro.", "trava": true}, {"id": "p021", "t": "A apólice garantirá exclusivamente as coberturas especificadas na proposta de seguro. Eventuais débitos decorrentes do presente contrato, não pagos pelo(s) LOCATÁRIO(S) após regularmente instados a tanto serão comunicados às entidades mantenedoras de bancos de dados de proteção ao crédito (Serasa, SPC, etc.), quer pelos Locadores, quer pela Seguradora. Tais débitos incluem todas as despesas com as medidas judiciais cabíveis.", "trava": true}, {"id": "p022", "t": "Notificações em geral, inclusive sobre eventuais débitos decorrentes do presente contrato poderão ser realizadas ao(s) LOCATÁRIO(S), via e-mail.", "trava": true}, {"id": "p023", "t": "Cláusula 2º - (quando contratada a cobertura adicional de danos ao imóvel)", "trava": true}, {"id": "p024", "t": "LOCADOR (es) e LOCATÁRIO(s) declara(m) que o Laudo de Vistoria Inicial, com descrição do estado do imóvel, foi elaborado antes da posse do imóvel, bem como o(s) LOCATÁRIO(s) concorda(m) com o conteúdo do laudo. O(s) LOCATÁRIO(s) declaram para todos os fins e efeitos de direito, que recebe(m) o imóvel locado no estado em que se encontra de conservação e uso, identificado no Relatório referente ao estado de uso e conservação do imóvel o qual é parte integrante deste contrato, assinado por todos os contratantes, obrigando-se e comprometendo-se a devolvê-lo nesse estado, independentemente de qualquer aviso ou notificação prévia, e qualquer que seja o motivo de devolução, sob pena de incorrer nas cominações previstas neste contrato ou estipuladas em lei, além da obrigação de indenizar por danos ou prejuízos decorrentes da inobservância dessa obrigação, salvo as deteriorações decorrentes do uso normal do imóvel.", "trava": true}, {"id": "p025", "t": "Cláusula 3º - (quando contratada a cobertura adicional de pintura interna)", "trava": true}, {"id": "p026", "t": "LOCADOR (es) e LOCATÁRIO(s) declara(m) que o Laudo de Vistoria Inicial, com descrição do estado[ do imóvel, foi elaborado antes da posse do imóvel, bem como o(s) LOCATÁRIO(s) concorda(m) com o conteúdo do laudo. Declara(m) o(s) locatário(s), para todos os fins e efeitos de direito, que recebe(m) o imóvel locado com Pintura Interna NOVA, e assim obriga-se, ao final da locação, a pintá-lo e devolvê-lo no mesmo estado em que recebeu, sob pena de incorrer nas cominações previstas neste contrato ou estipuladas em lei. O(s) locatário(s) declara(m) ainda estar ciente de que, não devolvendo o imóvel pintado internamente, a Seguradora indenizará o locador pelo ônus da pintura, e terá direito de reaver o valor que tiver sido pago. O Segurado poderá comunicar o Sinistro a Porto Seguro no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel.", "trava": true}, {"id": "p027", "t": "Cláusula 4º - (quando contratada a cobertura adicional de pintura externa)", "trava": true}, {"id": "p028", "t": "LOCADOR e LOCATÁRIO declara que o Laudo de Vistoria Inicial, com descrição do estado do imóvel, foi elaborado antes da posse do imóvel, bem como o LOCATÁRIO concorda com o conteúdo do laudo. Declara(m) o(s) locatário(s), para todos os fins e efeitos de direito, que recebe(m) o imóvel locado com Pintura Externa NOVA, e assim obriga-se, ao final da locação, a pintá-lo e devolvê-lo no mesmo estado que recebeu, sob pena de incorrer nas cominações previstas neste contrato ou estipuladas em lei. O(s) locatário(s) declara(m) ainda estar ciente de que não devolvendo o imóvel pintado externamente, a Seguradora indenizará o locador pelo ônus da pintura, e terá direito de reaver o valor que tiver sido pago. O Segurado poderá comunicar o Sinistro a PORTO SEGURO no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel.", "trava": true}, {"id": "p029", "t": "APÓLICE: [APOLICE_REFERENCIA]"}, {"id": "p030", "t": "[[OBJETO]]"}, {"id": "p031", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p032", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p033", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso de MORADIA dos LOCATÁRIO (S).", "dest": "residencial"}, {"id": "p034", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso COMERCIAL dos LOCATÁRIO (S).", "dest": "comercial", "adaptado": true}, {"id": "p035", "t": "[[PRAZO]]"}, {"id": "p036", "t": "Cláusula 1º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), conforme acordado entre as partes e o(a) LOCATÁRIO(A) se compromete a pagar pontualmente até o dia [DIA_VENCIMENTO] de cada mês subsequente."}, {"id": "p037", "t": "Cláusula 2º - O primeiro aluguel será pago 30 dias após a data de entrega das chaves e os aluguéis subsequentes, serão pagos na data de vencimento fixada neste documento."}, {"id": "p038", "t": "[[ADICIONAIS]]"}, {"id": "p039", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p040", "t": "O valor do aluguel pode ser acrescido de acessórios locatícios e encargos, se aplicável, conforme estipulado neste contrato. O cômputo desses encargos será a partir da posse da chave e serão cobrados juntamente com o aluguel na data estabelecida."}, {"id": "p041", "t": "Cláusula 3º - O aluguel mensal deve ser pago juntamente com os demais encargos, em moeda corrente nacional, em seu vencimento, ficando em caso contrário acrescidos de multa de 10% (dez por cento) do seu valor, mais juros de 1% (um por cento) ao mês, mais a correção monetária prevista em lei, a título de penalidade contratual, sem prejuízo da exigibilidade das demais correções estipuladas."}, {"id": "p042", "t": "Cláusula 4º - O pagamento dos alugueis e encargos locatícios devem ser realizados por meio de boleto bancário, que será emitido pela ADMINISTRADORA."}, {"id": "p043", "t": "Cláusula 5º - Caso o LOCATÁRIO não receba o boleto com a cobrança em ate 02 (dois) dias úteis antes do vencimento, será de responsabilidade do mesmo, entrar em contato com a ADMINISTRADORA para solicitar a emissão da 2º via de boleto."}, {"id": "p044", "t": "Cláusula 6º - Além das penalidades previstas na CLÁUSULA 3º, a falta de pagamento do aluguel na data estipulada poderá acarretar a rescisão do presente contrato, após 15 (quinze) dias da data do vencimento, ficando o LOCATÁRIO(S) responsável pela multa prevista na CLÁUSULA 28º - Parágrafo segundo do presente contrato, pelas despesas processuais e honorários advocatícios."}, {"id": "p045", "t": "Cláusula 7º - O LOCATÁRIO(S) não terá direito a reter o pagamento do aluguel ou de qualquer outra quantia devida nos termos do presente contrato, sob a alegação de não terem sido atendidas exigências porventura solicitadas."}, {"id": "p046", "t": "Cláusula 8º – O LOCATÁRIO(S) fica ciente nesta data que, antes da propositura da ação de despejo por falta de pagamento do aluguel e encargos na data estipulada neste contrato, poderá haver o protesto, junto ao cartório competente."}, {"id": "p047", "t": "Cláusula 9º - Eventual inadimplência do aluguel e encargos por parte dos LOCATÁRIO (S), ensejará Ação Judicial, independente do prazo da mora, não se responsabilizando o LOCADOR(A) pela inclusão dos nomes dos devedores ou de seus Fiadores junto às entidades mantenedoras de bancos de proteção ao crédito, SERASA, SCPC etc."}, {"id": "p048", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p049", "t": "O valor do aluguel ora contratado sofrerá reajuste anualmente, em conformidade com a legislação específica. Entretanto, havendo alteração legal para nova periodicidade, esta será aplicada automaticamente, independentemente de confirmação das partes."}, {"id": "p050", "t": "INDEXADORES:"}, {"id": "p051", "t": "As partes de comum acordo estabelecem o índice IGPM (Índice Geral de Preço de Mercado), para a correção do aluguel, que será aplicado de acordo com a periodicidade acima. Havendo a extinção do mesmo, por determinação legal, as partes elegerão seu substituto imediatamente após a eventual extinção."}, {"id": "p052", "t": "Cláusula 10º - O LOCATÁRIO autoriza a administradora a efetuar a cobrança dos valores relativos a IPTU e CONDOMÍNIO vincendo juntamente com o aluguel vencido, antes da data do vencimento junto a autarquia municipal e a empresa administradora do condomínio (referente ao mês subsequente de vencimento), mesmo que não vencido e escoado a data de pagamento, visando o repasse ao LOCADOR, para o pagamento direto de referidas despesas."}, {"id": "p053", "t": "Cláusula 11º - No caso dos carnês e/ou avisos dos tributos citados na cláusula acima serem entregues diretamente ao LOCATÁRIO (S), este deverá encaminhá-los ao endereço da ADMINISTRADORA, antes do vencimento dos títulos no prazo de até 5 (cinco) dias úteis, sob pena de responderem pelas multas do atraso."}, {"id": "p054", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p055", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p056", "t": "Cláusula 12º – O LOCATÁRIO obriga-se a providenciar, junto às concessionárias competentes, a transferência da titularidade das contas de ÁGUA, ENERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade das referidas contas, por parte do LOCATÁRIO, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p057", "t": "Cláusula 13º – O descumprimento da obrigação prevista na CLÁUSULA 12º, autoriza o LOCADOR a reter as chaves até a devida apresentação dos respectivos comprovantes, sem que isso gere qualquer direito de indenização ou alegação de atraso na imissão da posse por parte do LOCATÁRIO."}, {"id": "p058", "t": "Cláusula 14º - O LOCATÁRIO recebendo na data da assinatura deste contrato, o respectivo laudo de vistoria inicial, cujo documento aponta o estado de conservação do imóvel, declara concordar que o imóvel tem como finalidade, o uso de HABITAÇÃO, considerando inclusive suas instalações ELÉTRICAS, HIDRÁULICAS e SANITÁRIAS. Obriga-se o LOCATÁRIO a manter o imóvel assim como consta em LAUDO DE VISTORIA INICIAL, de forma a tudo restituir na mais perfeita ordem e no mesmo estado de conservação, higiene e funcionamento, quando findo ou rescindido o presente contrato, de modo que possa ser imediatamente ocupado pelo LOCADOR ou por quem este indicar, sem que isso dependa de qualquer conserto, reparação, etc. O LOCADOR será responsável pelos problemas estruturais, caso seja necessario.", "dest": "residencial"}, {"id": "p059", "t": "Cláusula 14º - O LOCATÁRIO recebendo na data da assinatura deste contrato, o respectivo laudo de vistoria inicial, cujo documento aponta o estado de conservação do imóvel, declara concordar que o imóvel tem como finalidade, o uso COMERCIAL, considerando inclusive suas instalações ELÉTRICAS, HIDRÁULICAS e SANITÁRIAS. Obriga-se o LOCATÁRIO a manter o imóvel assim como consta em LAUDO DE VISTORIA INICIAL, de forma a tudo restituir na mais perfeita ordem e no mesmo estado de conservação, higiene e funcionamento, quando findo ou rescindido o presente contrato, de modo que possa ser imediatamente ocupado pelo LOCADOR ou por quem este indicar, sem que isso dependa de qualquer conserto, reparação, etc. O LOCADOR será responsável pelos problemas estruturais, caso seja necessario.", "dest": "comercial", "adaptado": true}, {"id": "p060", "t": "Cláusula 15º - Em caso de discordância do laudo de vistoria inicial, o LOCATÁRIO terá o prazo de 10 (dez) dias corridos para realizar sua contestação, mediante formalização por email ou notificação por correios. O silêncio será considerado concordância ao laudo inicial apresentado."}, {"id": "p061", "t": "Cláusula 16º - Fica terminantemente proibida a colocação de pregos e parafusos nas paredes ou executar furos nos azulejos. Caso o LOCATÁRIO necessite fixar armários de cozinha ou outros, deverá solicitar autorização por escrito ao LOCADOR, ocasião em que, uma vez autorizado, receberá uma cópia da planta hidráulica e elétrica do imóvel."}, {"id": "p062", "t": "Cláusula 17º - A repintura no imóvel ora locado por parte do LOCATÁRIO, deverá ser compatível com a tinta anterior, ou seja, nas mesmas cores e qualidade que foi entregue."}, {"id": "p063", "t": "Cláusula 18º - Os pisos, azulejos, armários modulados, ou qualquer item de acabamento do imóvel ora locado por parte do LOCATÁRIO, deverá ser entregue nas mesmas condições recebidas, ou seja, caso danifique algum desses itens, o mesmo deverá ser substituído pelo mesmo modelo, tamanho, marca e nas mesmas cores e qualidade que foi entregue."}, {"id": "p064", "t": "Cláusula 19º - Caso algum piso seja danificado e o LOCATÁRIO não encontre o mesmo modelo disponível para compra, ou tenha saído de fabricação, deverá consultar o LOCADOR, através da ADMINISTRADORA, um outro modelo compatível aceito para substituição de todos os pisos e em todos os ambientes que o integram, arcando o LOCATÁRIO com todo o custo de material e instalação."}, {"id": "p065", "t": "Cláusula 20º - Fica o LOCATÁRIO, responsável pela verificação da voltagem da corrente elétrica existente no imóvel, em todos os seus pontos, assumindo para si, eventuais danos em aparelhos e/ou equipamentos que sejam ligados sem a devida checagem."}, {"id": "p066", "t": "Cláusula 21º - O LOCATÁRIO não poderá fazer modificações ou transformações no imóvel locado, nem introduzir quaisquer benfeitorias, sem que haja prévio aviso e consentimento por escrito do LOCADOR. Realizado benfeitorias, desde que tenham sido com o consentimento expresso da LOCADOR, essas ficarão incorporadas ao imóvel sem qualquer direito ao LOCATÁRIO, de retenção ou indenização, ao término da locação."}, {"id": "p067", "t": "Cláusula 22º - São de responsabilidade do LOCATÁRIO as obras de manutenção do imóvel, cabendo exclusivamente ao LOCADOR aquelas que importem na estrutura e segurança dele, nos termos da legislação vigente. I): Sendo necessária a realização de qualquer obra ou manutenção por parte do LOCADOR, o LOCATÁRIO deverá notifica-lo para que no prazo de até 05 (cinco) dias úteis do recebimento da notificação, dar início aos reparos necessários. Não sendo realizados, fica desde já autorizado o LOCATÁRIO a realizar três orçamentos e providenciar a realização dos reparos que importem a estrutura ou segurança do imóvel e cobrá-los do LOCADOR pelo menor preço orçado."}, {"id": "p068", "t": "Cláusula 23º - Fica ainda facultado ao LOCADOR quando lhe convier, exigir a remoção de benfeitorias introduzidas no imóvel sem sua autorização, correndo todas as despesas por conta do LOCATÁRIO."}, {"id": "p069", "t": "Cláusula 24º - Se na VISTORIA FINAL for constatado qualquer anormalidade no imóvel, o LOCATÁRIO será notificado no prazo de 05 (cinco) dias corridos, para reparar o defeito ou substituir as peças ou aparelhos defeituosos por sua conta e risco. Não atendida esta notificação, ficará facultado ao LOCADOR providenciar os serviços, cobrando do LOCATÁRIO, os valores gastos com material e mão de obra, além dos dias de aluguel necessários para tais reparos, sem prejuízo da cobrança por eventuais perdas e danos que a LOCADORA vier a incorrer."}, {"id": "p070", "t": "Parágrafo único: As partes concordam que a vistoria final do imóvel será realizada sem qualquer custo para o LOCATÁRIO. Contudo, caso seja necessária a realização de uma revistoria, será cobrada do LOCATÁRIO uma taxa de R$ 120,00 (cento e vinte) reais para cobrir custos envolvidos."}, {"id": "p071", "t": "Cláusula 25º - O LOCATÁRIO desde já, faculta o LOCADOR, ou seu representante devidamente constituído, examinar ou vistoriar o imóvel locado, quando entender conveniente, com aviso de 48 (quarenta e oito) horas de antecedência."}, {"id": "p072", "t": "Cláusula 26º - Ocorrerá a rescisão do presente contrato de pleno direito, no caso de desapropriação, incêndio ou acidente que sujeite o imóvel locado a obras que importem na sua reconstrução ainda que parcial, que impeçam o seu uso por mais de 45 (quarenta e cinco) dias, ou, ainda, no caso de se verificar ou ocorrer a insolvência, recuperação judicial ou falência do LOCATÁRIO, ou se forem verificados atos desabonadores, de ordem civil ou criminal de sua parte, sem prejuízo das demais cláusulas contratuais e da responsabilidade da multa contratual estipulada na CLÁUSULA 28º, que alcançará também os Fiadores (se houver)."}, {"id": "p073", "t": "Cláusula 27º - No caso de desapropriação do imóvel locado, ficará o LOCADOR desobrigado por todas as cláusulas deste contrato, ressalvando-se ao LOCATÁRIO tão somente o direito de haver do poder público desapropriante a indenização a que porventura tenha direito."}, {"id": "p074", "t": "Cláusula 28º - O LOCATÁRIO é obrigado a respeitar os direitos de vizinhança, a lei do silêncio, regras de condomínio, evitando a prática de quaisquer atos que venham a perturbar a tranquilidade e as condições de saúde pública."}, {"id": "p075", "t": "Parágrafo primeiro: Ocorrerá também a rescisão do presente contrato se o LOCATÁRIO infringir obrigação legal ou cometer infração a qualquer uma das cláusulas do presente instrumento."}, {"id": "p076", "t": "Parágrafo segundo: Fica estipulada a multa contratual não compensatória proporcional de 03 (três) vezes o valor do aluguel vigente da época da eventual infração, em benefício ao LOCADOR, sem prejuízo da exigibilidade das p e r da s e da n o s , a l é m d a s obrigações assumidas por este instrumento, podendo o LOCADOR, se assim lhe convier, considerar ao mesmo tempo rescindido o presente contrato de locação, independentemente de qualquer formalidade."}, {"id": "p077", "t": "Cláusula 29º - O LOCATÁRIO assume o formal compromisso de 30 (trinta) dias antes de desocupar o imóvel, notificar por escrito a ADMINISTRADORA que, efetuará uma vistoria no mesmo a fim de ficar constatado o estado de conservação do imóvel."}, {"id": "p078", "t": "Cláusula 30º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p079", "t": "Cláusula 31º - Decorrido o PRAZO DA LOCAÇÃO e estando a locação vigorando por prazo indeterminado, o LOCATÁRIO poderá rescindir o contrato de locação mediante notificação por escrito á ADMINISTRADORA, com antecedência de 30 (trinta) dias da devolução das chaves."}, {"id": "p080", "t": "Parágrafo único: Na ausência do aviso acima citado, o LOCADOR poderá exigir a quantia correspondente a 01 (um) mês de aluguel e encargos vigentes da data da rescisão, conforme autoriza o artigo 6º, da Lei no 8.245/91."}, {"id": "p081", "t": "Cláusula 32º - Tudo quanto for devido em razão deste contrato, notadamente os aluguéis mensais e seus acessórios, será cobrado por ação judicial apropriada no FORO TERRITORIAL DO IMÓVEL, com expressa renúncia de qualquer outro, por mais privilegiado que seja, o qual desde já fica eleito pelos contratantes como seu domicílio, para que exercitem e cumpram todos os direitos e obrigações decorrentes do presente instrumento."}, {"id": "p082", "t": "Parágrafo único: Em qualquer procedimento judicial que o LOCATÁRIO der causa, correrão por sua conta além do principal, todas as custas e despesas oriundas desta medida e ainda, honorários advocatícios, mesmo em caso de purgação de mora, quando houver a propositura da ação ou logo após a distribuição da petição."}, {"id": "p083", "t": "Cláusula 33º - Não é permitida a transferência deste contrato, no todo ou em parte, a sublocação ou empréstimo do imóvel locado, sem prévio consentimento, por escrito do LOCADOR."}, {"id": "p084", "t": "Parágrafo único: Em caso de falecimento, separação de fato ou judicial, divórcio ou dissolução da união estável do LOCATÁRIO, esta locação prosseguirá automaticamente com seu cônjuge ou companheiro, este que permanecer no imóvel, nos termos da Lei."}, {"id": "p085", "t": "Cláusula 34º - Caso o imóvel seja colocado à venda, o LOCATÁRIO terá preferência na compra. Não havendo interesse no prazo de 30 (trinta) dias, o LOCATÁRIO deverá permitir e facilitar as visitas dos pretendentes ao mesmo, em conformidade com o artigo 27, da Lei no 8.245/91."}, {"id": "p086", "t": "Cláusula 35º - Ocorrendo interesse do LOCATÁRIO na compra do imóvel, sua manifestação deverá ser encaminhada por escrito, à ADMINISTRADORA, com a devida intervenção do corretor de imóveis da mesma empresa, a quem caberá a intermediação para a concretização do negócio."}, {"id": "p087", "t": "Cláusula 36º - Alugado o imóvel, a administração exercida pela ADMINISTRADORA, será realizada até o efetivo recebimento de todos dos valores em aberto ou até o recebimento das chaves, o que ocorrer primeiro."}, {"id": "p088", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p089", "t": "Cláusula 37º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da parte perecível do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p090", "t": "Parágrafo primeiro: O LOCATÁRIO (S), poderá ele mesmo contratar e apresentar a apólice para a ADMINISTRADORA, porém, somente serão aceitas apólices que apresentarem seu pagamento integral."}, {"id": "p091", "t": "Parágrafo segundo: Quanto a atualização e renovação do seguro, o valor segurado a ser corrigido durante a vigência do presente contrato, deverá comprovar que a apólice em vigor cubra sempre o custo para reconstrução do imóvel, onde caberá ao LOCATARIO providenciar a renovação do seguro na época própria, dando ciência ao LOCADOR ou a ADMINISTRADORA."}, {"id": "p092", "t": "Cláusula 38º - A falta do pagamento do seguro por parte do LOCATÁRIO, constituirá infração passível de rescisão do presente instrumento, independente da incidência da multa infracional prevista em contrato."}, {"id": "p093", "t": "Cláusula 39º - Em se tratando de edifício, fica desde já convencionado que não serão aceitas apólices coletivas de condomínio em substituição ao seguro mencionado na CLÁUSULA 38º."}, {"id": "p094", "t": "Cláusula 40º - Caso o LOCATÁRIO não apresente sua apólice contratada de forma particular à ADMINISTRADORA, ficará o LOCADOR automaticamente autorizado a contratar uma empresa Seguradora de sua preferência e lançar seus valores à vista na primeira parcela de cobrança de aluguel. As renovações serão cobradas automaticamente no boleto de pagamento do aluguel."}, {"id": "p095", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p096", "t": "Cláusula 41º - As partes declaram expresso consentimento que a ADMINISTRADORA irá coletar, tratar e compartilhar os dados necessários ao cumprimento do contrato, nos termos do art. 7°, inciso V da Lei Geral de Proteção de Dados, bem como os dados necessários para o cumprimento de obrigações legais, nos termos do art. 7°, inciso II da LGPD e os dados, se necessários para proteção de crédito, conforme autorizado, também pelo art. 7° inciso V da LGPD."}, {"id": "p097", "t": "Cláusula 42º - Outros dados poderão ser coletados, tratados e compartilhados para fins administrativos da imobiliária, conforme termo de consentimento específico."}, {"id": "p098", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p099", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p100", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IGPM (Índice Geral de Preço de Mercado); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p101", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O LOCADOR declara ser o legítimo proprietário e/ou possuidor do Imóvel, o qual se encontra livre e desonerado de quaisquer direitos, obrigações e ônus, judiciais e/ou extrajudiciais, que possam comprometer este CONTRATO, assumindo o dever de indenizar e manter o LOCATÁRIO e a ADMINISTRADORA indenes de quaisquer responsabilidades decorrentes de medidas que comprometam a sua posse e propriedade sobre o Imóvel. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Qualquer alteração nos endereços eletrônicos de e-mail constantes no cadastro prévio realizado deverá ser prontamente comunicada à ADMINISTRADORA por instrumento que comprove a total ciência da imobiliária quanto a aludida mudança. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p102", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p103", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p104", "t": "[[ASSINATURAS]]"}]$mod$::jsonb, 'Texto-base enviado por Denis (16/11/2026)')
ON CONFLICT DO NOTHING;
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, 'seguro_pottencial', 1, $mod$Seguro-fiança Pottencial$mod$, 'residencial', 'seguro_fianca', 'pottencial', $mod$SEGURO FIANÇA POTTENCIAL$mod$, $mod$[{"id": "p001", "t": "QUADRO RESUMO: Locador(es); Locatário(a); Administradora; Imóvel; Destinação da Locação; Prazo da Locação; Valor e Vencimento do Aluguel; Primeiro Aluguel; Reajuste e Indexador; Encargos Locatícios; Contas de Consumo; Transferência de Titularidade; Garantia Locatícia; Inadimplência; Vistoria Inicial; Contestação da Vistoria; Conservação e Manutenção do Imóvel; Benfeitorias e Modificações; Vistoria Final e Revistoria; Rescisão e Multa Contratual; Desocupação e Aviso Prévio; Seguro Incêndio; Sublocação/Cessão; Preferência na Compra do Imóvel; Administração do Imóvel; LGPD; Disposições Gerais; Foro."}, {"id": "p002", "t": "PRÊAMBULO"}, {"id": "p003", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p004", "t": "[[LOCADOR]]"}, {"id": "p005", "t": "[[LOCATARIO]]"}, {"id": "p006", "t": "ADMINISTRADORA: [ADMINISTRADORA_QUALIFICACAO]; cuja a administração do referido imóvel perdurará durante o prazo de vigência do presente Contrato de Locação, estendendo-se até a data da efetiva entrega das chaves, estando cientes as partes celebrantes deste instrumento de que toda e qualquer questão decorrente deste deverá ser tratada prévia e diretamente junto à ADMINISTRADORA, sendo que o não cumprimento desta cláusula, poderá dar ensejo às medidas cabíveis de rescisão contratual por culpa da parte infratora, ou outras medidas cabíveis, além de isenção de responsabilidade da ADMINISTRADORA."}, {"id": "p007", "t": "GARANTIA LOCATÍCIA: SEGURO POTTENCIAL ALUGUEL: As Partes anuem com a emissão de seguro fiança locatícia para garantia do presente contrato, nos termos do art. 37, III da Lei nº 8.245/1991 (Lei de Locações), a ser contratado pelo(a) LOCATÁRIO(A), junto à Pottencial Seguradora S.A., tendo como Segurado o LOCADOR e declaram ter negociado e anuído com a indicação do corretor de seguros, as coberturas e limites de indenização contratados, cujos termos e condições do contrato de seguro estão disponíveis para consulta através do link https://pottencial.com.br/certidoes-legais/condicoesgerais/.", "trava": true}, {"id": "p008", "t": "O seguro estará vigente pelo período previsto na apólice emitida. Ocorrendo prorrogação de prazo do presente contrato de locação com alteração das condições anteriormente estabelecidas entre as partes, mediante formalização de aditivo ou em razão de prorrogação por prazo indeterminado por força de lei ou ato normativo, a Seguradora deverá ser comunicada para reanálise de aceitação do risco.", "trava": true}, {"id": "p009", "t": "Para efeito desta garantia, os prêmios iniciais e de renovações do seguro fiança serão pagos pelo LOCATÁRIO(A), de acordo com o inciso XI, do artigo 23 da lei do inquilinato. Exclusivamente em caso de o pagamento do prêmio ser efetivada através de fatura, o LOCATÁRIO desde já anui com a realização do pagamento do prêmio à IMOBILIÁRIA para posterior repasse da quantia à Seguradora. A apólice garantirá exclusivamente as coberturas especificadas na proposta de seguro.", "trava": true}, {"id": "p010", "t": "Inadimplência - Em caso de inadimplência do LOCATÁRIO(A), a SEGURADORA concederá prazo ao LOCADOR(A) para pagamento do prêmio, nos termos previstos nas Condições Gerais do seguro, sob pena de cancelamento do seguro e rescisão desta locação por infração contratual, com o consequente despejo.", "trava": true}, {"id": "p011", "t": "Notificações – O(A) LOCADOR(A) e LOCATÁRIO(A) declara(m) que todos os dados informados para contratação do seguro estão corretos, estando cientes de que serão considerados pela SEGURADORA para envio de quaisquer notificações e/ou comunicações previstas na legislação vigente e Condições Gerais do seguro, sendo presumidos válidos para todos os fins de direito. O (A) LOCADOR(A) e o(a) LOCATÁRIO(A) poderão outorgar poderes à terceiros para recebimento de tais notificações e/ou comunicações, inclusive o(a) corretor/corretora de seguros ou a imobiliária, hipótese em que serão indicados os dados destes terceiros para contratação do seguro. Sendo necessário ajuste de qualquer dado, o(a) LOCADOR(A) ou o(a) LOCATÁRIO(A) deverão, a qualquer momento, entrar em contato com a SEGURADORA através da Central de Atendimento 0800 606 7688 ou pelo e-mail atendimento.corretora@pottencial.com.br para alteração ou correção.", "trava": true}, {"id": "p012", "t": "Pagamento de indenizações e Sub-rogação. Em caso de pagamento de qualquer indenização securitária, a SEGURADORA sub-rogar-se-á automaticamente no direito do LOCADOR(A) de cobrar os débitos em aberto em face do(a) LOCATÁRIO(A).", "trava": true}, {"id": "p013", "t": "Restrição Financeira. Eventuais débitos decorrentes do presente contrato ou do contrato de seguro não pagos pelo LOCATÁRIO(A) serão comunicados às entidades mantenedoras de bancos de dados de proteção ao crédito (Serasa, SPC, etc.), quer pelo LOCADOR(A), quer pela SEGURADORA, inclusive de todas as despesas havidas com as medidas judiciais cabíveis.", "trava": true}, {"id": "p014", "t": "Locatário Solidário – Havendo mais de um LOCATÁRIO(A) para exercer os direitos e dar cumprimento às obrigações desse contrato, ao firmarem esta locação, os LOCATÁRIOS(AS) declaram-se solidários entre si e constituem-se reciprocamente PROCURADORES, conferindose mutuamente poderes especiais para receber citações, notificações e intimações, confessar, desistir, e assinar tudo quanto se tornar necessário, transigir em juízo ou fora dele, fazer acordos, firmar compromissos judiciais ou extrajudiciais, receber e dar quitação, no âmbito deste contrato.", "trava": true}, {"id": "p015", "t": "Cobertura adicional de Multa Rescisória (contratação opcional) – Em caso de contratação desta cobertura adicional, o(a) LOCATÁRIO(A) reconhece que a entrega antecipada do imóvel antes da vigência final do contrato de locação configura quebra contratual, estando, portanto, obrigado ao pagamento de multa por rescisão que, caso não adimplida, poderá ensejar o pagamento da indenização securitária pela SEGURADORA. O(A) LOCATÁRIO(A) declara, ainda, estar ciente de que, não realizando o pagamento da multa prevista ao(a) LOCADOR(A), a SEGURADORA efetuará a indenização, com consequente pedido de ressarcimento em face do(a) LOCATÁRIO(A). O Segurado deverá comunicar o Sinistro à Pottencial no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel.", "trava": true}, {"id": "p016", "t": "Cobertura adicional de Danos ao Imóvel (contratação opcional) – Em caso de contratação desta cobertura adicional, o(a) LOCATÁRIO(A) declara para todos os fins e efeitos de direito, que recebe o imóvel locado no estado em que se encontra de conservação e uso, identificado no Laudo (Relatório) de Vistoria Inicial assinado por todos os contratantes, o qual é parte integrante deste contrato, obrigando-se e comprometendo-se o(a) LOCATÁRIO(A) a devolvê-lo nesse estado, independentemente de qualquer aviso ou notificação prévia e qualquer que seja o motivo de devolução, sob pena de incorrer nas cominações previstas neste contrato ou estipuladas em lei, além da obrigação de indenizar por danos ou prejuízos decorrentes da inobservância dessa obrigação, salvo as deteriorações decorrentes do uso normal do imóvel. O(A) LOCATÁRIO(A) declara, ainda, estar ciente de que, não realizando o pagamento dos prejuízos ao(a) LOCADOR(A), a SEGURADORA efetuará a indenização nos termos dos limites e condições contratuais do seguro, com consequente pedido de ressarcimento em face do(a) LOCATÁRIO(A). LOCADOR(A) e LOCATÁRIO(A) declaram que o Laudo (Relatório) de Vistoria Inicial com descrição do estado do imóvel foi elaborado antes da posse do imóvel, estando de acordo com todo o conteúdo do laudo. É imprescindível e obrigatória a apresentação do Relatório do Estado do Uso de Conservação do imóvel, assinado pelo Locador(a) e Locatário(a) como condição para pagamento de indenização pela SEGURADORA. O Segurado deverá comunicar o Sinistro à Pottencial o no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel.", "trava": true}, {"id": "p017", "t": "Cobertura adicional de Pintura Interna Nova (contratação opcional) – Caso contratada esta cobertura, declara o(a) LOCATÁRIO (A), para todos os fins e efeitos de direito, que recebe o imóvel locado com Pintura Interna NOVA e, assim, obriga-se, ao final da locação, a pintá-lo e devolvê-lo no mesmo estado em que recebeu, sob pena de arcar com os valores devidos ao(a) LOCADOR(A) para realização de nova pintura. O(A) LOCATÁRIO(A) declara ainda estar ciente de que, não devolvendo o imóvel pintado internamente, e estando a respectiva cobertura contratada na proposta de seguro, a SEGURADORA indenizará o(a) LOCADOR(A) pelos prejuízos havidos com a nova pintura, e terá direito de reaver o valor que tiver sido pago, nos termos dos limites e condições contratuais do seguro, em face do(a) LOCATÁRIO(A). O Segurado deverá comunicar o Sinistro à Pottencial no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel.", "trava": true}, {"id": "p018", "t": "Cobertura adicional de Pintura Externa Nova (cobertura opcional) – A cobertura é exclusiva para imóveis residenciais e não residenciais (casas para fins comerciais), na qual o locatário ocupa a área global do imóvel alugado. Declara o(a) LOCATÁRIO(A), para todos os fins e efeitos de direito, que recebe o imóvel locado com Pintura Externa NOVA, e assim obriga-se, ao final da locação, a pintá-lo e devolvê-lo no mesmo estado que recebeu, sob pena de arcar com os valores devidos ao(a) LOCADOR(A) para realização de nova pintura O(A) LOCATÁRIO(A) declara ainda estar ciente de que, não devolvendo o imóvel pintado internamente, e estando a respectiva cobertura contratada na proposta de seguro, a SEGURADORA indenizará o(a) LOCADOR(A) pelos prejuízos havidos com a nova pintura, e terá direito de reaver o valor que tiver sido pago, nos termos dos limites e condições contratuais do seguro, em face do(a) LOCATÁRIO(A). O(A) Segurado(a) deverá comunicar o Sinistro a Pottencial no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel.", "trava": true}, {"id": "p019", "t": "APÓLICE: [APOLICE_REFERENCIA]"}, {"id": "p020", "t": "[[OBJETO]]"}, {"id": "p021", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p022", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p023", "t": "O imóvel identificado neste instrumento destina-se exclusivamente à MORADIA do LOCATÁRIO e dos moradores expressamente identificados neste contrato, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "residencial"}, {"id": "p024", "t": "O imóvel identificado neste instrumento destina-se exclusivamente ao uso COMERCIAL do LOCATÁRIO, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "comercial", "adaptado": true}, {"id": "p025", "t": "[[PRAZO]]"}, {"id": "p026", "t": "Cláusula 1º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), devendo ser pago pelo LOCATÁRIO até o dia [DIA_VENCIMENTO] de cada mês, conforme as condições estabelecidas neste instrumento."}, {"id": "p027", "t": "Cláusula 2º - O primeiro aluguel vencerá 30 (trinta) dias após a efetiva entrega das chaves ao LOCATÁRIO. Os aluguéis subsequentes vencerão todo dia [DIA_VENCIMENTO] de cada mês, observando-se, quando necessário, o cálculo proporcional dos períodos de ocupação, a fim de evitar cobrança em duplicidade."}, {"id": "p028", "t": "[[ADICIONAIS]]"}, {"id": "p029", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p030", "t": "Além do aluguel mensal, serão de responsabilidade do LOCATÁRIO os encargos locatícios expressamente atribuídos a ele neste contrato, os quais serão devidos a partir da efetiva entrega das chaves, observadas as disposições legais e contratuais aplicáveis."}, {"id": "p031", "t": "Cláusula 3º - O atraso no pagamento do aluguel ou de quaisquer encargos locatícios acarretará a incidência de multa moratória de 10% (dez por cento) sobre o valor devido, acrescida de juros de mora de 1% (um por cento) ao mês, calculados proporcionalmente aos dias de atraso, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p032", "t": "Cláusula 4º - O pagamento dos alugueis e encargos locatícios devem ser realizados por meio de boleto bancário, que será emitido pela ADMINISTRADORA."}, {"id": "p033", "t": "Cláusula 5º - Caso o LOCATÁRIO não receba o boleto bancário até 02 (dois) dias úteis antes do vencimento, deverá entrar em contato com a ADMINISTRADORA para solicitar a segunda via, permanecendo responsável pelo pagamento na data estabelecida, salvo eventual falha imputável à ADMINISTRADORA que tenha efetivamente impedido o pagamento."}, {"id": "p034", "t": "Cláusula 6º - O inadimplemento do aluguel ou de quaisquer encargos locatícios na data do vencimento constituirá o LOCATÁRIO em mora, independentemente de notificação, facultando ao LOCADOR adotar as medidas judiciais e extrajudiciais cabíveis, inclusive ação de despejo e cobrança, nos termos da Lei nº 8.245/91, sem prejuízo dos encargos moratórios previstos neste contrato."}, {"id": "p035", "t": "Cláusula 7º - O LOCATÁRIO não poderá suspender ou deixar de efetuar o pagamento dos aluguéis e encargos locatícios por iniciativa própria, devendo eventuais divergências ou solicitações relacionadas ao imóvel ser formalizadas perante a ADMINISTRADORA, sem prejuízo dos direitos assegurados pela legislação vigente."}, {"id": "p036", "t": "Cláusula 8º – O LOCATÁRIO declara estar ciente de que o inadimplemento das obrigações financeiras decorrentes deste contrato poderá ensejar o protesto dos respectivos débitos, observadas as exigências legais aplicáveis."}, {"id": "p037", "t": "Cláusula 9º - O inadimplemento das obrigações locatícias poderá ensejar a adoção das medidas judiciais cabíveis, bem como a comunicação dos débitos aos órgãos de proteção ao crédito, desde que observados os requisitos legais, inclusive quanto à legitimidade, exatidão e atualização das informações fornecidas."}, {"id": "p038", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p039", "t": "O valor do aluguel será reajustado anualmente, respeitado o intervalo mínimo permitido pela legislação vigente, mediante aplicação do índice IPCA (Índice Nacional de Preços ao Consumidor Amplo), ou de outro índice oficial que venha a substituí-lo em caso de sua extinção, observadas as disposições legais aplicáveis."}, {"id": "p040", "t": "Cláusula 10º - O LOCATÁRIO será responsável pelo pagamento do IPTU e das despesas ordinárias de condomínio incidentes sobre o imóvel durante o período de sua posse, podendo tais valores ser incluídos no boleto mensal de aluguel para fins de cobrança e repasse. Permanecem sob responsabilidade exclusiva do LOCADOR as despesas extraordinárias de condomínio, conforme disposto no artigo 22, inciso X e parágrafo único, da Lei nº 8.245/91."}, {"id": "p041", "t": "Cláusula 11º - Caso o LOCATÁRIO receba diretamente carnês, avisos ou documentos referentes aos tributos e encargos de sua responsabilidade, deverá encaminhá-los à ADMINISTRADORA com antecedência suficiente para viabilizar o pagamento dentro do respectivo vencimento, respondendo por eventuais encargos decorrentes de sua omissão ou atraso injustificado."}, {"id": "p042", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p043", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p044", "t": "Cláusula 12º – O locatário obriga-se a providenciar, junto às concessionárias competentes, a transferência da titularidade das de ÁGUA, ELERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p045", "t": "DO DESCUMPRIMENTO E DAS PROVIDÊNCIAS ADMINISTRATIVAS:"}, {"id": "p046", "t": "Cláusula 13º - Caso o LOCATÁRIO não consiga realizar a transferência de titularidade das contas de ÁGUA, ENERGIA ELÉTRICA e GÁS antes da retirada das chaves, deverá apresentar à ADMINISTRADORA a devida comprovação das tentativas realizadas e da impossibilidade de efetivação, ficando a retirada das chaves condicionada à autorização expressa do LOCADOR. Uma vez autorizada a retirada das chaves pelo LOCADOR, o LOCATÁRIO deverá apresentar à ADMINISTRADORA, no prazo máximo de 15 (quinze) dias corridos, contados da data da retirada das chaves, os respectivos comprovantes de efetivação da transferência de titularidade das referidas contas."}, {"id": "p047", "t": "O não atendimento da obrigação no prazo estabelecido, sem a devida comprovação de impedimento não imputável ao LOCATÁRIO, caracterizará descumprimento contratual e ensejará a aplicação de multa administrativa no valor de R$ 250,00 (duzentos e cinquenta reais), a ser lançada no boleto de aluguel imediatamente subsequente à constatação do descumprimento."}, {"id": "p048", "t": "Na ausência de comprovação da regularização após o prazo previsto, a ADMINISTRADORA poderá, quando tecnicamente possível e mediante os documetnos e autorizações necessárias, adotrar as providências cabíveis perante as respectivas concessionárias para a regularização da titularidade, ficando o LOCATÁRIO responsável pelos eventuais custos, taxas ou encargos decorrentes de tais providências, quando comprovadamente de sua responsabilidade, sem prejuízo da multa prevista nesta cláusula."}, {"id": "p049", "t": "Cláusula 14º - O LOCATÁRIO declara receber, na data da efetiva entrega das chaves, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso para HABITAÇÃO.", "dest": "residencial"}, {"id": "p050", "t": "Cláusula 14º - O LOCATÁRIO declara receber, na data da efetiva entrega das chaves, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso COMERCIAL.", "dest": "comercial", "adaptado": true}, {"id": "p051", "t": "Cláusula 15º - Caso o LOCATÁRIO identifique divergências em relação ao laudo de vistoria inicial, deverá apresentar sua contestação por escrito à ADMINISTRADORA, no prazo de 10 (dez) dias corridos contados da entrega das chaves, preferencialmente acompanhada de fotografias ou outros registros que comprovem as condições apontadas. A ausência de manifestação dentro do prazo será considerada concordância quanto às condições aparentes descritas no laudo, ressalvados os vícios ocultos e defeitos não identificáveis em vistoria ordinária."}, {"id": "p052", "t": "Cláusula 16º - Fica permitido ao LOCATÁRIO realizar pequenos furos nas paredes do imóvel para a fixação de quadros, espelhos, suportes e objetos similares, desde que não comprometam a estrutura, as instalações hidráulicas ou elétricas. Fica expressamente vedada a realização de furos em azulejos, revestimentos cerâmicos e áreas impermeabilizadas, salvo mediante autorização prévia e por escrito do LOCADOR. Ao término da locação, o LOCATÁRIO deverá providenciar a adequada reparação dos furos realizados nas paredes, recompondo a pintura e o acabamento quando necessário, restituindo o imóvel nas condições em que o recebeu, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p053", "t": "Cláusula 17º - O LOCATÁRIO deverá devolver o imóvel com a pintura nas mesmas condições em que o recebeu, conforme descrito no laudo de vistoria inicial, responsabilizando-se pela reparação de manchas, riscos, alterações de cores, descascamentos ou danos decorrentes de uso inadequado ou de sua responsabilidade, ressalvado o desgaste natural decorrente do uso regular do imóvel."}, {"id": "p054", "t": "Cláusula 18º - O LOCATÁRIO deverá zelar pela conservação dos pisos, azulejos, armários, acessórios e demais itens que integram o imóvel, responsabilizando-se pelos danos que causar por ação, omissão ou uso inadequado, devendo providenciar o reparo ou a substituição dos itens danificados por outros de padrão, qualidade e características equivalentes aos originalmente existentes, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p055", "t": "Cláusula 19º - Caso algum piso seja danificado e o LOCATÁRIO não encontre o mesmo modelo disponível para compra, ou tenha saído de fabricação, deverá consultar o LOCADOR, através da ADMINISTRADORA, um outro modelo compatível aceito para substituição de todos os pisos do cômodo, arcando o LOCATÁRIO com todo o custo de material e instalação."}, {"id": "p056", "t": "Cláusula 20º - O LOCATÁRIO deverá verificar a tensão elétrica disponível nos pontos de energia do imóvel antes de conectar seus equipamentos e aparelhos eletrônicos, responsabilizando-se pelos danos decorrentes da utilização inadequada ou incompatível com a tensão disponível, desde que as instalações tenham sido entregues em condições regulares de funcionamento e que as informações disponíveis tenham sido corretamente fornecidas."}, {"id": "p057", "t": "Cláusula 21º - O LOCATÁRIO não poderá realizar modificações, alterações ou benfeitorias no imóvel sem prévia autorização, por escrito, do LOCADOR. Salvo ajuste expresso em contrário, as benfeitorias realizadas, ainda que autorizadas, incorporar-se-ão ao imóvel, sem direito de indenização ou retenção pelo LOCATÁRIO, nos termos do artigo 35 da Lei nº 8.245/91 e da Súmula 335 do STJ, ressalvadas as obrigações legais do LOCADOR relativas à conservação, segurança e habitabilidade do imóvel."}, {"id": "p058", "t": "Cláusula 22º - Compete ao LOCATÁRIO realizar os reparos e serviços de manutenção decorrentes do uso regular do imóvel, bem como reparar os danos causados por si, seus moradores, visitantes ou terceiros sob sua responsabilidade. Compete ao LOCADOR realizar os reparos relativos a vícios anteriores à locação, problemas estruturais e defeitos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, desde que não decorrentes de ação ou omissão do LOCATÁRIO."}, {"id": "p059", "t": "PARÁGRAFO ÚNICO: Identificada a necessidade de reparo de responsabilidade do LOCADOR, o LOCATÁRIO deverá comunicar formalmente a ADMINISTRADORA, para que sejam adotadas as providências necessárias. Em situações urgentes, que envolvam risco à segurança ou agravamento de danos ao imóvel, deverá comunicar imediatamente a ADMINISTRADORA, permitindo a adoção das medidas emergenciais cabíveis, observadas as disposições legais quanto à responsabilidade pelos custos."}, {"id": "p060", "t": "Cláusula 23º - O LOCADOR poderá exigir que o LOCATÁRIO remova modificações ou benfeitorias realizadas sem autorização prévia e por escrito, quando necessário à recomposição do imóvel às condições originais, correndo as despesas correspondentes por conta do LOCATÁRIO, desde que decorrentes de sua responsabilidade."}, {"id": "p061", "t": "Cláusula 24º - Ao término da locação, será realizada vistoria final para verificar as condições de conservação do imóvel, mediante comparação com o laudo de vistoria inicial, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p062", "t": "Parágrafo 1º: Caso sejam constatados danos ou irregularidades de responsabilidade do LOCATÁRIO, este será comunicado para que possa providenciar os respectivos reparos no prazo de 05 (cinco) dias corridos, ou outro prazo acordado entre as partes, sem prejuízo da cobrança de eventuais valores necessários à recomposição do imóvel."}, {"id": "p063", "t": "Parágrafo 2º: Caso o LOCATÁRIO não realize os reparos de sua responsabilidade, o LOCADOR poderá providenciá-los e exigir o ressarcimento dos respectivos custos, mediante apresentação dos comprovantes pertinentes, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p064", "t": "Parágrafo 3º: A vistoria final será realizada sem custo para o LOCATÁRIO. Caso seja necessária nova vistoria para verificação dos reparos executados, poderá ser cobrada taxa de revistoria no valor de R$ 150,00 (cento e cinquenta reais), desde que previamente informada e relacionada à necessidade de nova verificação de pendências de responsabilidade do LOCATÁRIO."}, {"id": "p065", "t": "Parágrafo 4º: A existência de danos ou pendências apontadas na vistoria não impedirá o recebimento das chaves nem a formalização da devolução do imóvel, permanecendo assegurado ao LOCADOR o direito de exigir o ressarcimento dos prejuízos comprovadamente atribuíveis ao LOCATÁRIO."}, {"id": "p066", "t": "Cláusula 25º - O LOCATÁRIO permitirá que o LOCADOR ou seu representante devidamente autorizado examine ou vistori? o imóvel, mediante prévio agendamento e comunicação com antecedência mínima de 48 (quarenta e oito) horas, em dia e horário previamente acordados entre as partes, respeitado o direito à privacidade e ao uso pacífico do imóvel."}, {"id": "p067", "t": "Cláusula 26º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade residencial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "residencial"}, {"id": "p068", "t": "Cláusula 26º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade comercial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "comercial", "adaptado": true}, {"id": "p069", "t": "Cláusula 27º - Em caso de desapropriação do imóvel, a locação será extinta, ficando o LOCADOR desobrigado das obrigações futuras decorrentes deste contrato, ressalvados os direitos do LOCATÁRIO de pleitear eventual indenização diretamente perante o poder público desapropriante, quando legalmente cabível."}, {"id": "p070", "t": "Cláusula 28º - O LOCATÁRIO obriga-se a respeitar as normas de convivência, os direitos de vizinhança, as regras condominiais e a legislação vigente, abstendo-se de praticar atos que comprometam a segurança, a tranquilidade, a higiene ou o sossego dos demais moradores."}, {"id": "p071", "t": "Parágrafo primeiro: O descumprimento das obrigações legais ou contratuais poderá ensejar a aplicação das medidas cabíveis, inclusive rescisão da locação, conforme a natureza e a gravidade da infração, observadas as disposições da Lei nº 8.245/91."}, {"id": "p072", "t": "Parágrafo segundo: Fica estipulada multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente à época da infração, aplicável em caso de descumprimento contratual que justifique sua incidência, observados os critérios de proporcionalidade, a natureza da obrigação descumprida e a legislação vigente."}, {"id": "p073", "t": "Parágrafo terceiro: Na hipótese de devolução antecipada do imóvel por iniciativa do LOCATÁRIO durante o prazo determinado deste contrato, será devida multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente, calculada proporcionalmente ao período restante do contrato, conforme o artigo 4º da Lei nº 8.245/91."}, {"id": "p074", "t": "Cláusula 29º - Fica o LOCATÁRIO isento do pagamento de multa contratual por desocupação voluntária do imóvel após o 12º (décimo segundo) mês de locação, tendo, porém, a obrigação de avisar por escrito com, no mínimo, 30 (trinta) dias de antecedência, ficando responsável pelo pagamento do aluguel e dos acessórios locatícios durante o período de aviso.", "cond": "isencao_multa"}, {"id": "p075", "t": "Parágrafo primeiro: A isenção da multa rescisória apenas caberá em benefício do LOCATÁRIO, caso esteja quite com todas as demais obrigações previstas neste instrumento. Caso contrário fica estipulada a multa contratual compensatória proporcionalmente ao período de cumprimento do contrato, em conformidade com a nova redação do artigo 4º, atribuída pela Lei no 12.112/2009, na qual incorrerá o LOCATÁRIO na hipótese de devolução do imóvel antes do prazo pactuado.", "cond": "isencao_multa"}, {"id": "p076", "t": "Cláusula 30º - O LOCATÁRIO assume o formal compromisso de 30 (trinta) dias antes de desocupar o imóvel, notificar por escrito a ADMINISTRADORA que, efetuará uma vistoria no mesmo a fim de ficar constatado o estado de conservação do imóvel."}, {"id": "p077", "t": "Cláusula 31º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p078", "t": "Cláusula 32º - Após o término do prazo contratual, caso a locação prossiga por prazo indeterminado, o LOCATÁRIO poderá rescindir o contrato mediante comunicação por escrito ao LOCADOR ou à ADMINISTRADORA, com antecedência mínima de 30 (trinta) dias."}, {"id": "p079", "t": "Parágrafo único: Na ausência do aviso prévio previsto nesta cláusula, o LOCADOR poderá exigir quantia correspondente a 01 (um) mês de aluguel e encargos vigentes na data da rescisão, conforme disposto no artigo 6º, parágrafo único, da Lei nº 8.245/91."}, {"id": "p080", "t": "Cláusula 33º - Fica eleito o foro da comarca onde se localiza o imóvel objeto desta locação para dirimir quaisquer controvérsias decorrentes deste contrato, ressalvadas as hipóteses legais de competência absoluta."}, {"id": "p081", "t": "Parágrafo único: Em caso de demanda judicial decorrente do descumprimento das obrigações contratuais, as partes responderão pelas custas e despesas processuais, conforme a legislação vigente e eventual determinação judicial."}, {"id": "p082", "t": "Cláusula 34º - É vedado ao LOCATÁRIO ceder, transferir ou sublocar, total ou parcialmente, o imóvel objeto deste contrato, bem como emprestá-lo a terceiros, sem prévia autorização expressa e por escrito do LOCADOR, nos termos do artigo 13 da Lei nº 8.245/91."}, {"id": "p083", "t": "Parágrafo único: Em caso de separação de fato, separação judicial, divórcio ou dissolução da união estável do LOCATÁRIO, a locação prosseguirá automaticamente com aquele que permanecer no imóvel, observadas as disposições do artigo 12 da Lei nº 8.245/91, inclusive quanto à comunicação ao LOCADOR e ao FIADOR."}, {"id": "p084", "t": "Cláusula 35º - Caso o LOCADOR pretenda vender o imóvel durante a vigência da locação, deverá assegurar ao LOCATÁRIO o direito de preferência para aquisição, em igualdade de condições com terceiros, mediante comunicação formal contendo todas as condições do negócio, inclusive preço, forma de pagamento e demais informações pertinentes, nos termos dos artigos 27 e seguintes da Lei nº 8.245/91."}, {"id": "p085", "t": "Parágrafo único: O LOCATÁRIO terá o prazo legal de 30 (trinta) dias, contado do recebimento da comunicação, para manifestar sua aceitação integral e inequívoca da proposta. Caso não exerça o direito de preferência, deverá permitir visitas de interessados, mediante prévio agendamento e em horários previamente acordados."}, {"id": "p086", "t": "Cláusula 36º - Ocorrendo interesse do LOCATÁRIO na compra do imóvel, sua manifestação deverá ser encaminhada por escrito, à ADMINISTRADORA, com a devida intervenção do corretor de imóveis da mesma empresa, a quem caberá a intermediação para a concretização do negócio."}, {"id": "p087", "t": "Cláusula 37º - A ADMINISTRADORA permanecerá responsável pela administração da locação durante a vigência deste contrato, observados os poderes que lhe foram conferidos pelo LOCADOR, inclusive quanto aos procedimentos de encerramento, entrega das chaves, apuração de encargos e prestação de contas, conforme o respectivo contrato de administração."}, {"id": "p088", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p089", "t": "Cláusula 38º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da estrutura e partes integrantes do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p090", "t": "Parágrafo primeiro: O LOCATÁRIO (S), poderá ele mesmo contratar e apresentar a apólice para a ADMINISTRADORA, porém, somente serão aceitas apólices que apresentarem seu pagamento integral."}, {"id": "p091", "t": "Parágrafo segundo: Quanto a atualização e renovação do seguro, o valor segurado a ser corrigido durante a vigência do presente contrato, deverá comprovar que a apólice em vigor cubra sempre o custo para reconstrução do imóvel, onde caberá ao LOCATARIO providenciar a renovação do seguro na época própria, dando ciência ao LOCADOR ou a ADMINISTRADORA."}, {"id": "p092", "t": "Cláusula 39º - O descumprimento da obrigação de contratação ou renovação do seguro contra incêndio, após notificação para regularização, poderá caracterizar infração contratual, sujeitando o LOCATÁRIO às medidas legais e contratuais cabíveis."}, {"id": "p093", "t": "Cláusula 40º - Em se tratando de edifício, fica desde já convencionado que não serão aceitas apólices coletivas de condomínio em substituição ao seguro incêndio individual."}, {"id": "p094", "t": "Cláusula 41º - Caso o LOCATÁRIO não apresente a apólice de seguro contratada por sua iniciativa dentro do prazo estabelecido, o LOCADOR poderá providenciar a contratação do seguro, mediante prévia comunicação ao LOCATÁRIO, sendo os respectivos custos de responsabilidade deste, desde que comprovados documentalmente. Os valores poderão ser incluídos no boleto de aluguel, observadas as condições e os prazos de pagamento informados pela ADMINISTRADORA."}, {"id": "p095", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p096", "t": "Cláusula 42º - As partes declaram estar cientes de que a ADMINISTRADORA poderá coletar, armazenar, utilizar e compartilhar os dados pessoais estritamente necessários à execução deste contrato, ao cumprimento de obrigações legais e regulatórias, bem como à proteção do crédito, observadas as bases legais previstas no artigo 7º, incisos II, V e X, da Lei nº 13.709/2018 (Lei Geral de Proteção de Dados Pessoais – LGPD)."}, {"id": "p097", "t": "Cláusula 43º - O tratamento de dados pessoais para finalidades adicionais, não abrangidas pelas hipóteses legais previstas na cláusula anterior, dependerá da existência de base legal adequada, inclusive consentimento específico do titular, quando necessário, assegurados os direitos previstos na Lei nº 13.709/2018."}, {"id": "p098", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p099", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p100", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IPCA (Índice Nacional de Preços ao Consumidor Amplo); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p101", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O LOCADOR declara ser o legítimo proprietário e/ou possuidor do Imóvel, o qual se encontra livre e desonerado de quaisquer direitos, obrigações e ônus, judiciais e/ou extrajudiciais, que possam comprometer este CONTRATO, assumindo o dever de indenizar e manter o LOCATÁRIO e a ADMINISTRADORA indenes de quaisquer responsabilidades decorrentes de medidas que comprometam a sua posse e propriedade sobre o Imóvel. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Qualquer alteração nos endereços eletrônicos de e-mail constantes no cadastro prévio realizado deverá ser prontamente comunicada à ADMINISTRADORA por instrumento que comprove a total ciência da imobiliária quanto a aludida mudança. Em se tratando de LOCATÁRIO pessoa jurídica, que seja obrigado ao pagamento de imposto de renda retido na fonte (IRRF) quando do pagamento do aluguel, compromete-se o LOCATÁRIO a apresentar mensalmente à ADMINISTRADORA os comprovantes de recolhimento do IRRF, na forma calculada no boleto emitido para pagamento do aluguel, sob pena de ser responsável por quaisquer valores despendidos pelo LOCADOR perante a Receita Federal do Brasil, mesmo que apurados após a extinção do presente instrumento. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p102", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p103", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p104", "t": "[[ASSINATURAS]]"}]$mod$::jsonb, 'Texto-base enviado por Denis (16/11/2026)')
ON CONFLICT DO NOTHING;
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, 'seguro_tokio', 1, $mod$Seguro-fiança Tokio Marine$mod$, 'residencial', 'seguro_fianca', 'tokio', $mod$TOKIO MARINE$mod$, $mod$[{"id": "p001", "t": "PRÊAMBULO"}, {"id": "p002", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p003", "t": "[[LOCADOR]]"}, {"id": "p004", "t": "[[LOCATARIO]]"}, {"id": "p005", "t": "ADMINISTRADORA: [ADMINISTRADORA_QUALIFICACAO]; cuja a administração do referido imóvel perdurará durante o prazo de vigência do presente Contrato de Locação, estendendo-se até a data da efetiva entrega das chaves, estando cientes as partes celebrantes deste instrumento de que toda e qualquer questão decorrente deste deverá ser tratada prévia e diretamente junto à ADMINISTRADORA, sendo que o não cumprimento desta cláusula, poderá dar ensejo às medidas cabíveis de rescisão contratual por culpa da parte infratora, ou outras medidas cabíveis, além de isenção de responsabilidade da ADMINISTRADORA."}, {"id": "p006", "t": "GARANTIA LOCATICIA: CLÁUSULA OBRIGATÓRIA Nº 1 – DA GARANTIA LOCATÍCIA (Cláusula 1a – Obrigatória em todas as contratações) O seguro de Fiança Locatícia contratado pelo LOCADOR junto a TOKIO MARINE, garantirá esta locação, nos termos do inciso III, do artigo 37 da Lei do Inquilinato, mediante pagamento de prêmio, ressalvadas as exceções previstas nas condições gerais. São de conhecimento do LOCADOR e LOCATÁRIO(S) as Condições Gerais do seguro de Fiança Locatícia. Para efeito desta garanta, os prêmios iniciais e renovações, calculados conforme NORMAS VIGENTES, serão pagos pelo(s) Locatário(s), de acordo com o inciso XI, do artigo 23 da lei do inquilinato, sob pena de rescisão desta locação, com o consequente despejo e cancelamento da apólice. A apólice garantirá exclusivamente as coberturas especificadas na proposta de seguro. Eventuais débitos decorrentes do presente contrato, não pagos pelo(s) Locatário(s) após regularmente instados a tanto serão comunicados às entidades mantenedoras de bancos de dados de proteção ao crédito (Serasa, SPC, etc.), quer pelo Locador(a), quer pela Seguradora. Tais débitos incluem todas as despesas com as medidas judiciais cabíveis. Para exercer os direitos e dar cumprimento às obrigações desse contrato, os LOCATÁRIOS declaram-se solidários entre si e constituem-se reciprocamente PROCURADORES, conferindose mutuamente poderes especiais para receber citações, notificações e intimações, confessar, desistir, e assinar tudo quanto se tornar necessário, transigir em Juízo ou fora dele, fazer acordos, firmar compromissos judiciais ou extrajudiciais, receber e dar quitação.", "trava": true}, {"id": "p007", "t": "CLÁUSULA ESPECIAL Nº 2 – DANOS AO IMÓVEL (quando contratada a cobertura de danos ao imóvel) O locatário declara para todos os fins e efeitos de direito, que recebe o imóvel locado no estado em que se encontra de conservação e uso, identificado no Laudo de Vistoria Inicial o qual é parte integrante deste contrato, assinado por todos os contratantes, obrigando-se e comprometendo-se a devolvê-lo nesse estado, independentemente de qualquer aviso ou notificação prévia e qualquer que seja o motivo de devolução, sob pena de incorrer nas cominações previstas neste contrato ou estipuladas em lei, além da obrigação de indenizar por danos ou prejuízos decorrentes da inobservância dessa obrigação, salvo as deteriorações decorrentes do uso normal do imóvel.", "trava": true}, {"id": "p008", "t": "CLÁUSULA ESPECIAL Nº 3 – PINTURA INTERNA (Cláusula 3 – quando contratada a cobertura de pintura interna) Declara o locatário, para todos os fins e efeitos de direito, que recebe o imóvel locado com Pintura Interna NOVA, e assim obriga-se, ao final da locação, a pintá-lo e devolvê-lo no mesmo estado em que recebeu, sob pena de incorrer nas cominações previstas neste contrato ou estipuladas em lei. O locatário declara ainda estar ciente de que, não devolvendo o imóvel pintado internamente, a Seguradora indenizará o locador pelo ônus da pintura, e terá direito de reaver o valor que tiver sido pago. O Segurado deverá comunicar o Sinistro a TOKIO MARINE no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel.", "trava": true}, {"id": "p009", "t": "CLÁUSULA ESPECIAL Nº 4 – PINTURA EXTERNA (Cláusula 4 – quando contratada a cobertura de pintura externa) Declara o locatário, para todos os fins e efeitos de direito, que recebe o imóvel locado com Pintura Externa NOVA, e assim obriga-se, ao final da locação, a pintá-lo e devolvê-lo no mesmo estado que recebeu, sob pena de incorrer nas cominações previstas neste contrato ou estipuladas em lei. O locatário declara ainda estar ciente de que não devolvendo o imóvel pintado externamente, a Seguradora indenizará o locador pelo ônus da pintura, e terá direito de reaver o valor que tiver sido pago. O Segurado deverá comunicar o Sinistro a TOKIO MARINE no prazo máximo de 15 (quinze) dias a contar da desocupação do imóvel. Esta cobertura é válida somente para imóveis residenciais e não residenciais do tipo “casa”, onde o locatário ocupa a totalidade do imóvel alugado.", "trava": true}, {"id": "p010", "t": "APÓLICE: [APOLICE_REFERENCIA]"}, {"id": "p011", "t": "[[OBJETO]]"}, {"id": "p012", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p013", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p014", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso de MORADIA dos LOCATÁRIO (S).", "dest": "residencial"}, {"id": "p015", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso COMERCIAL dos LOCATÁRIO (S).", "dest": "comercial", "adaptado": true}, {"id": "p016", "t": "[[PRAZO]]"}, {"id": "p017", "t": "Cláusula 1º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), conforme acordado entre as partes e o(a) LOCATÁRIO(A) se compromete a pagar pontualmente até o dia [DIA_VENCIMENTO] de cada mês subsequente."}, {"id": "p018", "t": "Cláusula 2º - O primeiro aluguel será pago 30 dias após a data de entrega das chaves e os aluguéis subsequentes, serão pagos na data de vencimento fixada neste documento."}, {"id": "p019", "t": "[[ADICIONAIS]]"}, {"id": "p020", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p021", "t": "O valor do aluguel pode ser acrescido de acessórios locatícios e encargos, se aplicável, conforme estipulado neste contrato. O cômputo desses encargos será a partir da posse da chave e serão cobrados juntamente com o aluguel na data estabelecida."}, {"id": "p022", "t": "Cláusula 3º - O aluguel mensal deve ser pago juntamente com os demais encargos, em moeda corrente nacional, em seu vencimento, ficando em caso contrário acrescidos de multa de 10% (dez por cento) do seu valor, mais juros de 1% (um por cento) ao mês, mais a correção monetária prevista em lei, a título de penalidade contratual, sem prejuízo da exigibilidade das demais correções estipuladas."}, {"id": "p023", "t": "Cláusula 4º - O pagamento dos alugueis e encargos locatícios devem ser realizados por meio de boleto bancário, que será emitido pela ADMINISTRADORA."}, {"id": "p024", "t": "Cláusula 5º - Caso o LOCATÁRIO não receba o boleto com a cobrança em ate 02 (dois) dias úteis antes do vencimento, será de responsabilidade do mesmo, entrar em contato com a ADMINISTRADORA para solicitar a emissão da 2º via de boleto."}, {"id": "p025", "t": "Cláusula 6º - Além das penalidades previstas na CLÁUSULA 3º, a falta de pagamento do aluguel na data estipulada poderá acarretar a rescisão do presente contrato, após 15 (quinze) dias da data do vencimento, ficando o LOCATÁRIO(S) responsável pela multa prevista na CLÁUSULA 28º - Parágrafo segundo do presente contrato, pelas despesas processuais e honorários advocatícios."}, {"id": "p026", "t": "Cláusula 7º - O LOCATÁRIO(S) não terá direito a reter o pagamento do aluguel ou de qualquer outra quantia devida nos termos do presente contrato, sob a alegação de não terem sido atendidas exigências porventura solicitadas."}, {"id": "p027", "t": "Cláusula 8º – O LOCATÁRIO(S) fica ciente nesta data que, antes da propositura da ação de despejo por falta de pagamento do aluguel e encargos na data estipulada neste contrato, poderá haver o protesto, junto ao cartório competente."}, {"id": "p028", "t": "Cláusula 9º - Eventual inadimplência do aluguel e encargos por parte dos LOCATÁRIO (S), ensejará Ação Judicial, independente do prazo da mora, não se responsabilizando o LOCADOR(A) pela inclusão dos nomes dos devedores ou de seus Fiadores junto às entidades mantenedoras de bancos de proteção ao crédito, SERASA, SCPC etc."}, {"id": "p029", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p030", "t": "O valor do aluguel ora contratado sofrerá reajuste anualmente, em conformidade com a legislação específica. Entretanto, havendo alteração legal para nova periodicidade, esta será aplicada automaticamente, independentemente de confirmação das partes."}, {"id": "p031", "t": "INDEXADORES:"}, {"id": "p032", "t": "As partes de comum acordo estabelecem o índice IPCA (Índice Nacional de Preços ao Consumidor Amplo), para a correção do aluguel, que será aplicado de acordo com a periodicidade acima. Havendo a extinção do mesmo, por determinação legal, as partes elegerão seu substituto imediatamente após a eventual extinção."}, {"id": "p033", "t": "Cláusula 10º - O LOCATÁRIO autoriza a administradora a efetuar a cobrança dos valores relativos a IPTU e CONDOMÍNIO vincendo juntamente com o aluguel vencido, antes da data do vencimento junto a autarquia municipal e a empresa administradora do condomínio (referente ao mês subsequente de vencimento), mesmo que não vencido e escoado a data de pagamento, visando o repasse ao LOCADOR, para o pagamento direto de referidas despesas."}, {"id": "p034", "t": "Cláusula 11º - No caso dos carnês e/ou avisos dos tributos citados na cláusula acima serem entregues diretamente ao LOCATÁRIO (S), este deverá encaminhá-los ao endereço da ADMINISTRADORA, antes do vencimento dos títulos no prazo de até 5 (cinco) dias úteis, sob pena de responderem pelas multas do atraso."}, {"id": "p035", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p036", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p037", "t": "Cláusula 12º - O LOCATÁRIA obriga-se a providenciar, junto às concessionárias competente, a transferência da titularidade das contas de ÁGUA, ENERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p038", "t": "DO DESCUMPRIMENTO E DAS PROVIDÊNCIAS ADMINISTRATIVAS:"}, {"id": "p039", "t": "Cláusula 13º – Caso o LOCATÁRIO não consiga realizar a transferência de titularidade das contas de Á GUA, ENERGIA ELÉTRICA e GÁS antes da retirada das chaves, deverá apresentar à ADMINISTRADORA a devida comprovação das tentativas realizadas e da impossibilidade de efetivação, ficando a retirada das chaves condicionada à autorização expressa do LOCADOR. Uma vez autorizada a retirada das chaves pelo LOCADOR, o LOCATÁRIO deverá apresentar à ADMINISTRADORA, no prazo máximo de 15 (quinze) dias corridos, contados da data da retirada das chaves, os respectivos comprovantes de efetivação da transferência de titularidade das referidas contas."}, {"id": "p040", "t": "Cláusula 14º - O não atendimento da obrigação no prazo estabelecido, sem a devida comprovação de impedimento não imputável ao LOCATÁRIO, caracterizará descumprimento contratual e ensejará a aplicação de multa administrativa no valor de R$ 250,00 (duzentos e cinquenta reais), a ser lançada no boleto de aluguel imediatamente subsequente à constatação do descumprimento."}, {"id": "p041", "t": "Na ausência de comprovação de regularização após o prazo previsto, a ADMINISTRADORA poderá, quando tecnicamente possível e mediante os documentos e autorizaçãoes necessários, adorar as providências cabíveis perante as respectivas concessionárias para a regularização da titularidade, ficando o LOCATÁRIO responsável pelos eventuais custos, taxas ou encargos decorrentes de tais providências, quando comprovadamente de sua responsabilidade, sem prejuízo da multa prevista nesta cláusula."}, {"id": "p042", "t": "Cláusula 15º - O LOCATÁRIO recebendo na data da assinatura deste contrato, o respectivo laudo de vistoria inicial, cujo documento aponta o estado de conservação do imóvel, declara concordar que o imóvel tem como finalidade, o uso de HABITAÇÃO, considerando inclusive suas instalações ELÉTRICAS, HIDRÁULICAS e SANITÁRIAS. Obriga-se o LOCATÁRIO a manter o imóvel assim como consta em LAUDO DE VISTORIA INICIAL, de forma a tudo restituir na mais perfeita ordem e no mesmo estado de conservação, higiene e funcionamento, quando findo ou rescindido o presente contrato, de modo que possa ser imediatamente ocupado pelo LOCADOR ou por quem este indicar, sem que isso dependa de qualquer conserto, reparação, etc. O LOCADOR será responsável pelos problemas estruturais, caso seja necessario.", "dest": "residencial"}, {"id": "p043", "t": "Cláusula 15º - O LOCATÁRIO recebendo na data da assinatura deste contrato, o respectivo laudo de vistoria inicial, cujo documento aponta o estado de conservação do imóvel, declara concordar que o imóvel tem como finalidade, o uso COMERCIAL, considerando inclusive suas instalações ELÉTRICAS, HIDRÁULICAS e SANITÁRIAS. Obriga-se o LOCATÁRIO a manter o imóvel assim como consta em LAUDO DE VISTORIA INICIAL, de forma a tudo restituir na mais perfeita ordem e no mesmo estado de conservação, higiene e funcionamento, quando findo ou rescindido o presente contrato, de modo que possa ser imediatamente ocupado pelo LOCADOR ou por quem este indicar, sem que isso dependa de qualquer conserto, reparação, etc. O LOCADOR será responsável pelos problemas estruturais, caso seja necessario.", "dest": "comercial", "adaptado": true}, {"id": "p044", "t": "Cláusula 16º - Em caso de discordância do laudo de vistoria inicial, o LOCATÁRIO terá o prazo de 10 (dez) dias corridos para realizar sua contestação, mediante formalização por email ou notificação por correios. O silêncio será considerado concordância ao laudo inicial apresentado."}, {"id": "p045", "t": "Cláusula 17º - Fica terminantemente proibida a colocação de pregos e parafusos nas paredes ou executar furos nos azulejos. Caso o LOCATÁRIO necessite fixar armários de cozinha ou outros, deverá solicitar autorização por escrito ao LOCADOR, ocasião em que, uma vez autorizado, receberá uma cópia da planta hidráulica e elétrica do imóvel."}, {"id": "p046", "t": "Cláusula 18º - A repintura no imóvel ora locado por parte do LOCATÁRIO, deverá ser compatível com a tinta anterior, ou seja, nas mesmas cores e qualidade que foi entregue."}, {"id": "p047", "t": "Cláusula 19º - Os pisos, azulejos, armários modulados, ou qualquer item de acabamento do imóvel ora locado por parte do LOCATÁRIO, deverá ser entregue nas mesmas condições recebidas, ou seja, caso danifique algum desses itens, o mesmo deverá ser substituído pelo mesmo modelo, tamanho, marca e nas mesmas cores e qualidade que foi entregue."}, {"id": "p048", "t": "Cláusula 20º - Caso algum piso seja danificado e o LOCATÁRIO não encontre o mesmo modelo disponível para compra, ou tenha saído de fabricação, deverá consultar o LOCADOR, através da ADMINISTRADORA, um outro modelo compatível aceito para substituição de todos os pisos e em todos os ambientes que o integram, arcando o LOCATÁRIO com todo o custo de material e instalação."}, {"id": "p049", "t": "Cláusula 21º - Fica o LOCATÁRIO, responsável pela verificação da voltagem da corrente elétrica existente no imóvel, em todos os seus pontos, assumindo para si, eventuais danos em aparelhos e/ou equipamentos que sejam ligados sem a devida checagem."}, {"id": "p050", "t": "Cláusula 22º - O LOCATÁRIO não poderá fazer modificações ou transformações no imóvel locado, nem introduzir quaisquer benfeitorias, sem que haja prévio aviso e consentimento por escrito do LOCADOR. Realizado benfeitorias, desde que tenham sido com o consentimento expresso da LOCADOR, essas ficarão incorporadas ao imóvel sem qualquer direito ao LOCATÁRIO, de retenção ou indenização, ao término da locação."}, {"id": "p051", "t": "Cláusula 23º - São de responsabilidade do LOCATÁRIO as obras de manutenção do imóvel, cabendo exclusivamente ao LOCADOR aquelas que importem na estrutura e segurança dele, nos termos da legislação vigente. I): Sendo necessária a realização de qualquer obra ou manutenção por parte do LOCADOR, o LOCATÁRIO deverá notifica-lo para que no prazo de até 05 (cinco) dias úteis do recebimento da notificação, dar início aos reparos necessários. Não sendo realizados, fica desde já autorizado o LOCATÁRIO a realizar três orçamentos e providenciar a realização dos reparos que importem a estrutura ou segurança do imóvel e cobrá-los do LOCADOR pelo menor preço orçado."}, {"id": "p052", "t": "Cláusula 24º - Fica ainda facultado ao LOCADOR quando lhe convier, exigir a remoção de benfeitorias introduzidas no imóvel sem sua autorização, correndo todas as despesas por conta do LOCATÁRIO."}, {"id": "p053", "t": "Cláusula 25º - Se na VISTORIA FINAL for constatado qualquer anormalidade no imóvel, o LOCATÁRIO será notificado no prazo de 05 (cinco) dias corridos, para reparar o defeito ou substituir as peças ou aparelhos defeituosos por sua conta e risco. Não atendida esta notificação, ficará facultado ao LOCADOR providenciar os serviços, cobrando do LOCATÁRIO, os valores gastos com material e mão de obra, além dos dias de aluguel necessários para tais reparos."}, {"id": "p054", "t": "Parágrafo único: As partes concordam que a vistoria final do imóvel será realizada sem qualquer custo para o LOCATÁRIO. Contudo, caso seja necessária a realização de uma revistoria, será cobrada uma taxa de R$ 120,00 (cento e vinte) reais para cobrir custos envolvidos."}, {"id": "p055", "t": "Cláusula 26º - O LOCATÁRIO desde já, faculta o LOCADOR, ou seu representante devidamente constituído, examinar ou vistoriar o imóvel locado, quando entender conveniente, com aviso de 48 (quarenta e oito) horas de antecedência."}, {"id": "p056", "t": "Cláusula 27º - Ocorrerá a rescisão do presente contrato de pleno direito, no caso de desapropriação, incêndio ou acidente que sujeite o imóvel locado a obras que importem na sua reconstrução ainda que parcial, que impeçam o seu uso por mais de 45 (quarenta e cinco) dias, ou, ainda, no caso de se verificar ou ocorrer a insolvência, recuperação judicial ou falência do LOCATÁRIO, ou se forem verificados atos desabonadores, de ordem civil ou criminal de sua parte, sem prejuízo das demais cláusulas contratuais e da responsabilidade da multa contratual estipulada na CLÁUSULA 28º, que alcançará também os Fiadores (se houver)."}, {"id": "p057", "t": "Cláusula 28º - No caso de desapropriação do imóvel locado, ficará o LOCADOR desobrigado por todas as cláusulas deste contrato, ressalvando-se ao LOCATÁRIO tão somente o direito de haver do poder público desapropriante a indenização a que porventura tenha direito."}, {"id": "p058", "t": "Cláusula 29º - O LOCATÁRIO é obrigado a respeitar os direitos de vizinhança, a lei do silêncio, regras de condomínio, evitando a prática de quaisquer atos que venham a perturbar a tranquilidade e as condições de saúde pública."}, {"id": "p059", "t": "Parágrafo primeiro: Ocorrerá também a rescisão do presente contrato se o LOCATÁRIO infringir obrigação legal ou cometer infração a qualquer uma das cláusulas do presente instrumento."}, {"id": "p060", "t": "Parágrafo segundo: Fica estipulada a multa contratual compensatória proporcional de 03 (três) vezes o valor do aluguel vigente da época da eventual infração, em benefício ao LOCADOR, sem prejuízo da exigibilidade das obrigações assumidas por este instrumento, podendo o LOCADOR, se assim lhe convier, considerar ao mesmo tempo rescindido o presente contrato de locação, independentemente de qualquer formalidade."}, {"id": "p061", "t": "Cláusula 30º - O LOCATÁRIO assume o formal compromisso de 30 (trinta) dias antes de desocupar o imóvel, notificar por escrito a ADMINISTRADORA que, efetuará uma vistoria no mesmo a fim de ficar constatado o estado de conservação do imóvel."}, {"id": "p062", "t": "Cláusula 31º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p063", "t": "Cláusula 32º - Decorrido o PRAZO DA LOCAÇÃO e estando a locação vigorando por prazo indeterminado, o LOCATÁRIO poderá rescindir o contrato de locação mediante notificação por escrito á ADMINISTRADORA, com antecedência de 30 (trinta) dias da devolução das chaves."}, {"id": "p064", "t": "Parágrafo único: Na ausência do aviso acima citado, o LOCADOR poderá exigir a quantia correspondente a 01 (um) mês de aluguel e encargos vigentes da data da rescisão, conforme autoriza o artigo 6º, da Lei no 8.245/91."}, {"id": "p065", "t": "Cláusula 33º - Tudo quanto for devido em razão deste contrato, notadamente os aluguéis mensais e seus acessórios, será cobrado por ação judicial apropriada no FORO TERRITORIAL DO IMÓVEL, com expressa renúncia de qualquer outro, por mais privilegiado que seja, o qual desde já fica eleito pelos contratantes como seu domicílio, para que exercitem e cumpram todos os direitos e obrigações decorrentes do presente instrumento."}, {"id": "p066", "t": "Parágrafo único: Em qualquer procedimento judicial que o LOCATÁRIO der causa, correrão por sua conta além do principal, todas as custas e despesas oriundas desta medida e ainda, honorários advocatícios, mesmo em caso de purgação de mora, quando houver a propositura da ação ou logo após a distribuição da petição."}, {"id": "p067", "t": "Cláusula 34º - Não é permitida a transferência deste contrato, no todo ou em parte, a sublocação ou empréstimo do imóvel locado, sem prévio consentimento, por escrito do LOCADOR."}, {"id": "p068", "t": "Parágrafo único: Em caso de falecimento, separação de fato ou judicial, divórcio ou dissolução da união estável do LOCATÁRIO, esta locação prosseguirá automaticamente com seu cônjuge ou companheiro, este que permanecer no imóvel, nos termos da Lei."}, {"id": "p069", "t": "Cláusula 35º - Caso o imóvel seja colocado à venda, o LOCATÁRIO terá preferência na compra. Não havendo interesse no prazo de 30 (trinta) dias, o LOCATÁRIO deverá permitir e facilitar as visitas dos pretendentes ao mesmo, em conformidade com o artigo 27, da Lei no 8.245/91."}, {"id": "p070", "t": "Cláusula 36º - Ocorrendo interesse do LOCATÁRIO na compra do imóvel, sua manifestação deverá ser encaminhada por escrito, à ADMINISTRADORA, com a devida intervenção do corretor de imóveis da mesma empresa, a quem caberá a intermediação para a concretização do negócio."}, {"id": "p071", "t": "Cláusula 37º - Alugado o imóvel, a administração exercida pela ADMINISTRADORA, será realizada até o efetivo recebimento de todos dos valores em aberto ou até o recebimento das chaves, o que ocorrer primeiro."}, {"id": "p072", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p073", "t": "Cláusula 38º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da parte perecível do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p074", "t": "Parágrafo primeiro: O LOCATÁRIO (S), poderá ele mesmo contratar e apresentar a apólice para a ADMINISTRADORA, porém, somente serão aceitas apólices que apresentarem seu pagamento integral."}, {"id": "p075", "t": "Parágrafo segundo: Quanto a atualização e renovação do seguro, o valor segurado a ser corrigido durante a vigência do presente contrato, deverá comprovar que a apólice em vigor cubra sempre o custo para reconstrução do imóvel, onde caberá ao LOCATARIO providenciar a renovação do seguro na época própria, dando ciência ao LOCADOR ou a ADMINISTRADORA."}, {"id": "p076", "t": "Cláusula 39º - A falta do pagamento do seguro por parte do LOCATÁRIO, constituirá infração passível de rescisão do presente instrumento, independente da incidência da multa infracional prevista em contrato."}, {"id": "p077", "t": "Cláusula 40º - Em se tratando de edifício, fica desde já convencionado que não serão aceitas apólices coletivas de condomínio em substituição ao seguro mencionado na CLÁUSULA 38º."}, {"id": "p078", "t": "Cláusula 41º - Caso o LOCATÁRIO não apresente sua apólice contratada de forma particular à ADMINISTRADORA, ficará o LOCADOR automaticamente autorizado a contratar uma empresa Seguradora de sua preferência e lançar seus valores à vista na primeira parcela de cobrança de aluguel. As renovações serão cobradas automaticamente no boleto de pagamento do aluguel."}, {"id": "p079", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p080", "t": "Cláusula 42º - As partes declaram expresso consentimento que a ADMINISTRADORA irá coletar, tratar e compartilhar os dados necessários ao cumprimento do contrato, nos termos do art. 7°, inciso V da Lei Geral de Proteção de Dados, bem como os dados necessários para o cumprimento de obrigações legais, nos termos do art. 7°, inciso II da LGPD e os dados, se necessários para proteção de crédito, conforme autorizado, também pelo art. 7° inciso V da LGPD."}, {"id": "p081", "t": "Cláusula 43º - Outros dados poderão ser coletados, tratados e compartilhados para fins administrativos da imobiliária, conforme termo de consentimento específico."}, {"id": "p082", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p083", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p084", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IPCA (Índice Nacional de Preços ao Consumidor Amplo); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p085", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O LOCADOR declara ser o legítimo proprietário e/ou possuidor do Imóvel, o qual se encontra livre e desonerado de quaisquer direitos, obrigações e ônus, judiciais e/ou extrajudiciais, que possam comprometer este CONTRATO, assumindo o dever de indenizar e manter o LOCATÁRIO e a ADMINISTRADORA indenes de quaisquer responsabilidades decorrentes de medidas que comprometam a sua posse e propriedade sobre o Imóvel. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Qualquer alteração nos endereços eletrônicos de e-mail constantes no cadastro prévio realizado deverá ser prontamente comunicada à ADMINISTRADORA por instrumento que comprove a total ciência da imobiliária quanto a aludida mudança. Em se tratando de LOCATÁRIO pessoa jurídica, que seja obrigado ao pagamento de imposto de renda retido na fonte (IRRF) quando do pagamento do aluguel, compromete-se o LOCATÁRIO a apresentar mensalmente à ADMINISTRADORA os comprovantes de recolhimento do IRRF, na forma calculada no boleto emitido para pagamento do aluguel, sob pena de ser responsável por quaisquer valores despendidos pelo LOCADOR perante a Receita Federal do Brasil, mesmo que apurados após a extinção do presente instrumento. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p086", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p087", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p088", "t": "[[ASSINATURAS]]"}]$mod$::jsonb, 'Texto-base enviado por Denis (16/11/2026)')
ON CONFLICT DO NOTHING;
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, 'seguro_almada', 1, $mod$Garantia Almada$mod$, 'residencial', 'seguro_fianca', 'almada', $mod$SEGURO FIANÇA ALMADA$mod$, $mod$[{"id": "p001", "t": "PRÊAMBULO"}, {"id": "p002", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p003", "t": "[[LOCADOR]]"}, {"id": "p004", "t": "[[LOCATARIO]]"}, {"id": "p005", "t": "ADMINISTRADORA: [ADMINISTRADORA_QUALIFICACAO]; cuja a administração do referido imóvel perdurará durante o prazo de vigência do presente Contrato de Locação, estendendo-se até a data da efetiva entrega das chaves, estando cientes as partes celebrantes deste instrumento de que toda e qualquer questão decorrente deste deverá ser tratada prévia e diretamente junto à ADMINISTRADORA, sendo que o não cumprimento desta cláusula, poderá dar ensejo às medidas cabíveis de rescisão contratual por culpa da parte infratora, ou outras medidas cabíveis, além de isenção de responsabilidade da ADMINISTRADORA."}, {"id": "p006", "t": "GARANTIA LOCATÍCIA: O Locatário contratou a ALMADA GARANTIAS CONTRATUAIS EMPREENDIMENTOS E PARTICIPACOES LTDA., inscrita no CNPJ nº 29.101.162/0001-06, com sede na Rua Pais Leme, 215 - Sala 201/220 Pinheiros, CEP 05424-010, São Paulo/SP, para atuar na condição de garantidor das obrigações financeiras do presente instrumento em caso de inadimplemento do Locatário, nos termos, limites e condições definidos na Carta de Aprovação e nos Termos e Condições Gerais ALMADA GARANTIAS que são de conhecimento das partes, especialmente no que diz respeito a: (i) valor máximo e limites de responsabilidade; (ii) prazo de vigência; (iii) condições de renovação; (iv) hipóteses de exoneração. A garantia locatícia foi contratada mediante o pagamento de uma remuneração conforme quadro resumo de prévio conhecimento do Locatário e do Locador e poderá ser paga à vista ou parcelada, competindo ao Locatário o pontual pagamento da remuneração. Caso o Locatário deixe de pagar a remuneração, total ou parcialmente, por qualquer motivo, a garantia será automaticamente extinta após 15 (quinze) dias do vencimento da fatura não paga, ficando facultadas ao Locador as seguintes hipóteses: (i) conceder prazo ao Locatário para substituição da garantia; (ii) assumir o pagamento dos valores em aberto para manter a garantia vigente, desde que não haja sinistro em andamento; (iii) dar por rescindido o contrato de locação. O Locador ou a Imobiliária/Corretor deverão comunicar à ALMADA GARANTIAS todo e qualquer inadimplemento do contrato de locação no prazo máximo de 15 (quinze) dias da data do inadimplemento para que a ALMADA GARANTIAS possa dar início aos procedimentos administrativos e financeiros previstos nos Termos e Condições ALMADA GARANTIAS.", "trava": true}, {"id": "p007", "t": "APÓLICE: [APOLICE_REFERENCIA]"}, {"id": "p008", "t": "[[OBJETO]]"}, {"id": "p009", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p010", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p011", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso de MORADIA dos LOCATÁRIO (S).", "dest": "residencial"}, {"id": "p012", "t": "O imóvel identificado no item OBJETO DA LOCAÇÃO, destina-se exclusivamente apenas para uso COMERCIAL dos LOCATÁRIO (S).", "dest": "comercial", "adaptado": true}, {"id": "p013", "t": "[[PRAZO]]"}, {"id": "p014", "t": "Cláusula 1º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), conforme acordado entre as partes e o(a) LOCATÁRIO(A) se compromete a pagar pontualmente até o dia [DIA_VENCIMENTO] de cada mês subsequente."}, {"id": "p015", "t": "Cláusula 2º - O primeiro aluguel será pago 30 dias após a data de entrega das chaves e os aluguéis subsequentes, serão pagos na data de vencimento fixada neste documento."}, {"id": "p016", "t": "[[ADICIONAIS]]"}, {"id": "p017", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p018", "t": "O valor do aluguel pode ser acrescido de acessórios locatícios e encargos, se aplicável, conforme estipulado neste contrato. O cômputo desses encargos será a partir da posse da chave e serão cobrados juntamente com o aluguel na data estabelecida."}, {"id": "p019", "t": "Cláusula 3º - O aluguel mensal deve ser pago juntamente com os demais encargos, em moeda corrente nacional, em seu vencimento, ficando em caso contrário acrescidos de multa de 10% (dez por cento) do seu valor, mais juros de 1% (um por cento) ao mês, mais a correção monetária prevista em lei, a título de penalidade contratual, sem prejuízo da exigibilidade das demais correções estipuladas."}, {"id": "p020", "t": "Cláusula 4º - O pagamento dos alugueis e encargos locatícios devem ser realizados por meio de boleto bancário, que será emitido pela ADMINISTRADORA."}, {"id": "p021", "t": "Cláusula 5º - Caso o LOCATÁRIO não receba o boleto com a cobrança em ate 02 (dois) dias úteis antes do vencimento, será de responsabilidade do mesmo, entrar em contato com a ADMINISTRADORA para solicitar a emissão da 2º via de boleto."}, {"id": "p022", "t": "Cláusula 6º - Além das penalidades previstas na CLÁUSULA 3º, a falta de pagamento do aluguel na data estipulada poderá acarretar a rescisão do presente contrato, após 15 (quinze) dias da data do vencimento, ficando o LOCATÁRIO(S) responsável pela multa prevista na CLÁUSULA 28º - Parágrafo segundo do presente contrato, pelas despesas processuais e honorários advocatícios."}, {"id": "p023", "t": "Cláusula 7º - O LOCATÁRIO(S) não terá direito a reter o pagamento do aluguel ou de qualquer outra quantia devida nos termos do presente contrato, sob a alegação de não terem sido atendidas exigências porventura solicitadas."}, {"id": "p024", "t": "Cláusula 8º – O LOCATÁRIO(S) fica ciente nesta data que, antes da propositura da ação de despejo por falta de pagamento do aluguel e encargos na data estipulada neste contrato, poderá haver o protesto, junto ao cartório competente."}, {"id": "p025", "t": "Cláusula 9º - Eventual inadimplência do aluguel e encargos por parte dos LOCATÁRIO (S), ensejará Ação Judicial, independente do prazo da mora, não se responsabilizando o LOCADOR(A) pela inclusão dos nomes dos devedores ou de seus Fiadores junto às entidades mantenedoras de bancos de proteção ao crédito, SERASA, SCPC etc."}, {"id": "p026", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p027", "t": "O valor do aluguel ora contratado sofrerá reajuste anualmente, em conformidade com a legislação específica. Entretanto, havendo alteração legal para nova periodicidade, esta será aplicada automaticamente, independentemente de confirmação das partes."}, {"id": "p028", "t": "INDEXADORES:"}, {"id": "p029", "t": "As partes de comum acordo estabelecem o índice IPCA (Índice Nacional de Preços ao Consumidor Amplo), para a correção do aluguel, que será aplicado de acordo com a periodicidade acima. Havendo a extinção do mesmo, por determinação legal, as partes elegerão seu substituto imediatamente após a eventual extinção."}, {"id": "p030", "t": "Cláusula 10º - O LOCATÁRIO autoriza a administradora a efetuar a cobrança dos valores relativos a IPTU e CONDOMÍNIO vincendo juntamente com o aluguel vencido, antes da data do vencimento junto a autarquia municipal e a empresa administradora do condomínio (referente ao mês subsequente de vencimento), mesmo que não vencido e escoado a data de pagamento, visando o repasse ao LOCADOR, para o pagamento direto de referidas despesas."}, {"id": "p031", "t": "Cláusula 11º - No caso dos carnês e/ou avisos dos tributos citados na cláusula acima serem entregues diretamente ao LOCATÁRIO (S), este deverá encaminhá-los ao endereço da ADMINISTRADORA, antes do vencimento dos títulos no prazo de até 5 (cinco) dias úteis, sob pena de responderem pelas multas do atraso."}, {"id": "p032", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p033", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p034", "t": "Cláusula 12º – O LOCATÁRIO obriga-se a providenciar, junto às concessionárias competentes, a transferência da titularidade das contas de ÁGUA, ENERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade das referidas contas, por parte do LOCATÁRIO, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p035", "t": "Cláusula 13º – O descumprimento da obrigação prevista na CLÁUSULA 12º, autoriza o LOCADOR a reter as chaves até a devida apresentação dos respectivos comprovantes, sem que isso gere qualquer direito de indenização ou alegação de atraso na imissão da posse por parte do LOCATÁRIO."}, {"id": "p036", "t": "Cláusula 14º - O LOCATÁRIO recebendo na data da assinatura deste contrato, o respectivo laudo de vistoria inicial, cujo documento aponta o estado de conservação do imóvel, declara concordar que o imóvel tem como finalidade, o uso de HABITAÇÃO, considerando inclusive suas instalações ELÉTRICAS, HIDRÁULICAS e SANITÁRIAS. Obriga-se o LOCATÁRIO a manter o imóvel assim como consta em LAUDO DE VISTORIA INICIAL, de forma a tudo restituir na mais perfeita ordem e no mesmo estado de conservação, higiene e funcionamento, quando findo ou rescindido o presente contrato, de modo que possa ser imediatamente ocupado pelo LOCADOR ou por quem este indicar, sem que isso dependa de qualquer conserto, reparação, etc. O LOCADOR será responsável pelos problemas estruturais, caso seja necessario.", "dest": "residencial"}, {"id": "p037", "t": "Cláusula 14º - O LOCATÁRIO recebendo na data da assinatura deste contrato, o respectivo laudo de vistoria inicial, cujo documento aponta o estado de conservação do imóvel, declara concordar que o imóvel tem como finalidade, o uso COMERCIAL, considerando inclusive suas instalações ELÉTRICAS, HIDRÁULICAS e SANITÁRIAS. Obriga-se o LOCATÁRIO a manter o imóvel assim como consta em LAUDO DE VISTORIA INICIAL, de forma a tudo restituir na mais perfeita ordem e no mesmo estado de conservação, higiene e funcionamento, quando findo ou rescindido o presente contrato, de modo que possa ser imediatamente ocupado pelo LOCADOR ou por quem este indicar, sem que isso dependa de qualquer conserto, reparação, etc. O LOCADOR será responsável pelos problemas estruturais, caso seja necessario.", "dest": "comercial", "adaptado": true}, {"id": "p038", "t": "Cláusula 15º - Em caso de discordância do laudo de vistoria inicial, o LOCATÁRIO terá o prazo de 10 (dez) dias corridos para realizar sua contestação, mediante formalização por email ou notificação por correios. O silêncio será considerado concordância ao laudo inicial apresentado."}, {"id": "p039", "t": "Cláusula 16º - Fica terminantemente proibida a colocação de pregos e parafusos nas paredes ou executar furos nos azulejos. Caso o LOCATÁRIO necessite fixar armários de cozinha ou outros, deverá solicitar autorização por escrito ao LOCADOR, ocasião em que, uma vez autorizado, receberá uma cópia da planta hidráulica e elétrica do imóvel."}, {"id": "p040", "t": "Cláusula 17º - A repintura no imóvel ora locado por parte do LOCATÁRIO, deverá ser compatível com a tinta anterior, ou seja, nas mesmas cores e qualidade que foi entregue."}, {"id": "p041", "t": "Cláusula 18º - Os pisos, azulejos, armários modulados, ou qualquer item de acabamento do imóvel ora locado por parte do LOCATÁRIO, deverá ser entregue nas mesmas condições recebidas, ou seja, caso danifique algum desses itens, o mesmo deverá ser substituído pelo mesmo modelo, tamanho, marca e nas mesmas cores e qualidade que foi entregue."}, {"id": "p042", "t": "Cláusula 19º - Caso algum piso seja danificado e o LOCATÁRIO não encontre o mesmo modelo disponível para compra, ou tenha saído de fabricação, deverá consultar o LOCADOR, através da ADMINISTRADORA, um outro modelo compatível aceito para substituição de todos os pisos e em todos os ambientes que o integram, arcando o LOCATÁRIO com todo o custo de material e instalação."}, {"id": "p043", "t": "Cláusula 20º - Fica o LOCATÁRIO, responsável pela verificação da voltagem da corrente elétrica existente no imóvel, em todos os seus pontos, assumindo para si, eventuais danos em aparelhos e/ou equipamentos que sejam ligados sem a devida checagem."}, {"id": "p044", "t": "Cláusula 21º - O LOCATÁRIO não poderá fazer modificações ou transformações no imóvel locado, nem introduzir quaisquer benfeitorias, sem que haja prévio aviso e consentimento por escrito do LOCADOR. Realizado benfeitorias, desde que tenham sido com o consentimento expresso da LOCADOR, essas ficarão incorporadas ao imóvel sem qualquer direito ao LOCATÁRIO, de retenção ou indenização, ao término da locação."}, {"id": "p045", "t": "Cláusula 22º - São de responsabilidade do LOCATÁRIO as obras de manutenção do imóvel, cabendo exclusivamente ao LOCADOR aquelas que importem na estrutura e segurança dele, nos termos da legislação vigente. I): Sendo necessária a realização de qualquer obra ou manutenção por parte do LOCADOR, o LOCATÁRIO deverá notifica-lo para que no prazo de até 05 (cinco) dias úteis do recebimento da notificação, dar início aos reparos necessários. Não sendo realizados, fica desde já autorizado o LOCATÁRIO a realizar três orçamentos e providenciar a realização dos reparos que importem a estrutura ou segurança do imóvel e cobrá-los do LOCADOR pelo menor preço orçado."}, {"id": "p046", "t": "Cláusula 23º - Fica ainda facultado ao LOCADOR quando lhe convier, exigir a remoção de benfeitorias introduzidas no imóvel sem sua autorização, correndo todas as despesas por conta do LOCATÁRIO."}, {"id": "p047", "t": "Cláusula 24º - Se na VISTORIA FINAL for constatado qualquer anormalidade no imóvel, o LOCATÁRIO será notificado no prazo de 05 (cinco) dias corridos, para reparar o defeito ou substituir as peças ou aparelhos defeituosos por sua conta e risco. Não atendida esta notificação, ficará facultado ao LOCADOR providenciar os serviços, cobrando do LOCATÁRIO, os valores gastos com material e mão de obra, além dos dias de aluguel necessários para tais reparos."}, {"id": "p048", "t": "Parágrafo único: As partes concordam que a vistoria final do imóvel será realizada sem qualquer custo para o LOCATÁRIO. Contudo, caso seja necessária a realização de uma revistoria, será cobrada uma taxa de R$ 120,00 (cento e vinte) reais para cobrir custos envolvidos."}, {"id": "p049", "t": "Cláusula 25º - O LOCATÁRIO desde já, faculta o LOCADOR, ou seu representante devidamente constituído, examinar ou vistoriar o imóvel locado, quando entender conveniente, com aviso de 48 (quarenta e oito) horas de antecedência."}, {"id": "p050", "t": "Cláusula 26º - Ocorrerá a rescisão do presente contrato de pleno direito, no caso de desapropriação, incêndio ou acidente que sujeite o imóvel locado a obras que importem na sua reconstrução ainda que parcial, que impeçam o seu uso por mais de 45 (quarenta e cinco) dias, ou, ainda, no caso de se verificar ou ocorrer a insolvência, recuperação judicial ou falência do LOCATÁRIO, ou se forem verificados atos desabonadores, de ordem civil ou criminal de sua parte, sem prejuízo das demais cláusulas contratuais e da responsabilidade da multa contratual estipulada na CLÁUSULA 28º, que alcançará também os Fiadores (se houver)."}, {"id": "p051", "t": "Cláusula 27º - No caso de desapropriação do imóvel locado, ficará o LOCADOR desobrigado por todas as cláusulas deste contrato, ressalvando-se ao LOCATÁRIO tão somente o direito de haver do poder público desapropriante a indenização a que porventura tenha direito."}, {"id": "p052", "t": "Cláusula 28º - O LOCATÁRIO é obrigado a respeitar os direitos de vizinhança, a lei do silêncio, regras de condomínio, evitando a prática de quaisquer atos que venham a perturbar a tranquilidade e as condições de saúde pública."}, {"id": "p053", "t": "Parágrafo primeiro: Ocorrerá também a rescisão do presente contrato se o LOCATÁRIO infringir obrigação legal ou cometer infração a qualquer uma das cláusulas do presente instrumento."}, {"id": "p054", "t": "Parágrafo segundo: Fica estipulada a multa contratual compensatória proporcional de 03 (três) vezes o valor do aluguel vigente da época da eventual infração, em benefício ao LOCADOR, sem prejuízo da exigibilidade das obrigações assumidas por este instrumento, podendo o LOCADOR, se assim lhe convier, considerar ao mesmo tempo rescindido o presente contrato de locação, independentemente de qualquer formalidade."}, {"id": "p055", "t": "Cláusula 29º - O LOCATÁRIO assume o formal compromisso de 30 (trinta) dias antes de desocupar o imóvel, notificar por escrito a ADMINISTRADORA que, efetuará uma vistoria no mesmo a fim de ficar constatado o estado de conservação do imóvel."}, {"id": "p056", "t": "Cláusula 30º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p057", "t": "Cláusula 31º - Decorrido o PRAZO DA LOCAÇÃO e estando a locação vigorando por prazo indeterminado, o LOCATÁRIO poderá rescindir o contrato de locação mediante notificação por escrito á ADMINISTRADORA, com antecedência de 30 (trinta) dias da devolução das chaves."}, {"id": "p058", "t": "Parágrafo único: Na ausência do aviso acima citado, o LOCADOR poderá exigir a quantia correspondente a 01 (um) mês de aluguel e encargos vigentes da data da rescisão, conforme autoriza o artigo 6º, da Lei no 8.245/91."}, {"id": "p059", "t": "Cláusula 32º - Tudo quanto for devido em razão deste contrato, notadamente os aluguéis mensais e seus acessórios, será cobrado por ação judicial apropriada no FORO TERRITORIAL DO IMÓVEL, com expressa renúncia de qualquer outro, por mais privilegiado que seja, o qual desde já fica eleito pelos contratantes como seu domicílio, para que exercitem e cumpram todos os direitos e obrigações decorrentes do presente instrumento."}, {"id": "p060", "t": "Parágrafo único: Em qualquer procedimento judicial que o LOCATÁRIO der causa, correrão por sua conta além do principal, todas as custas e despesas oriundas desta medida e ainda, honorários advocatícios, mesmo em caso de purgação de mora, quando houver a propositura da ação ou logo após a distribuição da petição."}, {"id": "p061", "t": "Cláusula 33º - Não é permitida a transferência deste contrato, no todo ou em parte, a sublocação ou empréstimo do imóvel locado, sem prévio consentimento, por escrito do LOCADOR."}, {"id": "p062", "t": "Parágrafo único: Em caso de falecimento, separação de fato ou judicial, divórcio ou dissolução da união estável do LOCATÁRIO, esta locação prosseguirá automaticamente com seu cônjuge ou companheiro, este que permanecer no imóvel, nos termos da Lei."}, {"id": "p063", "t": "Cláusula 34º - Caso o imóvel seja colocado à venda, o LOCATÁRIO terá preferência na compra. Não havendo interesse no prazo de 30 (trinta) dias, o LOCATÁRIO deverá permitir e facilitar as visitas dos pretendentes ao mesmo, em conformidade com o artigo 27, da Lei no 8.245/91."}, {"id": "p064", "t": "Cláusula 35º - Ocorrendo interesse do LOCATÁRIO na compra do imóvel, sua manifestação deverá ser encaminhada por escrito, à ADMINISTRADORA, com a devida intervenção do corretor de imóveis da mesma empresa, a quem caberá a intermediação para a concretização do negócio."}, {"id": "p065", "t": "Cláusula 36º - Alugado o imóvel, a administração exercida pela ADMINISTRADORA, será realizada até o efetivo recebimento de todos dos valores em aberto ou até o recebimento das chaves, o que ocorrer primeiro."}, {"id": "p066", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p067", "t": "Cláusula 37º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da parte perecível do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p068", "t": "Parágrafo primeiro: O LOCATÁRIO (S), poderá ele mesmo contratar e apresentar a apólice para a ADMINISTRADORA, porém, somente serão aceitas apólices que apresentarem seu pagamento integral."}, {"id": "p069", "t": "Parágrafo segundo: Quanto a atualização e renovação do seguro, o valor segurado a ser corrigido durante a vigência do presente contrato, deverá comprovar que a apólice em vigor cubra sempre o custo para reconstrução do imóvel, onde caberá ao LOCATARIO providenciar a renovação do seguro na época própria, dando ciência ao LOCADOR ou a ADMINISTRADORA."}, {"id": "p070", "t": "Cláusula 38º - A falta do pagamento do seguro por parte do LOCATÁRIO, constituirá infração passível de rescisão do presente instrumento, independente da incidência da multa infracional prevista em contrato."}, {"id": "p071", "t": "Cláusula 39º - Em se tratando de edifício, fica desde já convencionado que não serão aceitas apólices coletivas de condomínio em substituição ao seguro mencionado na CLÁUSULA 38º."}, {"id": "p072", "t": "Cláusula 40º - Caso o LOCATÁRIO não apresente sua apólice contratada de forma particular à ADMINISTRADORA, ficará o LOCADOR automaticamente autorizado a contratar uma empresa Seguradora de sua preferência e lançar seus valores à vista na primeira parcela de cobrança de aluguel. As renovações serão cobradas automaticamente no boleto de pagamento do aluguel."}, {"id": "p073", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p074", "t": "Cláusula 41º - As partes declaram expresso consentimento que a ADMINISTRADORA irá coletar, tratar e compartilhar os dados necessários ao cumprimento do contrato, nos termos do art. 7°, inciso V da Lei Geral de Proteção de Dados, bem como os dados necessários para o cumprimento de obrigações legais, nos termos do art. 7°, inciso II da LGPD e os dados, se necessários para proteção de crédito, conforme autorizado, também pelo art. 7° inciso V da LGPD."}, {"id": "p075", "t": "Cláusula 42º - Outros dados poderão ser coletados, tratados e compartilhados para fins administrativos da imobiliária, conforme termo de consentimento específico."}, {"id": "p076", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p077", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p078", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IPCA (Índice Nacional de Preços ao Consumidor Amplo); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p079", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O LOCADOR declara ser o legítimo proprietário e/ou possuidor do Imóvel, o qual se encontra livre e desonerado de quaisquer direitos, obrigações e ônus, judiciais e/ou extrajudiciais, que possam comprometer este CONTRATO, assumindo o dever de indenizar e manter o LOCATÁRIO e a ADMINISTRADORA indenes de quaisquer responsabilidades decorrentes de medidas que comprometam a sua posse e propriedade sobre o Imóvel. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Qualquer alteração nos endereços eletrônicos de e-mail constantes no cadastro prévio realizado deverá ser prontamente comunicada à ADMINISTRADORA por instrumento que comprove a total ciência da imobiliária quanto a aludida mudança. Em se tratando de LOCATÁRIO pessoa jurídica, que seja obrigado ao pagamento de imposto de renda retido na fonte (IRRF) quando do pagamento do aluguel, compromete-se o LOCATÁRIO a apresentar mensalmente à ADMINISTRADORA os comprovantes de recolhimento do IRRF, na forma calculada no boleto emitido para pagamento do aluguel, sob pena de ser responsável por quaisquer valores despendidos pelo LOCADOR perante a Receita Federal do Brasil, mesmo que apurados após a extinção do presente instrumento. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p080", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p081", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p082", "t": "[[ASSINATURAS]]"}]$mod$::jsonb, 'Texto-base enviado por Denis (16/11/2026)')
ON CONFLICT DO NOTHING;
INSERT INTO public.locacao_modelos (organization_id, chave, versao, titulo, tipo, garantia, seguradora, subtitulo, paragrafos, nota)
VALUES (NULL, 'loft', 1, $mod$Loft (CredPago)$mod$, 'residencial', 'loft', NULL, $mod$CREDPAGO$mod$, $mod$[{"id": "p001", "t": "QUADRO RESUMO: Locador(es); Locatário(a); Administradora; Imóvel; Destinação da Locação; Prazo da Locação; Valor e Vencimento do Aluguel; Primeiro Aluguel; Reajuste e Indexador; Encargos Locatícios; Contas de Consumo; Transferência de Titularidade; Garantia Locatícia; Inadimplência; Vistoria Inicial; Contestação da Vistoria; Conservação e Manutenção do Imóvel; Benfeitorias e Modificações; Vistoria Final e Revistoria; Rescisão e Multa Contratual; Desocupação e Aviso Prévio; Seguro Incêndio; Sublocação/Cessão; Preferência na Compra do Imóvel; Administração do Imóvel; LGPD; Disposições Gerais; Foro."}, {"id": "p002", "t": "PRÊAMBULO"}, {"id": "p003", "t": "Os signatários que contratam nas qualidades a seguir indicadas, têm entre si, ajustada a presente locação, mediante as condições e cláusulas seguintes:"}, {"id": "p004", "t": "[[LOCADOR]]"}, {"id": "p005", "t": "[[LOCATARIO]]"}, {"id": "p006", "t": "ADMINISTRADORA: [ADMINISTRADORA_QUALIFICACAO]; cuja a administração do referido imóvel perdurará durante o prazo de vigência do presente Contrato de Locação, estendendo-se até a data da efetiva entrega das chaves, estando cientes as partes celebrantes deste instrumento de que toda e qualquer questão decorrente deste deverá ser tratada prévia e diretamente junto à ADMINISTRADORA, sendo que o não cumprimento desta cláusula, poderá dar ensejo às medidas cabíveis de rescisão contratual por culpa da parte infratora, ou outras medidas cabíveis, além de isenção de responsabilidade da ADMINISTRADORA."}, {"id": "p007", "t": "GARANTIA LOCATÍCIA: O Inquilino realizou a contratação da LOFT SOLUÇÕES FINANCEIRAS S/A ., pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º 25.027.928/0001-90 (“LOFT”), à qual se compromete, quando solicitado pelo LOCADOR, por meio da Imobiliária (na qualidade de seu representante), a efetuar o pagamento de eventuais débitos relativos ao aluguel e demais encargos da presente locação que venham a ser inadimplidos pelo Inquilino até o limite do valor máximo afiançado, conforme condições constantes nos Termos e Condições Gerais da FIANÇA ALUGUEL (“T&C”) firmado pelo Inquilino, constantes no Anexo I deste instrumento, com o que o LOCADOR anui expressamente.", "trava": true}, {"id": "p008", "t": "O LOCADOR e o Inquilino declaram estar cientes e de acordo com todas as condições e limitações relativas à fiança prestada pela LOFT, notadamente, no tocante a: (i) o valor máximo afiançado, (ii) as limitações da responsabilidade da LOFT; (iii) o prazo de vigência da fiança contratada; (iv) as condições para sua renovação; (v) a possibilidade da LOFT substituir a fiança prestada por outra Modalidade de Garantia, especialmente, por seguro garantia financeiro; (vi) as hipóteses de término da FIANÇA ALUGUEL, que ocorrerá pelo primeiro dos seguintes eventos: (a) a entrega das chaves do Imóvel ao Locador; (b) a certidão de despejo emitida por Oficial de Justiça em ação de despejo; ou (c) a desocupação e disponibilização do Imóvel ao Locador; (vii) a inaplicabilidade, em relação à LOFT, de eventuais cláusulas deste instrumento que contrariem os T&C; e (viii) a rescisão imediata da FIANÇA ALUGUEL, com a consequente liberação da LOFT do pagamento de qualquer nova indenização, em caso de inadimplemento da contraprestação devida à LOFT pela prestação da fiança (“Taxa LOFT”).", "trava": true}, {"id": "p009", "t": "O Inquilino e o LOCADOR reconhecem que, o Contrato de Locação será considerado automaticamente rescindido e, por consequência, também será rescindida a garantia LOFT FIANÇA ALUGUEL em qualquer das hipóteses de término, previstas anteriormente, ficando a LOFT imediatamente liberada do pagamento de qualquer indenização.", "trava": true}, {"id": "p010", "t": "O LOCADOR declara-se ciente e concorda que os pagamentos dos valores afiançados serão realizados pela LOFT mediante depósito à Imobiliária, na qualidade de representante legal do Locador e se sub-rogará com relação aos valores desembolsados, operando-se, de forma automática, a cessão não onerosa de todos os direitos do Locador em relação ao pagamento efetuado, inclusive, mas não se limitando, a eventuais multas penais ou moratórias devidas pelo Inquilino.", "trava": true}, {"id": "p011", "t": "Nesta hipótese, o LOCADOR reconhece e aceita expressamente que, uma vez realizados os pagamentos à Imobiliária, a LOFT se exime de qualquer responsabilidade perante o LOCADOR caso a Imobiliária não realize o repasse dos valores ao LOCADOR.", "trava": true}, {"id": "p012", "t": "E o Inquilino concorda expressamente que, em caso exoneração da LOFT como fiadora por qualquer motivo detalhado no T&C, especialmente decorrente do inadimplemento do Inquilino, caberá a ele, promover, no prazo máximo de 30 (trinta) dias, a substituição da garantia locatícia prestada, o que só ocorrerá mediante expresso aceite da nova modalidade pelo LOCADOR, sob pena de infração contratual e ajuizamento da competente ação de despejo.", "trava": true}, {"id": "p013", "t": "O e-mail indicado pelo Inquilino para a Loft quando da contratação da FIANÇA ALUGUEL será considerado apto para recebimento de qualquer comunicação (inclusive judiciais) acerca do Contrato de Locação e decorrentes do T&C, independentemente de confirmação de recebimento. Desta forma, o Inquilino tem ciência que deverá manter seus dados cadastrais atualizados junto a LOFT.", "trava": true}, {"id": "p014", "t": "Para fins de cumprimento das obrigações previstas neste Contrato de Locação e nos T&C a ele vinculados, o LOCADOR, por meio deste instrumento, outorga poderes específicos à LOFT, na qualidade de fiadora do contrato de locação, de forma expressa, irrevogável e irretratável, mandato específico para representá-lo nas seguintes situações:", "trava": true}, {"id": "p015", "t": "(a) Na hipótese de rescisão motivada dos Termos e Condições firmados entre a LOFT e a Imobiliária, em razão do descumprimento, pela Imobiliária, das obrigações relativas à FIANÇA ALUGUEL, quais sejam: (i) a falta de repasse da Taxa LOFT na modalidade de Pagamento Via Imobiliária (PVI); (ii) a existência de indícios de participação em fraude; (iii) a cessão dos Termos e Condições da Imobiliária a terceiros em desacordo com o disposto no referido instrumento; e (iv) o descumprimento das Políticas da LOFT publicadas em seu site oficial. Nestas hipóteses, o LOCADOR, desde já, autoriza que a LOFT, de forma transitória, exerça os poderes anteriormente outorgados pelo Locador à Imobiliária exclusivamente no que se refere à FIANÇA ALUGUEL, sub-rogando-se, na medida do necessário, nos direitos e obrigações decorrentes do referido Termos e Condições, respeitado o direito de decisão do LOCADOR sobre a administração do imóvel.", "trava": true}, {"id": "p016", "t": "(b) Notificar o LOCATÁRIO, em nome do LOCADOR, em especial para que apresente nova modalidade de garantia locatícia no prazo de até 30 (trinta) dias, conforme previsto no artigo 40, §2º da Lei nº 8.245/1991 (Lei do Inquilinato), sob pena de rescisão contratual e adoção das medidas legais cabíveis;", "trava": true}, {"id": "p017", "t": "(c) Na hipótese de adesão à solução de Gestão de Despejos prestado pela LOFT, contratar advogado(s) e outorgar-lhes poderes, para promover, em nome do LOCADOR, o ajuizamento, condução e acompanhamento de ação de despejo, bem como outras ações judiciais ou procedimentos arbitrais relacionados à presente locação, incluindo, mas não se limitando a ações possessórias, medidas cautelares e ações de cobrança, perante qualquer juízo, instância, tribunal ou câmara arbitral (procuração ad judicia);", "trava": true}, {"id": "p018", "t": "(d) Ainda na hipótese de adesão à solução de Gestão de Despejos, os advogados contratados poderão receber poderes especiais para, em nome do LOCADOR, transigir, desistir, receber e dar quitação, firmar compromissos, renunciar a direitos, desistir de recursos e/ou reconhecer a procedência de pedidos, desde que tais atos estejam relacionados à defesa dos interesses do LOCADOR no âmbito da locação ora contratada.", "trava": true}, {"id": "p019", "t": "Parágrafo Primeiro: Os poderes permanecerão válidos enquanto vigente o presente contrato ou até que sejam expressamente revogados por instrumento escrito e registrado, sem prejuízo da validade dos atos já praticados.", "trava": true}, {"id": "p020", "t": "Parágrafo Segundo: O exercício dos poderes previstos nos itens (c) e (d) deste instrumento está condicionado à adesão do LOCADOR, por meio da Imobiliária, à solução de Gestão de Despejos prestada pela LOFT, conforme regras aplicáveis nos Termos e Condições da Fiança Aluguel.", "trava": true}, {"id": "p021", "t": "ANEXO I – Termos e Condições Gerais da FIANÇA ALUGUEL (LOFT): [LOFT_REFERENCIA]"}, {"id": "p022", "t": "[[OBJETO]]"}, {"id": "p023", "t": "Parágrafo Único: A descrição, características e estado de conservação do imóvel locado ficam constantes no LAUDO DE VISTORIA INICIAL, assinado e ratificado pelas partes, que passa a integrar o presente contrato de locação."}, {"id": "p024", "t": "DESTINAÇÃO DA LOCAÇÃO:"}, {"id": "p025", "t": "O imóvel identificado neste instrumento destina-se exclusivamente à MORADIA do LOCATÁRIO e dos moradores expressamente identificados neste contrato, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "residencial"}, {"id": "p026", "t": "O imóvel identificado neste instrumento destina-se exclusivamente ao uso COMERCIAL do LOCATÁRIO, sendo vedada a utilização para finalidade diversa sem prévia autorização por escrito do LOCADOR.", "dest": "comercial", "adaptado": true}, {"id": "p027", "t": "[[PRAZO]]"}, {"id": "p028", "t": "Cláusula 1º - O aluguel mensal ajustado é de R$ [VALOR_ALUGUEL] ([VALOR_ALUGUEL_EXTENSO]), devendo ser pago pelo LOCATÁRIO até o dia [DIA_VENCIMENTO] de cada mês, conforme as condições estabelecidas neste instrumento."}, {"id": "p029", "t": "Cláusula 2º - O primeiro aluguel vencerá 30 (trinta) dias após a efetiva entrega das chaves ao LOCATÁRIO. Os aluguéis subsequentes vencerão todo dia [DIA_VENCIMENTO] de cada mês, observando-se, quando necessário, o cálculo proporcional dos períodos de ocupação, a fim de evitar cobrança em duplicidade."}, {"id": "p030", "t": "[[ADICIONAIS]]"}, {"id": "p031", "t": "ACRÉSCIMO DE ACESSÓRIO LOCATÍCIOS E ENCARGOS:"}, {"id": "p032", "t": "Além do aluguel mensal, serão de responsabilidade do LOCATÁRIO os encargos locatícios expressamente atribuídos a ele neste contrato, os quais serão devidos a partir da efetiva entrega das chaves, observadas as disposições legais e contratuais aplicáveis."}, {"id": "p033", "t": "Cláusula 3º - O atraso no pagamento do aluguel ou de quaisquer encargos locatícios acarretará a incidência de multa moratória de 10% (dez por cento) sobre o valor devido, acrescida de juros de mora de 1% (um por cento) ao mês, calculados proporcionalmente aos dias de atraso, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p034", "t": "Cláusula 4º - O pagamento dos alugueis e encargos locatícios devem ser realizados por meio de boleto bancário, que será emitido pela ADMINISTRADORA."}, {"id": "p035", "t": "Cláusula 5º - Caso o LOCATÁRIO não receba o boleto bancário até 02 (dois) dias úteis antes do vencimento, deverá entrar em contato com a ADMINISTRADORA para solicitar a segunda via, permanecendo responsável pelo pagamento na data estabelecida, salvo eventual falha imputável à ADMINISTRADORA que tenha efetivamente impedido o pagamento."}, {"id": "p036", "t": "Cláusula 6º - O inadimplemento do aluguel ou de quaisquer encargos locatícios na data do vencimento constituirá o LOCATÁRIO em mora, independentemente de notificação, facultando ao LOCADOR adotar as medidas judiciais e extrajudiciais cabíveis, inclusive ação de despejo e cobrança, nos termos da Lei nº 8.245/91, sem prejuízo dos encargos moratórios previstos neste contrato."}, {"id": "p037", "t": "Cláusula 7º - O LOCATÁRIO não poderá suspender ou deixar de efetuar o pagamento dos aluguéis e encargos locatícios por iniciativa própria, devendo eventuais divergências ou solicitações relacionadas ao imóvel ser formalizadas perante a ADMINISTRADORA, sem prejuízo dos direitos assegurados pela legislação vigente."}, {"id": "p038", "t": "Cláusula 8º – O LOCATÁRIO declara estar ciente de que o inadimplemento das obrigações financeiras decorrentes deste contrato poderá ensejar o protesto dos respectivos débitos, observadas as exigências legais aplicáveis."}, {"id": "p039", "t": "Cláusula 9º - O inadimplemento das obrigações locatícias poderá ensejar a adoção das medidas judiciais cabíveis, bem como a comunicação dos débitos aos órgãos de proteção ao crédito, desde que observados os requisitos legais, inclusive quanto à legitimidade, exatidão e atualização das informações fornecidas."}, {"id": "p040", "t": "PERIODICIDADE DOS REAJUSTES:"}, {"id": "p041", "t": "O valor do aluguel será reajustado anualmente, respeitado o intervalo mínimo permitido pela legislação vigente, mediante aplicação do índice IPCA (Índice Nacional de Preços ao Consumidor Amplo), ou de outro índice oficial que venha a substituí-lo em caso de sua extinção, observadas as disposições legais aplicáveis."}, {"id": "p042", "t": "Cláusula 10º - O LOCATÁRIO será responsável pelo pagamento do IPTU e das despesas ordinárias de condomínio incidentes sobre o imóvel durante o período de sua posse, podendo tais valores ser incluídos no boleto mensal de aluguel para fins de cobrança e repasse. Permanecem sob responsabilidade exclusiva do LOCADOR as despesas extraordinárias de condomínio, conforme disposto no artigo 22, inciso X e parágrafo único, da Lei nº 8.245/91."}, {"id": "p043", "t": "Cláusula 11º - Caso o LOCATÁRIO receba diretamente carnês, avisos ou documentos referentes aos tributos e encargos de sua responsabilidade, deverá encaminhá-los à ADMINISTRADORA com antecedência suficiente para viabilizar o pagamento dentro do respectivo vencimento, respondendo por eventuais encargos decorrentes de sua omissão ou atraso injustificado."}, {"id": "p044", "t": "DAS CONTAS DE CONSUMO E DA ENTREGA DAS CHAVES:"}, {"id": "p045", "t": "O LOCATÁRIO assume integral responsabilidade pelo pagamento das contas de consumo de ÁGUA, ENERGIA ELÉTRICA e GÁS a partir da data de posse do imóvel (retirada das chaves)."}, {"id": "p046", "t": "Cláusula 12º – O locatário obriga-se a providenciar, junto às concessionárias competentes, a transferência da titularidade das de ÁGUA, ELERGIA ELÉTRICA e GÁS para o seu nome, antes da retirada das chaves do imóvel. A entrega das chaves ficará EXPRESSAMENTE condicionada à apresentação dos respectivos comprovantes de solicitação ou efetivação da transferência de titularidade, não sendo permitido o ingresso no imóvel antes do cumprimento desta obrigação."}, {"id": "p047", "t": "DO DESCUMPRIMENTO E DAS PROVIDÊNCIAS ADMINISTRATIVAS:"}, {"id": "p048", "t": "Cláusula 13º - Caso o LOCATÁRIO não consiga realizar a transferência de titularidade das contas de ÁGUA, ENERGIA ELÉTRICA e GÁS antes da retirada das chaves, deverá apresentar à ADMINISTRADORA a devida comprovação das tentativas realizadas e da impossibilidade de efetivação, ficando a retirada das chaves condicionada à autorização expressa do LOCADOR. Uma vez autorizada a retirada das chaves pelo LOCADOR, o LOCATÁRIO deverá apresentar à ADMINISTRADORA, no prazo máximo de 15 (quinze) dias corridos, contados da data da retirada das chaves, os respectivos comprovantes de efetivação da transferência de titularidade das referidas contas."}, {"id": "p049", "t": "O não atendimento da obrigação no prazo estabelecido, sem a devida comprovação de impedimento não imputável ao LOCATÁRIO, caracterizará descumprimento contratual e ensejará a aplicação de multa administrativa no valor de R$ 250,00 (duzentos e cinquenta reais), a ser lançada no boleto de aluguel imediatamente subsequente à constatação do descumprimento."}, {"id": "p050", "t": "Na ausência de comprovação da regularização após o prazo previsto, a ADMINISTRADORA poderá, quando tecnicamente possível e mediante os documetnos e autorizações necessárias, adotrar as providências cabíveis perante as respectivas concessionárias para a regularização da titularidade, ficando o LOCATÁRIO responsável pelos eventuais custos, taxas ou encargos decorrentes de tais providências, quando comprovadamente de sua responsabilidade, sem prejuízo da multa prevista nesta cláusula."}, {"id": "p051", "t": "Cláusula 14º - O LOCATÁRIO declara receber, na data da efetiva entrega das chaves, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso para HABITAÇÃO.", "dest": "residencial"}, {"id": "p052", "t": "Cláusula 14º - O LOCATÁRIO declara receber, na data da efetiva entrega das chaves, o imóvel descrito no LAUDO DE VISTORIA INICIAL, que integra o presente contrato para todos os fins de direito, comprometendo-se a conservá-lo no mesmo estado de conservação, higiene e funcionamento em que o recebeu, obrigando-se a devolvê-lo, ao término da locação, nas mesmas condições, ressalvado o desgaste natural decorrente do uso normal. Permanecem sob responsabilidade do LOCADOR os vícios ocultos, defeitos estruturais e reparos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, nos termos da legislação vigente. O imóvel tem como finalidade o uso COMERCIAL.", "dest": "comercial", "adaptado": true}, {"id": "p053", "t": "Cláusula 15º - Caso o LOCATÁRIO identifique divergências em relação ao laudo de vistoria inicial, deverá apresentar sua contestação por escrito à ADMINISTRADORA, no prazo de 10 (dez) dias corridos contados da entrega das chaves, preferencialmente acompanhada de fotografias ou outros registros que comprovem as condições apontadas. A ausência de manifestação dentro do prazo será considerada concordância quanto às condições aparentes descritas no laudo, ressalvados os vícios ocultos e defeitos não identificáveis em vistoria ordinária."}, {"id": "p054", "t": "Cláusula 16º - Fica permitido ao LOCATÁRIO realizar pequenos furos nas paredes do imóvel para a fixação de quadros, espelhos, suportes e objetos similares, desde que não comprometam a estrutura, as instalações hidráulicas ou elétricas. Fica expressamente vedada a realização de furos em azulejos, revestimentos cerâmicos e áreas impermeabilizadas, salvo mediante autorização prévia e por escrito do LOCADOR. Ao término da locação, o LOCATÁRIO deverá providenciar a adequada reparação dos furos realizados nas paredes, recompondo a pintura e o acabamento quando necessário, restituindo o imóvel nas condições em que o recebeu, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p055", "t": "Cláusula 17º - O LOCATÁRIO deverá devolver o imóvel com a pintura nas mesmas condições em que o recebeu, conforme descrito no laudo de vistoria inicial, responsabilizando-se pela reparação de manchas, riscos, alterações de cores, descascamentos ou danos decorrentes de uso inadequado ou de sua responsabilidade, ressalvado o desgaste natural decorrente do uso regular do imóvel."}, {"id": "p056", "t": "Cláusula 18º - O LOCATÁRIO deverá zelar pela conservação dos pisos, azulejos, armários, acessórios e demais itens que integram o imóvel, responsabilizando-se pelos danos que causar por ação, omissão ou uso inadequado, devendo providenciar o reparo ou a substituição dos itens danificados por outros de padrão, qualidade e características equivalentes aos originalmente existentes, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p057", "t": "Cláusula 19º - Caso algum piso seja danificado e o LOCATÁRIO não encontre o mesmo modelo disponível para compra, ou tenha saído de fabricação, deverá consultar o LOCADOR, através da ADMINISTRADORA, um outro modelo compatível aceito para substituição de todos os pisos do cômodo, arcando o LOCATÁRIO com todo o custo de material e instalação."}, {"id": "p058", "t": "Cláusula 20º - O LOCATÁRIO deverá verificar a tensão elétrica disponível nos pontos de energia do imóvel antes de conectar seus equipamentos e aparelhos eletrônicos, responsabilizando-se pelos danos decorrentes da utilização inadequada ou incompatível com a tensão disponível, desde que as instalações tenham sido entregues em condições regulares de funcionamento e que as informações disponíveis tenham sido corretamente fornecidas."}, {"id": "p059", "t": "Cláusula 21º - O LOCATÁRIO não poderá realizar modificações, alterações ou benfeitorias no imóvel sem prévia autorização, por escrito, do LOCADOR. Salvo ajuste expresso em contrário, as benfeitorias realizadas, ainda que autorizadas, incorporar-se-ão ao imóvel, sem direito de indenização ou retenção pelo LOCATÁRIO, nos termos do artigo 35 da Lei nº 8.245/91 e da Súmula 335 do STJ, ressalvadas as obrigações legais do LOCADOR relativas à conservação, segurança e habitabilidade do imóvel."}, {"id": "p060", "t": "Cláusula 22º - Compete ao LOCATÁRIO realizar os reparos e serviços de manutenção decorrentes do uso regular do imóvel, bem como reparar os danos causados por si, seus moradores, visitantes ou terceiros sob sua responsabilidade. Compete ao LOCADOR realizar os reparos relativos a vícios anteriores à locação, problemas estruturais e defeitos que comprometam a segurança, estabilidade ou habitabilidade do imóvel, desde que não decorrentes de ação ou omissão do LOCATÁRIO."}, {"id": "p061", "t": "PARÁGRAFO ÚNICO: Identificada a necessidade de reparo de responsabilidade do LOCADOR, o LOCATÁRIO deverá comunicar formalmente a ADMINISTRADORA, para que sejam adotadas as providências necessárias. Em situações urgentes, que envolvam risco à segurança ou agravamento de danos ao imóvel, deverá comunicar imediatamente a ADMINISTRADORA, permitindo a adoção das medidas emergenciais cabíveis, observadas as disposições legais quanto à responsabilidade pelos custos."}, {"id": "p062", "t": "Cláusula 23º - O LOCADOR poderá exigir que o LOCATÁRIO remova modificações ou benfeitorias realizadas sem autorização prévia e por escrito, quando necessário à recomposição do imóvel às condições originais, correndo as despesas correspondentes por conta do LOCATÁRIO, desde que decorrentes de sua responsabilidade."}, {"id": "p063", "t": "Cláusula 24º - Ao término da locação, será realizada vistoria final para verificar as condições de conservação do imóvel, mediante comparação com o laudo de vistoria inicial, ressalvado o desgaste natural decorrente do uso regular."}, {"id": "p064", "t": "Parágrafo 1º: Caso sejam constatados danos ou irregularidades de responsabilidade do LOCATÁRIO, este será comunicado para que possa providenciar os respectivos reparos no prazo de 05 (cinco) dias corridos, ou outro prazo acordado entre as partes, sem prejuízo da cobrança de eventuais valores necessários à recomposição do imóvel."}, {"id": "p065", "t": "Parágrafo 2º: Caso o LOCATÁRIO não realize os reparos de sua responsabilidade, o LOCADOR poderá providenciá-los e exigir o ressarcimento dos respectivos custos, mediante apresentação dos comprovantes pertinentes, sem prejuízo das demais medidas legais cabíveis."}, {"id": "p066", "t": "Parágrafo 3º: A vistoria final será realizada sem custo para o LOCATÁRIO. Caso seja necessária nova vistoria para verificação dos reparos executados, poderá ser cobrada taxa de revistoria no valor de R$ 150,00 (cento e cinquenta reais), desde que previamente informada e relacionada à necessidade de nova verificação de pendências de responsabilidade do LOCATÁRIO."}, {"id": "p067", "t": "Parágrafo 4º: A existência de danos ou pendências apontadas na vistoria não impedirá o recebimento das chaves nem a formalização da devolução do imóvel, permanecendo assegurado ao LOCADOR o direito de exigir o ressarcimento dos prejuízos comprovadamente atribuíveis ao LOCATÁRIO."}, {"id": "p068", "t": "Cláusula 25º - O LOCATÁRIO permitirá que o LOCADOR ou seu representante devidamente autorizado examine ou vistori? o imóvel, mediante prévio agendamento e comunicação com antecedência mínima de 48 (quarenta e oito) horas, em dia e horário previamente acordados entre as partes, respeitado o direito à privacidade e ao uso pacífico do imóvel."}, {"id": "p069", "t": "Cláusula 26º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade residencial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "residencial"}, {"id": "p070", "t": "Cláusula 26º - O presente contrato poderá ser rescindido nas hipóteses de desapropriação do imóvel ou de ocorrência de incêndio, sinistro ou outro evento que torne o imóvel total ou parcialmente impróprio para sua finalidade comercial, quando inviabilizada a continuidade da locação, observadas as circunstâncias do caso concreto e as disposições legais aplicáveis.", "dest": "comercial", "adaptado": true}, {"id": "p071", "t": "Cláusula 27º - Em caso de desapropriação do imóvel, a locação será extinta, ficando o LOCADOR desobrigado das obrigações futuras decorrentes deste contrato, ressalvados os direitos do LOCATÁRIO de pleitear eventual indenização diretamente perante o poder público desapropriante, quando legalmente cabível."}, {"id": "p072", "t": "Cláusula 28º - O LOCATÁRIO obriga-se a respeitar as normas de convivência, os direitos de vizinhança, as regras condominiais e a legislação vigente, abstendo-se de praticar atos que comprometam a segurança, a tranquilidade, a higiene ou o sossego dos demais moradores."}, {"id": "p073", "t": "Parágrafo primeiro: O descumprimento das obrigações legais ou contratuais poderá ensejar a aplicação das medidas cabíveis, inclusive rescisão da locação, conforme a natureza e a gravidade da infração, observadas as disposições da Lei nº 8.245/91."}, {"id": "p074", "t": "Parágrafo segundo: Fica estipulada multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente à época da infração, aplicável em caso de descumprimento contratual que justifique sua incidência, observados os critérios de proporcionalidade, a natureza da obrigação descumprida e a legislação vigente."}, {"id": "p075", "t": "Parágrafo terceiro: Na hipótese de devolução antecipada do imóvel por iniciativa do LOCATÁRIO durante o prazo determinado deste contrato, será devida multa compensatória equivalente a 03 (três) vezes o valor do aluguel vigente, calculada proporcionalmente ao período restante do contrato, conforme o artigo 4º da Lei nº 8.245/91."}, {"id": "p076", "t": "Cláusula 29º - O LOCATÁRIO assume o formal compromisso de 30 (trinta) dias antes de desocupar o imóvel, notificar por escrito a ADMINISTRADORA que, efetuará uma vistoria no mesmo a fim de ficar constatado o estado de conservação do imóvel."}, {"id": "p077", "t": "Cláusula 30º - Antes da devolução das chaves do imóvel ora locado, o LOCATÁRIO se compromete a agendar horário para entregar as chaves do mesmo, bem como, para que seja realizado laudo de vistoria final, o qual será assinado pelo LOCATÁRIO."}, {"id": "p078", "t": "Cláusula 31º - Após o término do prazo contratual, caso a locação prossiga por prazo indeterminado, o LOCATÁRIO poderá rescindir o contrato mediante comunicação por escrito ao LOCADOR ou à ADMINISTRADORA, com antecedência mínima de 30 (trinta) dias."}, {"id": "p079", "t": "Parágrafo único: Na ausência do aviso prévio previsto nesta cláusula, o LOCADOR poderá exigir quantia correspondente a 01 (um) mês de aluguel e encargos vigentes na data da rescisão, conforme disposto no artigo 6º, parágrafo único, da Lei nº 8.245/91."}, {"id": "p080", "t": "Cláusula 32º - Fica eleito o foro da comarca onde se localiza o imóvel objeto desta locação para dirimir quaisquer controvérsias decorrentes deste contrato, ressalvadas as hipóteses legais de competência absoluta."}, {"id": "p081", "t": "Parágrafo único: Em caso de demanda judicial decorrente do descumprimento das obrigações contratuais, as partes responderão pelas custas e despesas processuais, conforme a legislação vigente e eventual determinação judicial."}, {"id": "p082", "t": "Cláusula 33º - É vedado ao LOCATÁRIO ceder, transferir ou sublocar, total ou parcialmente, o imóvel objeto deste contrato, bem como emprestá-lo a terceiros, sem prévia autorização expressa e por escrito do LOCADOR, nos termos do artigo 13 da Lei nº 8.245/91."}, {"id": "p083", "t": "Parágrafo único: Em caso de separação de fato, separação judicial, divórcio ou dissolução da união estável do LOCATÁRIO, a locação prosseguirá automaticamente com aquele que permanecer no imóvel, observadas as disposições do artigo 12 da Lei nº 8.245/91, inclusive quanto à comunicação ao LOCADOR e ao FIADOR."}, {"id": "p084", "t": "Cláusula 34º - Caso o LOCADOR pretenda vender o imóvel durante a vigência da locação, deverá assegurar ao LOCATÁRIO o direito de preferência para aquisição, em igualdade de condições com terceiros, mediante comunicação formal contendo todas as condições do negócio, inclusive preço, forma de pagamento e demais informações pertinentes, nos termos dos artigos 27 e seguintes da Lei nº 8.245/91."}, {"id": "p085", "t": "Parágrafo único: O LOCATÁRIO terá o prazo legal de 30 (trinta) dias, contado do recebimento da comunicação, para manifestar sua aceitação integral e inequívoca da proposta. Caso não exerça o direito de preferência, deverá permitir visitas de interessados, mediante prévio agendamento e em horários previamente acordados."}, {"id": "p086", "t": "Cláusula 35º - Ocorrendo interesse do LOCATÁRIO na compra do imóvel, sua manifestação deverá ser encaminhada por escrito, à ADMINISTRADORA, com a devida intervenção do corretor de imóveis da mesma empresa, a quem caberá a intermediação para a concretização do negócio."}, {"id": "p087", "t": "Cláusula 36º - A ADMINISTRADORA permanecerá responsável pela administração da locação durante a vigência deste contrato, observados os poderes que lhe foram conferidos pelo LOCADOR, inclusive quanto aos procedimentos de encerramento, entrega das chaves, apuração de encargos e prestação de contas, conforme o respectivo contrato de administração."}, {"id": "p088", "t": "DO SEGURO OBRIGATÓRIO:"}, {"id": "p089", "t": "Cláusula 37º - Obriga-se o LOCATÁRIO a pagar além do aluguel e encargos estipulados neste contrato, o seguro contra risco de incêndio da estrutura e partes integrantes do imóvel locado, exceto bens pertencentes ao LOCATÁRIO, figurando o LOCADOR como o único beneficiário na respectiva apólice. Para efeitos desta cláusula, estimam as partes o valor da apólice de seguro incêndio em 200x o valor do aluguel, o qual será estipulado para apólice inicial do seguro a ser feito."}, {"id": "p090", "t": "Parágrafo primeiro: O LOCATÁRIO (S), poderá ele mesmo contratar e apresentar a apólice para a ADMINISTRADORA, porém, somente serão aceitas apólices que apresentarem seu pagamento integral."}, {"id": "p091", "t": "Parágrafo segundo: Quanto a atualização e renovação do seguro, o valor segurado a ser corrigido durante a vigência do presente contrato, deverá comprovar que a apólice em vigor cubra sempre o custo para reconstrução do imóvel, onde caberá ao LOCATARIO providenciar a renovação do seguro na época própria, dando ciência ao LOCADOR ou a ADMINISTRADORA."}, {"id": "p092", "t": "Cláusula 38º - O descumprimento da obrigação de contratação ou renovação do seguro contra incêndio, após notificação para regularização, poderá caracterizar infração contratual, sujeitando o LOCATÁRIO às medidas legais e contratuais cabíveis."}, {"id": "p093", "t": "Cláusula 39º - Em se tratando de edifício, fica desde já convencionado que não serão aceitas apólices coletivas de condomínio em substituição ao seguro incêndio individual."}, {"id": "p094", "t": "Cláusula 40º - Caso o LOCATÁRIO não apresente a apólice de seguro contratada por sua iniciativa dentro do prazo estabelecido, o LOCADOR poderá providenciar a contratação do seguro, mediante prévia comunicação ao LOCATÁRIO, sendo os respectivos custos de responsabilidade deste, desde que comprovados documentalmente. Os valores poderão ser incluídos no boleto de aluguel, observadas as condições e os prazos de pagamento informados pela ADMINISTRADORA."}, {"id": "p095", "t": "DA OBSERVÂNCIA À LGPD:"}, {"id": "p096", "t": "Cláusula 41º - As partes declaram estar cientes de que a ADMINISTRADORA poderá coletar, armazenar, utilizar e compartilhar os dados pessoais estritamente necessários à execução deste contrato, ao cumprimento de obrigações legais e regulatórias, bem como à proteção do crédito, observadas as bases legais previstas no artigo 7º, incisos II, V e X, da Lei nº 13.709/2018 (Lei Geral de Proteção de Dados Pessoais – LGPD)."}, {"id": "p097", "t": "Cláusula 42º - O tratamento de dados pessoais para finalidades adicionais, não abrangidas pelas hipóteses legais previstas na cláusula anterior, dependerá da existência de base legal adequada, inclusive consentimento específico do titular, quando necessário, assegurados os direitos previstos na Lei nº 13.709/2018."}, {"id": "p098", "t": "DISPOSIÇÕES GERAIS:"}, {"id": "p099", "t": "Considera-se em mora o LOCATÁRIO, independentemente de interpelação judicial ou extrajudicial, se não efetuar o pagamento dos alugueres e acessórios da locação no tempo, lugar e forma convencionados neste contrato (artigo 394 do Código Civil), a mora do LOCATÁRIO importará em:"}, {"id": "p100", "t": "1º) Se a purga da mora for extrajudicial, no pagamento da atualização monetária na conformidade da variação mensal do IPCA (Índice Nacional de Preços ao Consumidor Amplo); dos juros moratórios segundo a taxa de 1% (um por cento) ao mês; da multa penal de 10% (dez por cento) (artigos 408 e 409 do Código Civil) e dos honorários de advogado de 10% (dez por cento), independentemente de ação judicial (artigo 395 do Código Civil)."}, {"id": "p101", "t": "2º) Se a purga da mora for judicial, além da atualização monetária, dos juros moratórios e da multa penal, os honorários advocatícios sobre o total do débito (segunda parte da alínea \"d\" do inciso II, do artigo 62, da Lei nº 8.245/91), sendo ainda devidos pelo LOCATÁRIO as despesas judiciais antecipadas pelo LOCADOR e os honorários de condenação, ou sucumbenciais, fixados na sentença sobre o valor da condenação (artigo 20 e parágrafos 2º e 3º do Código de Processo Civil. O LOCADOR declara ser o legítimo proprietário e/ou possuidor do Imóvel, o qual se encontra livre e desonerado de quaisquer direitos, obrigações e ônus, judiciais e/ou extrajudiciais, que possam comprometer este CONTRATO, assumindo o dever de indenizar e manter o LOCATÁRIO e a ADMINISTRADORA indenes de quaisquer responsabilidades decorrentes de medidas que comprometam a sua posse e propriedade sobre o Imóvel. O(s) LOCATÁRIO(s) autorizam que as eventuais citações, intimações ou notificações sejam feitas por carta registrada ou por qualquer outro meio judicial ou extrajudicial, sendo certo que toda e qualquer comunicação enviada aos endereços eletrônicos de e-mail fornecidos nas qualificações do cadastro prévio será reputada como recebida e possuirá plena validade para todos os fins legais. Qualquer alteração nos endereços eletrônicos de e-mail constantes no cadastro prévio realizado deverá ser prontamente comunicada à ADMINISTRADORA por instrumento que comprove a total ciência da imobiliária quanto a aludida mudança. Em se tratando de LOCATÁRIO pessoa jurídica, que seja obrigado ao pagamento de imposto de renda retido na fonte (IRRF) quando do pagamento do aluguel, compromete-se o LOCATÁRIO a apresentar mensalmente à ADMINISTRADORA os comprovantes de recolhimento do IRRF, na forma calculada no boleto emitido para pagamento do aluguel, sob pena de ser responsável por quaisquer valores despendidos pelo LOCADOR perante a Receita Federal do Brasil, mesmo que apurados após a extinção do presente instrumento. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, a validade, legalidade e exequibilidade das demais disposições contidas neste Contrato não serão afetadas ou prejudicadas, devendo as partes negociar a substituição de quaisquer disposições inválidas, ilegais ou inexequíveis, por disposições válidas, legais e exequíveis, cujos efeitos deverão aproximar-se, tanto quanto possível, dos efeitos legais e econômicos almejados pelas disposições consideradas inválidas, ilegais ou inexequíveis. Qualquer omissão ou tolerância pelas partes na exigência do correto e pontual cumprimento dos termos e condições, específicas ou genéricas, constantes deste Contrato, inclusive quanto ao valor, forma e prazo de pagamento de aluguéis e encargos, ou no exercício de qualquer prerrogativa dele decorrente, não constituirá qualquer tipo de renúncia, desistência, nem afetará o direito de qualquer das Partes de exercê-los a qualquer tempo."}, {"id": "p102", "t": "A assinatura eletrônica tem validade jurídica e está amparada em diversas normas, dentre as quais o artigo 10, § 2 da Medida Provisória nº 2.200-2/2001, que institui a Infraestrutura de Chaves Públicas Brasileira – ICP-Brasil. “O disposto nesta Medida Provisória não obsta a utilização de outro meio de comprovação da autoria e integridade de documentos em forma eletrônica, inclusive os que utilizem certificados não emitidos pela ICP-Brasil, desde que admitido pelas partes como válido ou aceito pela pessoa a quem for oposto o documento”. Trata-se de um ambiente seguro para assinatura de documentos online, desenvolvido para reforçar a validade de documentos e assinaturas eletrônicas."}, {"id": "p103", "t": "E por estarem justos e contratados, aceitam desta forma, o presente documento eletronicamente."}, {"id": "p104", "t": "[[ASSINATURAS]]"}]$mod$::jsonb, 'Texto-base enviado por Denis (16/11/2026)')
ON CONFLICT DO NOTHING;

-- 6) Funções existentes alteradas (texto vigente + trocas mínimas) ----------------------------------------------
-- locacao_contrato_chaves: base 20261112120000_locacao_documentos_ia.sql
CREATE OR REPLACE FUNCTION public.locacao_contrato_chaves() RETURNS text[]
LANGUAGE sql IMMUTABLE SET search_path TO '' AS $$
  SELECT ARRAY[
    'loc_nome', 'loc_cpf', 'loc_rg', 'loc_nascimento', 'loc_nacionalidade', 'loc_estado_civil', 'loc_regime',
    'loc_profissao', 'loc_endereco', 'loc_email', 'loc_telefone',
    'prop_nome', 'prop_cpf', 'prop_rg', 'prop_nascimento', 'prop_nacionalidade', 'prop_estado_civil', 'prop_regime',
    'prop_profissao', 'prop_endereco', 'prop_email', 'prop_telefone',
    'prop_conj_nome', 'prop_conj_cpf', 'prop_conj_rg', 'prop_conj_nascimento', 'prop_conj_nacionalidade', 'prop_conj_profissao',
    'fia_nome', 'fia_cpf', 'fia_rg', 'fia_nascimento', 'fia_nacionalidade', 'fia_estado_civil', 'fia_regime',
    'fia_profissao', 'fia_endereco', 'fia_email', 'fia_telefone',
    'fia_conj_nome', 'fia_conj_cpf', 'fia_conj_rg', 'fia_conj_nascimento', 'fia_conj_nacionalidade', 'fia_conj_profissao',
    'fia_matricula', 'fia_cartorio',
    'imv_inscricao', 'imv_energia', 'imv_agua', 'imv_gas', 'imv_vagas',
    'prazo_meses', 'inicio', 'dia_vencimento', 'moradores',
    'seg_seguradora', 'seg_apolice', 'cau_tipo', 'cau_valor', 'cau_meses', 'cau_forma', 'cau_favorecido',
    'cauc_nome', 'cauc_cpf', 'cauc_rg', 'cauc_nacionalidade', 'cauc_estado_civil', 'cauc_profissao', 'cauc_endereco',
    'cauc_imovel_descricao', 'cauc_imovel_matricula', 'cauc_imovel_cartorio', 'loft_numero']::text[]
$$;
-- locacao_contrato_valor_ok: base 20261112120000_locacao_documentos_ia.sql
CREATE OR REPLACE FUNCTION public.locacao_contrato_valor_ok(_k text, _v text) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SET search_path TO '' AS $$
DECLARE _d date;
BEGIN
  IF _k IS NULL OR NOT (_k = ANY (public.locacao_contrato_chaves())) THEN RETURN false; END IF;
  IF _v IS NULL OR _v = '' THEN RETURN true; END IF;
  IF length(_v) > (CASE WHEN _k IN ('moradores', 'cauc_imovel_descricao') THEN 2000 ELSE 300 END) THEN RETURN false; END IF;
  IF _k = 'inicio' OR _k LIKE '%nascimento' THEN
    IF _v !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RETURN false; END IF;
    BEGIN _d := _v::date; EXCEPTION WHEN others THEN RETURN false; END;
    RETURN to_char(_d, 'YYYY-MM-DD') = _v AND _d BETWEEN DATE '1900-01-01' AND DATE '2100-12-31';
  END IF;
  IF _k = 'prazo_meses' THEN RETURN _v ~ '^[0-9]{1,3}$' AND _v::integer BETWEEN 1 AND 240; END IF;
  IF _k = 'dia_vencimento' THEN RETURN _v ~ '^[0-9]{1,2}$' AND _v::integer BETWEEN 1 AND 28; END IF;
  IF _k = 'seg_seguradora' THEN RETURN _v IN ('porto', 'pottencial', 'tokio', 'almada'); END IF;
  IF _k = 'cau_tipo' THEN RETURN _v IN ('dinheiro', 'imovel'); END IF;
  IF _k = 'cau_valor' THEN RETURN _v ~ '^[0-9]{1,7}([.][0-9]{1,2})?$' AND _v::numeric > 0; END IF;
  IF _k = 'cau_meses' THEN RETURN _v ~ '^[0-9]{1,2}$' AND _v::integer BETWEEN 1 AND 12; END IF;
  RETURN true;
END $$;
-- locacao_montagem_pega: base 20261114120000_locacao_montar_contrato.sql
CREATE OR REPLACE FUNCTION public.locacao_montagem_pega(_id uuid) RETURNS public.locacoes
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _l public.locacoes := public.locacao_pega(_id);
BEGIN
  PERFORM public.locacao_exige(_l, ARRAY['minuta'], 'contratos');
  IF _l.garantia NOT IN ('fiador', 'caucao', 'outras', 'seguro_fianca', 'loft') THEN
    RAISE EXCEPTION 'Ainda não há modelo para esta garantia: anexe a minuta feita por fora.' USING ERRCODE = '22023';
  END IF;
  IF cardinality(public.locacao_docs_faltando(_l)) > 0 THEN
    RAISE EXCEPTION 'Montar contrato travado: documentos obrigatórios pendentes' USING ERRCODE = '22023';
  END IF;
  RETURN _l;
END $$;
-- locacao_montagem_ler: base 20261114120000_locacao_montar_contrato.sql
CREATE OR REPLACE FUNCTION public.locacao_montagem_ler(_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _l public.locacoes := public.locacao_montagem_pega(_id); _o public.organizations; _c jsonb;
BEGIN
  SELECT * INTO _o FROM public.organizations WHERE id = _l.organization_id;
  SELECT campos INTO _c FROM public.locacao_montagem WHERE locacao_id = _id AND organization_id = _l.organization_id;
  RETURN jsonb_build_object('campos', coalesce(_c, '{}'::jsonb),
    'contrato', public.locacao_contrato_valores(_l),
    'administradora', jsonb_build_object('nome', coalesce(_o.razao_social, _o.nome),
      'cnpj', _o.cnpj, 'creci', _o.creci, 'cidade', _o.cidade, 'uf', _o.uf),
    'modelos', (SELECT coalesce(jsonb_object_agg(k, public.locacao_modelo_json(public.locacao_modelo_atual(_l.organization_id, k))), '{}'::jsonb)
                  FROM unnest(ARRAY['fiador', 'caucao_dinheiro', 'caucao_imovel', 'seguro_porto', 'seguro_pottencial',
                    'seguro_tokio', 'seguro_almada', 'loft']) k WHERE public.locacao_modelo_garantia_ok(_l.garantia, k)),
    'apolice', (SELECT a.numero FROM public.locacao_anexos a WHERE a.locacao_id = _l.id AND a.tipo = 'apolice'
                 ORDER BY a.enviado_em DESC LIMIT 1));
END $$;
-- locacao_minuta_registrar: base 20261130120000_locacao_minuta_anexada.sql
DROP FUNCTION IF EXISTS public.locacao_minuta_registrar(uuid, text, text, text);
CREATE OR REPLACE FUNCTION public.locacao_minuta_registrar(_id uuid, _path text, _nome text, _origem text,
  _modelo_chave text DEFAULT NULL, _modelo_versao integer DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _l public.locacoes := public.locacao_pega(_id); _m jsonb; _v integer; _o text; _nm text; _novo uuid;
  _mod public.locacao_modelos;
BEGIN
  PERFORM public.locacao_exige(_l, ARRAY['minuta'], 'contratos');
  IF _origem IS NULL OR _origem NOT IN ('anexo', 'gerada') THEN
    RAISE EXCEPTION 'Origem inválida.' USING ERRCODE = '22023';
  END IF;
  IF _path IS NULL OR _path !~ ('^' || _l.organization_id::text || '/' || _l.id::text || '/minutas/[0-9a-f-]{36}[.](pdf|doc|docx)$')
     OR NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'locacao-documentos' AND o.name = _path) THEN
    RAISE EXCEPTION 'Arquivo da minuta não encontrado.' USING ERRCODE = '22023';
  END IF;
  IF _origem = 'gerada' THEN
    IF _path !~ '[.]pdf$' OR NOT public.locacao_modelo_garantia_ok(_l.garantia, _modelo_chave) THEN
      RAISE EXCEPTION 'Esta garantia não tem modelo para gerar a minuta (PDF): anexe a minuta feita por fora.' USING ERRCODE = '22023';
    END IF;
    _mod := public.locacao_modelo_atual(_l.organization_id, _modelo_chave);
    IF _modelo_versao IS DISTINCT FROM (CASE WHEN _mod.organization_id IS NULL THEN 0 ELSE _mod.versao END) THEN
      RAISE EXCEPTION 'O modelo de contrato mudou enquanto você montava: recarregue e gere de novo.' USING ERRCODE = '22023';
    END IF;
  ELSIF _modelo_chave IS NOT NULL OR _modelo_versao IS NOT NULL THEN
    RAISE EXCEPTION 'Origem inválida.' USING ERRCODE = '22023';
  END IF;
  -- Tipo real gravado no storage tem de bater com a extensão (o navegador declara o tipo no upload).
  IF (SELECT o.metadata->>'mimetype' FROM storage.objects o WHERE o.bucket_id = 'locacao-documentos' AND o.name = _path)
     IS DISTINCT FROM (CASE WHEN _path LIKE '%.pdf' THEN 'application/pdf'
       WHEN _path LIKE '%.doc' THEN 'application/msword'
       ELSE 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' END) THEN
    RAISE EXCEPTION 'O tipo do arquivo não confere com a extensão (envie PDF ou Word).' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.locacao_minutas WHERE storage_path = _path) THEN
    RAISE EXCEPTION 'Arquivo já registrado.' USING ERRCODE = '22023';
  END IF;
  _m := _l.minuta;
  _o := CASE WHEN coalesce((_m->>'externa')::boolean, false) AND _origem = 'anexo' THEN 'externa' ELSE _origem END;
  _nm := left(coalesce(nullif(btrim(_nome), ''), 'minuta'), 200);
  -- A locação está travada (FOR UPDATE em locacao_pega): duas gravações seguidas não pegam o mesmo número.
  SELECT coalesce(max(versao), 0) + 1 INTO _v FROM public.locacao_minutas WHERE locacao_id = _l.id;
  INSERT INTO public.locacao_minutas (organization_id, locacao_id, versao, origem, storage_path, nome_arquivo, enviado_por,
    modelo_chave, modelo_versao)
  VALUES (_l.organization_id, _l.id, _v, _o, _path, _nm, auth.uid(), CASE WHEN _o = 'gerada' THEN _modelo_chave END,
    CASE WHEN _o = 'gerada' THEN _modelo_versao END) RETURNING id INTO _novo;
  PERFORM public.locacao_evento(_l, 'contratos', 'Minuta v' || _v || ' '
    || CASE _o WHEN 'gerada' THEN 'gerada pelo modelo "' || _mod.titulo || '" (texto '
         || CASE WHEN _modelo_versao = 0 THEN 'padrão' ELSE 'v' || _modelo_versao END || ') e guardada' WHEN 'externa' THEN 'de outra RE/MAX anexada'
       ELSE 'anexada' END || ' (' || _nm || ')');
  -- Versão nova depois do envio: volta a "elaborando" para o corretor conferir a versão nova.
  IF coalesce(_m->>'estado', '') IN ('', 'com_corretor', 'aprovada') THEN
    IF _m->>'estado' IN ('com_corretor', 'aprovada') THEN
      PERFORM public.locacao_evento(_l, 'contratos', 'Minuta volta a "elaborando": a versão v' || _v
        || ' ainda não foi enviada ao corretor');
    END IF;
    _m := _m || jsonb_build_object('estado', 'elaborando');
    UPDATE public.locacoes SET minuta = _m, atualizado_em = now() WHERE id = _l.id;
  ELSE
    UPDATE public.locacoes SET atualizado_em = now() WHERE id = _l.id;
  END IF;
  RETURN jsonb_build_object('id', _novo, 'versao', _v);
END $$;
REVOKE ALL ON FUNCTION public.locacao_minuta_registrar(uuid, text, text, text, text, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.locacao_minuta_registrar(uuid, text, text, text, text, integer) TO authenticated;
-- locacao_pos_acao: base 20261110120000_locacao_fase1.sql
CREATE OR REPLACE FUNCTION public.locacao_pos_acao(_id uuid, _acao text, _dados jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _l public.locacoes := public.locacao_pega(_id); _p jsonb; _hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  _c public.locacao_config; _data date; _alerta text; _desc text; _s text;
BEGIN
  PERFORM public.locacao_exige(_l, ARRAY['pos_assinatura', 'chaves'], 'vistoria');
  _p := _l.pos; _dados := coalesce(_dados, '{}'::jsonb);
  IF _acao = 'vistoria_pedida' THEN _p := _p || jsonb_build_object('vistoria_pedida', _hoje); _desc := 'Vistoria pedida';
  ELSIF _acao = 'laudo_assinado' THEN
    IF _p->>'vistoria_pedida' IS NULL AND NOT coalesce((_p->>'vist_junto')::boolean, false) THEN
      RAISE EXCEPTION 'Registre antes o pedido de vistoria.' USING ERRCODE = '22023';
    END IF;
    _p := _p || jsonb_build_object('laudo_em', _hoje); _desc := 'Laudo de vistoria assinado';
  ELSIF _acao = 'contestacao' THEN _p := _p || jsonb_build_object('contestacao_em', _hoje); _desc := 'Contestação de vistoria registrada';
  ELSIF _acao = 'seguro' THEN
    _p := _p || jsonb_build_object('seguro_em', _hoje, 'apolice', left(nullif(btrim(coalesce(_dados->>'apolice', '')), ''), 60));
    _desc := 'Seguro contratado' || coalesce(' — apólice ' || nullif(btrim(coalesce(_dados->>'apolice', '')), ''), '');
  ELSIF _acao = 'condominio_aviso' THEN _p := _p || jsonb_build_object('condominio_aviso', _hoje); _desc := 'Condomínio avisado';
  ELSIF _acao = 'sem_condominio' THEN _p := _p || jsonb_build_object('sem_condominio', true); _desc := 'Imóvel sem condomínio';
  ELSIF _acao = 'mudanca' THEN
    _data := (_dados->>'data')::date;
    IF _data IS NULL THEN RAISE EXCEPTION 'Informe a data da mudança.' USING ERRCODE = '22023'; END IF;
    _p := _p || jsonb_build_object('mudanca', _data); _desc := 'Mudança agendada para ' || to_char(_data, 'DD/MM/YYYY');
  ELSIF _acao = 'titularidade_aplica' THEN
    _s := _dados->>'servico';
    IF _s IS NULL OR _s NOT IN ('cpfl', 'saae', 'gas') THEN RAISE EXCEPTION 'Serviço inválido' USING ERRCODE = '22023'; END IF;
    _p := jsonb_set(_p, ARRAY['tit', _s, 'aplica'], to_jsonb(coalesce((_dados->>'aplica')::boolean, true)), true);
    _desc := upper(_s) || CASE WHEN coalesce((_dados->>'aplica')::boolean, true) THEN ' se aplica' ELSE ' não se aplica' END;
  ELSIF _acao = 'pronto_para_chaves' THEN
    _c := public.locacao_cfg(_l.organization_id);
    IF _l.etapa <> 'pos_assinatura' THEN RAISE EXCEPTION 'Ação não disponível nesta etapa.' USING ERRCODE = '22023'; END IF;
    IF _c.seguro_incendio_obrigatorio AND _p->>'seguro_em' IS NULL THEN
      RAISE EXCEPTION 'Seguro incêndio obrigatório nesta imobiliária: registre o seguro antes.' USING ERRCODE = '22023';
    END IF;
    UPDATE public.locacoes SET pos = _p WHERE id = _id;
    _l := public.locacao_mover(_id, 'chaves', false, NULL);
    PERFORM public.locacao_evento(_l, 'vistoria', 'Pós-assinatura concluída — aguardando entrega das chaves');
    RETURN jsonb_build_object('ok', true, 'etapa', _l.etapa);
  ELSIF _acao = 'entregar_chaves' THEN
    _c := public.locacao_cfg(_l.organization_id);
    IF _l.garantia = 'seguro_fianca' AND NOT public.locacao_tem_apolice(_l.id) THEN
      RAISE EXCEPTION 'Apólice pendente — anexe para liberar a entrega de chaves.' USING ERRCODE = '22023';
    END IF;
    _data := coalesce((_dados->>'data')::date, _hoje);
    IF _data > _hoje + 1 OR _data < _hoje - 120 THEN RAISE EXCEPTION 'Data de entrega inválida.' USING ERRCODE = '22023'; END IF;
    IF _c.seguro_incendio_obrigatorio AND _p->>'seguro_em' IS NULL THEN
      RAISE EXCEPTION 'Seguro incêndio obrigatório nesta imobiliária: registre o seguro antes.' USING ERRCODE = '22023';
    END IF;
    IF _p->>'laudo_em' IS NULL THEN
      IF NOT _c.chave_antes_do_laudo THEN
        RAISE EXCEPTION 'Laudo de vistoria ainda não assinado: entrega da chave bloqueada nesta imobiliária.' USING ERRCODE = '22023';
      END IF;
      _alerta := ' (ALERTA: laudo de vistoria ainda não assinado)';
    END IF;
    UPDATE public.locacoes SET pos = _p, chave_em = _data WHERE id = _id;
    _l := public.locacao_mover(_id, 'comissao', false, NULL);
    UPDATE public.locacoes SET etapa_desde = _data::timestamp AT TIME ZONE 'America/Sao_Paulo' WHERE id = _id RETURNING * INTO _l;
    PERFORM public.locacao_evento(_l, 'vistoria', 'Chaves entregues em ' || to_char(_data, 'DD/MM/YYYY') || coalesce(_alerta, ''));
    RETURN jsonb_build_object('ok', true, 'etapa', _l.etapa, 'alerta', _alerta IS NOT NULL);
  ELSE
    RAISE EXCEPTION 'Ação inválida' USING ERRCODE = '22023';
  END IF;
  UPDATE public.locacoes SET pos = _p, atualizado_em = now() WHERE id = _id RETURNING * INTO _l;
  PERFORM public.locacao_evento(_l, 'vistoria', _desc);
  RETURN jsonb_build_object('ok', true, 'etapa', _l.etapa);
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow THEN
  RAISE EXCEPTION 'Valor inválido' USING ERRCODE = '22023';
END $$;
-- locacao_detalhe: base 20261130120000_locacao_minuta_anexada.sql
CREATE OR REPLACE FUNCTION public.locacao_detalhe(_id uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $$
DECLARE _org uuid := public.locacao_ctx(); _l public.locacoes; _f text[];
BEGIN
  SELECT * INTO _l FROM public.locacoes WHERE id = _id AND organization_id = _org;
  IF _l.id IS NULL OR NOT public.locacao_pode_ver(_l) THEN
    RAISE EXCEPTION 'Sem acesso a esta locação.' USING ERRCODE = '42501';
  END IF;
  _f := public.locacao_docs_faltando(_l);
  RETURN public.locacao_json(_l) || jsonb_build_object(
    'checklist', to_jsonb(public.locacao_checklist_l(_l)),
    'faltando', to_jsonb(_f),
    'partes', public.locacao_partes_json(_l),
    'docs_completa', public.locacao_docs_completos_em(_l) IS NOT NULL,
    'docs_completos_em', public.locacao_docs_completos_em(_l),
    'captador_nome', (SELECT p.nome FROM public.profiles p WHERE p.id = _l.captador_id),
    'documentos', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'item', d.item, 'nome_arquivo', d.nome_arquivo,
        'enviado_em', d.enviado_em, 'leitura', lr.status, 'leitura_erro', lr.erro, 'leitura_em', lr.atualizado_em,
        'preenchidos', lr.preenchidos) ORDER BY d.enviado_em), '[]')
        FROM public.locacao_documentos d LEFT JOIN public.locacao_doc_leituras lr ON lr.documento_id = d.id
       WHERE d.locacao_id = _l.id AND d.removido_em IS NULL),
    'contrato', jsonb_build_object(
      'exige', public.locacao_exige_contrato(_l),
      'valores', public.locacao_contrato_valores(_l),
      'origem', coalesce((SELECT c.origem FROM public.locacao_contrato_dados c WHERE c.locacao_id = _l.id), '{}'::jsonb),
      'faltando', to_jsonb(public.locacao_contrato_faltando(_l))),
    'minutas', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', v.id, 'versao', v.versao, 'origem', v.origem,
        'nome_arquivo', v.nome_arquivo, 'enviado_em', v.enviado_em, 'enviado_por_nome', pr.nome,
        'modelo_chave', v.modelo_chave, 'modelo_versao', v.modelo_versao)
        ORDER BY v.versao DESC), '[]')
        FROM public.locacao_minutas v LEFT JOIN public.profiles pr ON pr.id = v.enviado_por WHERE v.locacao_id = _l.id),
    'anexos', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'tipo', x.tipo, 'nome_arquivo', x.nome_arquivo,
        'numero', x.numero, 'enviado_em', x.enviado_em, 'enviado_por_nome', pr.nome) ORDER BY x.enviado_em DESC), '[]')
        FROM public.locacao_anexos x LEFT JOIN public.profiles pr ON pr.id = x.enviado_por WHERE x.locacao_id = _l.id),
    'apolice_pendente', _l.garantia = 'seguro_fianca' AND NOT public.locacao_tem_apolice(_l.id),
    'andamentos', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'etapa', a.etapa, 'texto', a.texto,
        'aguardando', a.aguardando, 'criado_em', a.criado_em, 'criado_por_nome', pc.nome, 'resolvido_em', a.resolvido_em,
        'resolvido_por_nome', pr.nome, 'resolucao', a.resolucao) ORDER BY a.criado_em DESC), '[]')
        FROM public.locacao_andamentos a LEFT JOIN public.profiles pc ON pc.id = a.criado_por
        LEFT JOIN public.profiles pr ON pr.id = a.resolvido_por WHERE a.locacao_id = _l.id),
    'eventos', (SELECT coalesce(jsonb_agg(jsonb_build_object('em', e.em, 'etapa', e.etapa, 'papel', e.papel,
        'descricao', e.descricao, 'ator_nome', pr.nome) ORDER BY e.em, e.id), '[]')
        FROM public.locacao_eventos e LEFT JOIN public.profiles pr ON pr.id = e.ator_id WHERE e.locacao_id = _l.id));
END $$;
COMMIT;
